pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are fine only if zero; gaps below the item-size
    // mass threshold are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that can't fit the lookahead item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits (waste relative to perfect packing).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation.
    score += (open_bins_count as f64) * (2.0 + 30.0 / (post_residual as f64 + 5.0));

    // New-bin candidate: only attractive when it enables a near-perfect
    // pack or no existing bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 80 {
            score -= 45.0;
        }
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Prefer bins already below mean residual (keeps residuals balanced,
    // avoids many half-empty bins).
    score -= 3.0 * (mean_residual - post_residual as f64).max(0.0);

    // Late in stream: waste matters more, keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1..10) can use are toxic.
    if post_residual < 10 {
        score -= 25.0; // perfectly consumed or near-perfect fit is excellent
    } else if post_residual < 20 {
        score += 6.0; // small awkward gap
    } else if post_residual < 35 {
        score += 2.5;
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Penalize leaving a gap just below the next item's size (blocks the lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0 + (next_item_size - post_residual) as f64 * 0.15;
    }
    // Reward reserving space exactly for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.4;

    // Mean residual coupling: when open bins are already full-ish, prefer tighter fits.
    score += (mean_residual - post_residual as f64) * 0.1;

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            2.0
        } else {
            0.0
        };
        score = 55.0 + pressure - (fitting_bins_count as f64) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with progress
    let t = pr / cap;
    let g = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    let coupling = t * t * (1.0 - t) * (1.0 + g);

    // Reward tight fits (small post_residual) more strongly as stream advances
    let mut score = base - 6.0 * coupling * cap - progress * (cap - pr) * 0.15;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            // smooth reward when lookahead also fits
            score -= (pr - nx).min(cap * 0.5) * 0.1 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Favor bins tighter than average residual
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Slight bias against opening a new bin
    if bin_residual == bin_capacity {
        score += 4.0 + progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with a non-linear polynomial shaping of tightness
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - t));

    // Smooth coupling of post_residual with stream progress
    let progress_coupling = pr * t * (1.0 - t) * 4.0;
    score -= 0.6 * progress_coupling;

    // Penalize small-but-not-zero residuals quadratically (dead space)
    let dead = if next_item_size > 0.0 as u32 && (next_item_size as f64) > pr {
        let gap = next_item_size as f64 - pr;
        gap * gap * 0.05
    } else {
        0.0
    };
    score += dead;

    // Reward near-full fills smoothly
    score -= 12.0 * (norm_pr * norm_pr * norm_pr);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 5.0 * (1.0 - t);
    }

    // Mild pressure to prefer open bins over opening new ones as bins accumulate
    score += (open_bins_count as f64).ln().max(0.0) * (0.3 + 0.7 * t);

    // Prefer bins whose residual is close to the item (tight fit), smoothly
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 4.0 * tight * tight;

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 * (1.0 - pr / cap);
    }

    // Mean residual context: penalize deviating far from mean residual
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small leftover dead space (< 10) is nearly useless; penalize creating it
    // unless it's an exact fit (already handled).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item would fit into this bin's post-residual,
    // reward the placement (keeps chains going).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.08 * next_item_size as f64;
        } else if next_item_size >= bin_residual {
            // Next item can't fit here even before placement; this bin's
            // remaining space is dead weight for the lookahead horizon.
            score += 2.0;
        } else {
            // Next item fits now but not after placement: mild penalty.
            score += 1.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // this empty bin's potential; make it attractive only when it's genuinely
    // better than poor fits. Base cost for a fresh bin.
    if bin_residual == bin_capacity {
        // A new bin is fine when few bins are open or mean residual is high
        // (existing bins are full-ish).
        score += 15.0 - 0.5 * mean_residual - 1.0 * open_bins_count as f64;
        // If no open bin can fit the item at all, new bin must win.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer consolidating into existing bins when many are open.
        score -= 0.3 * open_bins_count as f64;
    }

    // Global state: if mean residual across open bins is large, prefer the bin
    // whose residual is closest to the mean (balanced depletion) — approximate
    // by penalizing deviation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be conservative with new bins
    // (favor filling existing ones); late in the stream, allow slightly more
    // freedom since long-term fragmentation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 5.0 * progress;
    } else {
        score += 3.0 * (1.0 - progress);
    }

    // Mild preference for larger post_residual among otherwise-equal bins is
    // already in the base score; add small noise-free tiebreak on residual.
    score += 0.01 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1, realistically >= next_item)
    // can use are pure waste. Penalize small unusable gaps super-linearly.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(50) } else { 10 };
    if post_residual < dead_threshold {
        // unusable sliver: heavy penalty proportional to wasted capacity
        score += (dead_threshold - post_residual) as f64 * 4.0;
    }
    if post_residual == 0 {
        // perfect fit: strong reward
        score -= 60.0;
    } else if post_residual < 10 {
        // nothing (min size 1..100 unknown, but tiny gaps rarely reusable)
        score += 25.0;
    }

    // Reward exact-ish tight fits: residual close to zero relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // competition: mildly prefer bins that others cannot take later? keep neutral tilt
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when all open bins would leave bad gaps,
    // otherwise penalize opening new bins (open_bins_count pressure).
    if bin_residual == bin_capacity {
        let best_case_gap = bin_residual.saturating_sub(item_size) as f64;
        if best_case_gap < dead_threshold as f64 {
            // opening a fresh bin and nearly filling it is great
            score -= 30.0;
        } else {
            score += 20.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        }
    } else {
        // using an existing bin relieves open-bin pressure
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item exactly fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack < 10 {
            score += 8.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap unusable by the known next item
        score += 5.0;
    }

    // Mild preference to fill earlier-opened bins first (progress pressure)
    score += (step_index as f64 / (total_items as f64).max(1.0)) * 3.0;

    // Pull toward bins with below-average residual (denser bins first)
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // Penalize post_residuals that are too small to be useful for any future item
    // (assume minimum useful item size ~10), but reward moderately large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: unusable gap
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0; // marginal gap: only fits very small items
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else {
        // larger residuals are valuable; slight reward scaled by size
        score -= (post_residual as f64 - 20.0) * 0.3;
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Open bins pressure: discourage spreading across many bins,
    // but soften near the end of the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 - 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; prefer placing into below-mean-residual bins.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - res) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin is a safe fallback; make it
    // moderately attractive so we avoid stuffing items into bad gaps, but
    // not so attractive that we always open new bins.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let cap = bin_capacity as f64;
    let mut score = r;

    // Smooth non-linear coupling: quadratic/cubic in post residual, modulated by progress
    let poly = r * r * (1.0 - r) * 4.0; // hump peaking at r=0.5
    score -= 12.0 * poly * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    let tightness = (1.0 - r).powi(3);
    score -= 10.0 * tightness * progress;

    // Penalize dead space that can't fit average future item
    let avg_next = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
    let unusable = ((avg_next - post_residual as f64).max(0.0)) / cap;
    score += 8.0 * unusable * unusable;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: mildly penalize early, mildly favor late
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - progress) - 1.5 * progress;
        // penalize opening new bin if a decent fit exists (mean residual large)
        score += 0.02 * mean_residual * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 9.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Congestion term: many open bins -> prefer consolidating
    score += 0.05 * open_bins_count as f64 * r;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual gets strong discount.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (post_residual as f64);

    // Penalize leaving awkward small gaps that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if next item can use the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64) / (post_residual as f64).max(1.0);
        } else {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.25 * waste.min(60.0);
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // later, allow opening new bins more freely when residuals are poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 15.0 * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        // New bin candidate: base penalty plus residual (full).
        score += new_bin_penalty;
        score -= 2.0 * open_bins_count as f64;
        // Opening a new bin is attractive if existing residuals are large relative to item.
        if mean_residual > (item_size as f64) * 1.5 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight preference as open bins grow (fill them).
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer using larger residual bins when item is large (avoid opening bins for big items).
    if item_size > 50 && bin_residual >= item_size {
        score -= 0.2 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly or nearly: strong reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack.min(60.0);
            if post_residual == next_item_size {
                score -= 500.0; // chain of perfect fits
            }
        } else {
            // Post-residual is dead space for the next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 2.0;
        }
    } else {
        // Last item: only tightness matters.
        score -= 50.0;
    }

    // Compare against mean residual: bins tighter than average are precious,
    // loose bins should absorb the item.
    if (bin_residual as f64) < mean_residual {
        score += 30.0; // this bin is already tight, prefer others
    } else {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e. this call happens with many fitting bins meaning competition is high,
    // push new bin down; when fitting bins are scarce the subtraction above
    // already favors existing bins, so make new bin moderately costly).
    if bin_residual == bin_capacity {
        score += 250.0;
        // Early in the stream, opening bins is cheaper (builds diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 150.0 * (1.0 - progress);
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 100.0;
        }
        // Don't open a new bin if many bins already fit the item.
        if fitting_bins_count > 2 {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
