}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste minimization).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 100.0 + (5 - post_residual) as f64 * 10.0;
    } else if post_residual <= 10 {
        score -= 30.0 + (10 - post_residual) as f64 * 3.0;
    }

    // 2-step lookahead: exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 400.0; // perfect chain: next item fills this bin exactly
        } else if diff <= 10.0 {
            score -= 80.0 - diff * 4.0;
        } else {
            // penalize leaving residuals that nothing useful can use
            score += diff * 0.5;
        }
        // If next item cannot fit here, leaving a huge residual is worse
        // relative to the stream's typical residual scale (mean_residual).
        if post < nxt && post > 0.0 {
            score += 40.0 + (nxt - post) * 0.3;
        }
    } else {
        // Last item: strongly prefer closing bins out.
        score -= 200.0;
    }

    // Compare against mean residual: bins tighter than average are more valuable.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        if post_f < mean_residual {
            score -= (mean_residual - post_f) * 0.6;
        } else {
            score += (post_f - mean_residual) * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - progress * 40.0;
        if fitting_bins_count > 0 {
            score += 100.0; // some open bin fits; opening new is wasteful
        }
        if next_item_size > 0 && (bin_capacity as f64 - post_residual as f64).abs() < 1.0 {
            // still allow fresh bin for perfect future chains
            score -= 60.0;
        }
    }

    // Slight preference for fuller bins as stream progresses.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are unusable for the smallest
    // future item (size 1) are fine, but residuals that are too small for typical
    // items yet nonzero are the worst outcome. Penalize tiny non-zero gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tight-fit reward scaled by how snugly the item sits in the bin.
    let snugness = item_size as f64 / bin_residual.max(1) as f64;
    score -= snugness * 20.0;

    // Dead space relative to capacity: large leftovers are wasteful unless the
    // bin is a fresh empty bin candidate.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 15.0;

    // Lookahead: if the next item fits exactly in the post-residual, this is a
    // golden placement; reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild bonus proportional to leftover after that.
        score -= 5.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: the leftover may become dead space; penalize
        // proportionally to how stranded it is.
        score += 8.0;
    }

    // Open-bins pressure: prefer consolidating into existing bins when many are
    // open; make new bins less attractive as open_bins_count grows.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor (large post_residual) or nothing fits elsewhere.
    if bin_residual == bin_capacity {
        // Base attractiveness of a fresh bin: neutral-ish, slightly above a
        // perfect fit, below a bad fit.
        score = 30.0
            + open_bins_count as f64 * 0.5
            - (next_item_size as f64 / bin_capacity as f64) * 10.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;
    }

    // Mean residual coupling: when open bins are on average quite full
    // (small mean residual), prefer placing into them to consolidate.
    if bin_residual != bin_capacity {
        score += (mean_residual - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as f64; // 8 harmonic octaves of residual
    score += class * 6.0;

    // Perfect-fit harmonic classes: residual that is a clean divisor-ish remainder
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual % 10 == 0 {
        score -= 40.0;
    } else if post_residual % 5 == 0 {
        score -= 15.0;
    }

    // Integer-division threshold: small post_residual relative to item granularity
    let small_grain = post_residual / 10; // usable slots of size 10
    score -= small_grain as f64 * 4.0;

    // Lookahead coupling: does post_residual accommodate the next item's class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.8;
            // harmonic bonus if next item leaves another clean remainder
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 25.0;
            }
        } else {
            // next item cannot fit here: penalize wasting this bin's future
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (mean_residual / 20.0 + 1.0);
        // opening a bin is good if mean residual is small (bins are tight)
        score += 30.0 + mean_residual * 2.0 - crowded * 3.0 - progress * 10.0;
        // never open a new bin if a near-perfect fit exists elsewhere
        if item_size % 10 == 0 && bin_residual - item_size < 10 {
            score += 200.0;
        }
    } else {
        // prefer tighter existing bins mildly
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Late-stream consolidation: favor filling bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (1..=10) are heavily penalized; mid gaps (11..=25) mildly penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 2.0; // dead space: worst when tiny
    } else if post_residual <= 25 {
        score += 15.0;
    } else if post_residual >= 40 {
        // Large leftover space is flexible; reward it slightly.
        score -= 8.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can still host the next item: keep it attractive.
            let slack = post_residual - next_item_size;
            score -= 12.0 - slack as f64 * 0.15;
        } else {
            // Next item won't fit here: residual is likely to become dead space.
            score += (post_residual as f64).min(35.0) * 0.6;
        }
    } else {
        // Last item: closing a bin fully is ideal.
        score -= 20.0;
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin fits; avoid opening a new bin unless the fit is terrible.
        score -= 25.0;
        if post_residual <= 30 {
            score -= 15.0;
        }
    }

    // --- Open bins count pressure ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    score += bin_pressure;

    // Deviation from mean residual: prefer bins whose residual stays near the pack norm.
    score += (mean_residual - post_residual as f64).abs() * 0.25;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of opening one. Attractive when existing fits are poor
        // (dead-space penalties above push bad fits above this), unattractive otherwise.
        score = 95.0 + item_size as f64 * 0.3 - (post_residual as f64) * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 40.0; // strongly discourage abandoning the sole fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the minimum
    // item size (1..100 interface => treat < item_size of smallest plausible
    // item) are wasted. Penalize tiny unusable gaps heavily.
    let dead_threshold: f64 = 10.0; // smallest historical item size
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 200.0 + (dead_threshold - post_residual as f64) * 20.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if (post_residual as f64) < 0.25 * bin_capacity as f64 {
        score -= 40.0 * (1.0 - post_residual as f64 / (0.25 * bin_capacity as f64));
    }

    // Penalize large leftover gaps that likely become dead space later.
    if post_residual > 60 {
        score += (post_residual - 60) as f64 * 1.5;
    }

    // Open-bin pressure: prefer consolidating into existing bins over
    // opening new ones as the number of open bins grows.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if next item fits snugly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap => gap likely dead.
        score += 25.0;
    }

    // Mean-residual coupling: bins far below mean residual are "loose";
    // prefer filling bins tighter than average.
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // New-bin candidate: baseline score so it loses to good fits but wins
    // over terrible fits (large dead-space penalties above).
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 1.5 - (post_residual as f64);
    }

    score
}

