        // But if current bin's post-residual would be unusable dead space, new bin is less bad.
        if post_residual < 10 && post_residual > 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 10.0; // fresh bin always fits next item
        }
    }

    // Mild preference for bins with residual close to mean (balance residuals).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, scaled by capacity.
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: this bin absorbs both items
        }
        // Penalize residuals too small for next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    } else {
        // Last item: pure tightness, strongly reward minimal residual.
        score -= (bin_capacity - post_residual) as f64 * 0.3;
    }

    // Relative-to-mean coupling: bins with residual near mean are "typical";
    // prefer filling bins with below-mean residual (they are scarcer space).
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.25;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make empty bin attractive only when item is large
    // relative to capacity or no good fits exist; otherwise penalize it.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 || (next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.7) {
            score -= 10.0;
        } else {
            score += 30.0 + 20.0 * (1.0 - frac);
        }
    }

    // Late-stream consolidation: as stream progresses, favor closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: larger item fraction of the consumed space lowers score.
    score -= (item / cap) * 30.0;

    // Perfect or near-perfect closure bonus.
    if post == 0.0 {
        score -= 60.0;
    } else if post <= 5.0 {
        score -= 25.0;
    } else if post < 10.0 {
        score -= 12.0;
    }

    // Lookahead: if the next item can reuse the leftover space, this is a great placement.
    if next > 0.0 {
        if next <= post {
            // Chain fit: leftover is usable, strongly reward, scaled by how snug it is.
            score -= 20.0 + 25.0 * (next / post.max(1.0));
        } else {
            // Leftover becomes dead space relative to the next item; penalize proportionally,
            // more so late in the stream when consolidation matters.
            score += (post - next).min(post) * (0.5 + progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin for a poor fit later.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 45.0 + 30.0 * (1.0 - post / cap);
    }

    // Global fragmentation pressure: when many open bins have large mean residual,
    // prefer filling existing bins over spreading; when mean residual is small,
    // opening a fresh bin is less costly.
    if !is_new_bin {
        score -= mean_residual * 0.15;
    } else {
        // New-bin candidate: baseline penalty so it only wins when fits are bad.
        score += 35.0;
        // Late in the stream or when open bins are nearly full, a new bin is cheap.
        score -= 40.0 * progress * (1.0 - mean_residual / cap).max(0.0);
        // If current item is large and leaves little waste anywhere, new bin is fine.
        score -= (item / cap) * 20.0;
        if next > 0.0 && next <= post {
            score -= 15.0;
        }
    }

    // Avoid hoarding many half-empty bins: with many open bins, favor consolidation.
    if !is_new_bin && open_bins_count > 3 {
        score -= 3.0 * (open_bins_count as f64).ln();
    }

    // Mild preference for bins whose residual is close to the item (snugness).
    let snug = 1.0 - (residual - item).abs() as f64 / cap;
    score -= snug * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: waste penalized more as stream progresses
    let waste_coupling = pr_norm * pr_norm * (0.5 + 2.5 * progress);
    score += 40.0 * waste_coupling;

    // Perfect-fit reward, stronger early and late (smooth sinusoidal shaping)
    let perfect_fit = (pr_norm * std::f64::consts::PI).cos();
    score -= 30.0 * perfect_fit * perfect_fit * (1.0 - pr_norm);

    // Lookahead: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0) / cap;
        let proximity = 1.0 - ((pr - nxt).abs() / cap).min(1.0);
        score -= 20.0 * proximity * proximity * (1.0 - fits_next);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 25.0 * progress;
    }

    // Mild penalty for bins with residual far from mean (fragmentation signal)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline, penalized slightly more early
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..=8

    // Reward near-perfect fits heavily (post_residual in lowest class).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= eighth {
        score -= 120.0;
    } else if post_residual <= quarter {
        score -= 40.0;
    } else if post_residual > bin_capacity - quarter {
        // Large dead space: penalize quadratically.
        let dead = post_residual as f64 / cap;
        score += 60.0 * dead * dead;
    }

    // Modulo arithmetic on post_residual: small residues relative to common item
    // size bands (10..80 multiples) are more reusable.
    let m10 = post_residual % 10;
    if m10 == 0 && post_residual > 0 {
        score -= 15.0; // residue is a multiple of 10 -> likely reusable
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 / (1.0 + slack / 10.0);
        } else {
            // Next item won't fit here; slight penalty for leaving odd residue.
            score += 5.0;
        }
    } else {
        // Last item: any bin that fits is equally fine; prefer tightest (post_residual already small).
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and stream is early (many items left to use the fresh bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual as f64 / cap; // large = bad fit for item
        // Favor new bin when the placement leaves huge residue and much stream remains.
        score += 150.0 - 200.0 * bad_fit * (1.0 - progress);
    }

    // Prefer consolidating into fewer bins when many are open with mean residual
    // close to item size (avoid bin sprawl).
    if open_bins_count > 1 && bin_residual != bin_capacity {
        let gap = (mean_residual - item_size as f64).abs();
        score -= 20.0 / (1.0 + gap / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1, realistically >= next_item)
    // can use are pure waste. Penalize small unusable gaps super-linearly.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(50) } else { 10 };
    if post_residual < dead_threshold {
        // unusable sliver: heavy penalty proportional to wasted capacity
        score += (dead_threshold - post_residual) as f64 * 4.0;
    }
    if post_residual == 0 {
        // perfect fit: strong reward
        score -= 60.0;
    } else if post_residual < 10 {
        // nothing (min size 1..100 unknown, but tiny gaps rarely reusable)
        score += 25.0;
    }

    // Reward exact-ish tight fits: residual close to zero relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 10.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // competition: mildly prefer bins that others cannot take later? keep neutral tilt
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when all open bins would leave bad gaps,
    // otherwise penalize opening new bins (open_bins_count pressure).
    if bin_residual == bin_capacity {
        let best_case_gap = bin_residual.saturating_sub(item_size) as f64;
        if best_case_gap < dead_threshold as f64 {
            // opening a fresh bin and nearly filling it is great
            score -= 30.0;
        } else {
            score += 20.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
        }
    } else {
        // using an existing bin relieves open-bin pressure
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item exactly fits the post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack < 10 {
            score += 8.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap unusable by the known next item
        score += 5.0;
    }

    // Mild preference to fill earlier-opened bins first (progress pressure)
    score += (step_index as f64 / (total_items as f64).max(1.0)) * 3.0;

    // Pull toward bins with below-average residual (denser bins first)
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // --- 2-step lookahead: exact match between post_residual and next item ---
    if next_item_size > 0 {
        let pr = post_residual as i64;
        let nx = next_item_size as i64;
        let diff = (pr - nx).abs();

        if diff == 0 {
            // Perfect 2-chain: this bin will be exactly filled by the next item.
            score -= 60.0;
        } else if diff <= 5 {
            score -= 25.0;
        } else if diff <= 15 {
            score -= 8.0;
        } else if pr < nx {
            // Next item won't fit here; residual becomes dead space if small.
            if pr > 0 && pr < 10 {
                score += 20.0;
            }
        } else {
            // Next item fits with slack: mild reward proportional to tightness.
            score -= (20.0 - (diff.min(20) as f64)) * 0.4;
        }

        // Penalize leaving residual that neither fits next item nor is tiny.
        if pr >= nx && diff > 15 {
            score += 3.0;
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, prefer using it ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 + 10.0 * progress;
    }

    // --- Penalize large dead space relative to mean residual ---
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += (pr - mean_residual).max(0.0) * 0.15;
    }

    // --- New-bin candidate calibration ---
    if is_new_bin {
        // Neutral-ish baseline: slightly worse than a good fit, better than a bad one.
        score += 12.0;
        // Early in the stream, prefer consolidating into open bins.
        score += 10.0 * (1.0 - progress);
        // If many bins are open, discourage opening yet another unless necessary.
        score += 2.0 * (open_bins_count as f64).min(20.0);
        // If no other bin fits (this is the only candidate), the +12 is fine;
        // a poor fit elsewhere (large dead space) will exceed it naturally.
    }

    // Small tie-breaker favoring tighter fits overall.
    score += (post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit pressure: reward tight fits nonlinearly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize small dead space band: residuals 1..=9 are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving large residual
            // that could have held it (wasted complementarity).
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 2.0;
            }
        }
    }

    // New-bin candidate logic: opening a bin is costly early (few bins) but
    // attractive when item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin.
        score += 15.0;
        // Reward opening when item is large and mean residual can't host it well.
        score -= 25.0 * item_frac * item_frac;
        // Late in stream, prefer filling existing bins (less time to amortize).
        score += 20.0 * progress;
        // If many bins open, opening one more is cheaper structurally.
        score -= 0.5 * (open_bins_count as f64).sqrt();
        // If this item is the only one that fits nowhere well (last-chance pressure
        // is absent for new bin), keep moderate.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 3.0; // new bin can also host next item
        }
    } else {
        // Existing-bin bonus when it's the only fitting bin (avoid forcing new bin).
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Reward bins with residual below mean (denser bins first).
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
        // Slight bonus for keeping mean residual low overall.
        score -= 0.05 * (bin_capacity as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic-ish penalty on post residual (dead space), modulated by stream progress.
    // Early on, keep residuals flexible; late, aggressively minimize post_residual.
    let mut score = pr * (1.0 + 1.5 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Smooth non-linear coupling: reward tight fits more strongly as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.3 + progress);

    // Last-chance bonus: strongly favor this bin if it's the only one that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 50.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Lookahead: if next item can use the post_residual, reward leaving useful space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let waste = pr - nx;
            score -= 12.0 * (1.0 - waste / cap) * (0.4 + 0.6 * progress);
        } else {
            // smooth penalty when next item cannot use leftover space
            let gap = (nx - pr) / cap;
            score += 8.0 * gap * (1.0 - progress);
        }
    }

    // Slight dispersion penalty: avoid concentrating on bins far from mean residual.
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: penalize mildly early (prefer using open bins), allow late when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) - 10.0 * progress * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes via modulo arithmetic.
    // Residuals in (0,10) are nearly unusable dead space -> heavy penalty.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0;
    }
    // Class residuals by capacity fraction: post_residual in [10,33) = "small class",
    // [33,50) = "half class", [50,100) = "large class". Reward half-class (best reuse).
    if pr >= 40 && pr <= 60 {
        score -= 12.0;
    } else if pr >= 25 && pr < 40 {
        score -= 4.0;
    }
    // Modulo-10 harmony: residual that is a multiple of 10 pairs well with
    // integer-sized items (sizes drawn 1..100 with 10-aligned mass).
    if pr % 10 == 0 && pr > 0 {
        score -= 3.0;
    }
    // Integer-division threshold: pr / 10 tells how many 10-blocks remain.
    let blocks = pr / 10;
    score -= blocks as f64 * 0.5;

    // Perfect fit bonus.
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item can't use this bin's remainder: penalize large leftovers
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = cap * 0.55 + open_bins_count as f64 * 2.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 8.0;
        }
        // If many bins fit the item, definitely don't open a new one.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild preference for bins below mean residual (balance loads).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item (1..100 stream, but keep a conservative threshold) are
    // pure waste. Penalize sharply when post_residual falls into a "dead zone".
    if post_residual > 0 {
        // dead zone: gap too small to be reusable by typical items
        if post_residual < 12 {
            score += 40.0; // unusable sliver
        } else if post_residual <= 25 {
            score += 12.0; // hard-to-fill gap
        } else if post_residual <= 50 {
            score += 3.0;  // moderately reusable
        } else {
            score -= 6.0;  // large residual stays flexible
        }
    } else {
        // Perfect fit: strongly reward zero waste.
        score -= 50.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Last-chance bonus: if this is the only bin that fits, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        // extra pressure when many bins are already open (consolidate)
        score -= (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins. This applies a penalty to the new-bin candidate
    // implicitly by rewarding fits here, and directly when residual matches
    // a fresh bin.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and bins accumulate.
        score += 30.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
        // But if no open bin can fit at all, allow opening (fitting_bins_count
        // includes this candidate, so ==1 means nothing else fits).
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    } else if fitting_bins_count == 1 {
        // Sole existing fitting bin: strong preference over opening new bin.
        score -= 20.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // gap blocks the known next item: penalize
            score += 8.0;
        }
    }

    // Deviation from mean residual: prefer bins whose post state stays near
    // the mean to keep the bin population homogeneous.
    let post_f = post_residual as f64;
    score += 0.15 * (post_f - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by wasted potential
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate scoring: penalize when open bins are underutilized.
        score += 15.0 + mean_residual * 0.5 + open_bins_count as f64 * 2.0;
        // Early in the stream, opening bins is cheaper; late, expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    } else {
        // Existing bin: reward keeping mean residual low (balance across bins).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Time horizon: as stream progresses, favor tighter packing exponentially.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Smooth non-linear polynomial coupling with stream progress:
    // early in stream, mild preference for tight fits; late in stream, strong preference.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= progress_poly * 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize dead space quadratically, modulated by how unusable it is
    // relative to typical item sizes (use item_size as proxy for scale).
    let dead = norm_pr;
    score += 60.0 * dead * dead * dead * (1.0 + progress);

    // Lookahead: reward if next item fits into post residual (smooth logistic-like)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = (next_item_size as f64) / cap;
        score -= 25.0 * (1.0 - fit_quality) * (1.0 - fit_quality);
    } else if next_item_size > 0 {
        // next item cannot fit: penalize proportionally to the gap
        let gap = (next_item_size as f64 - pr) / cap;
        score += 30.0 * gap * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0 * (1.0 + progress_poly);
    }

    // Mild penalty for spreading across many open bins (encourage consolidation),
    // scaled smoothly by how far this bin's residual deviates from the mean.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Slight preference for fuller bins overall (lower residual => lower score)
    score -= 0.1 * (cap - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual divided into
    // capacity fractions (1/8 granularity) — small classes are dead space.
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth.max(1); // 0..=8 harmonic class
    match class {
        0 => score -= 60.0,          // near-perfect fit, highly desirable
        1 => score -= 40.0,          // leftover <= 1/8 capacity, still great
        2 => score -= 20.0,          // decent fit
        3 => {}                      // neutral band
        4 => score += 15.0,          // half-full leftover: mediocre
        5 => score += 30.0,
        6 => score += 45.0,
        7 => score += 60.0,          // large unusable gap for typical items
        _ => score += 75.0,          // empty-ish bin class (new-bin candidate)
    }

    // Modulo arithmetic: leftover that is a multiple of common item sizes
    // (divisible by 10) is reusable by future items; reward it.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    // Odd, non-round leftovers are hard to fill; penalize slightly.
    if post_residual % 10 != 0 && post_residual > 0 && post_residual < bin_capacity {
        score += 6.0;
    }

    // Lookahead compatibility: if the next item fits exactly into the
    // post_residual, this placement is part of a perfect chain.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 55.0;
        } else if slack <= eighth {
            score -= 30.0;
        } else {
            score -= (slack as f64).min(25.0) * 0.3;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this leftover at all: penalize proportionally.
        score += ((next_item_size - post_residual) as f64) * 0.25;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin for a poor alternative.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only allow opening a new bin when the item is large (would leave a
    // harmonically small leftover in an existing bin anyway) or late in the
    // stream when bin count is already high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        let mut new_bin_bonus = 0.0;
        if item_frac > 0.7 {
            new_bin_bonus += 45.0; // big items pair well with a fresh bin
        }
        if progress > 0.8 && open_bins_count > 4 {
            new_bin_bonus += 25.0; // consolidation phase, keep bins tidy
        }
        if mean_residual < cap * 0.25 && item_frac > 0.5 {
            new_bin_bonus += 20.0; // existing bins are nearly full anyway
        }
        score -= new_bin_bonus;
        // Base penalty so a fresh bin is only chosen when bonuses justify it.
        score += 40.0;
    }

    // Mild preference for tighter (fuller) bins among equals.
    score += (mean_residual - post_residual as f64).abs() * 0.05;
    // Small step-based dither to break ties deterministically.
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that no realistic item can use are wasted.
    // Penalize heavily when post_residual is small but nonzero (unusable gap).
    if post_residual > 0 {
        // If the next item can't fit into the gap, the leftover is dead space.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // Very small absolute gaps (< 10) are almost surely unusable.
        if post_residual < 10 {
            score += 15.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 20.0;
    }

    // Reward tight fits relative to the bin itself.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // opening yet another bin spreads items thin and creates many small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin, which is almost always better.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity (would leave a big, reusable residual elsewhere anyway) or when
    // open bins are already numerous and fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin by default; relax when item is huge
        // or existing bins are badly fragmented.
        score += 25.0 - 20.0 * large_item - 10.0 * fragmentation;
    } else {
        // Slight penalty scaled by how much worse this bin's residual is vs mean.
        if (bin_residual as f64) > mean_residual {
            score += 0.3 * (bin_residual as f64 - mean_residual);
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is excellent; reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins where the next item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Tight two-item packing: post_residual close to next_item_size is best.
            score -= 200.0 - ((post_residual - next_item_size) as f64) * 0.5;
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            let waste = post_residual as f64 / next_item_size as f64;
            score += 40.0 * (1.0 - waste.min(1.0));
        }
    }

    // Penalize tiny unusable residuals (dead space below minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, less so when it's early
    // in the stream or the current fit is very loose.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 120.0;
        if next_item_size > 0 && item_size >= next_item_size {
            new_bin_penalty -= 30.0; // big item now, smaller next: fine to open
        }
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0; // no alternative
        }
        score += new_bin_penalty * (0.5 + 0.5 * (1.0 - progress));
    }

    // Mild preference for consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: normalize stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let horizon = 0.5 + 0.5 * progress; // later steps => tighter packing pressure

    // Reward good fits: small post_residual is good, but only if item actually fits here.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: reward bins whose post_residual can host the next item (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap * horizon;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 20.0 * horizon;
    }

    // Penalize bins that are already fragmented relative to the mean residual
    // (avoid unbalanced waste accumulation).
    let deviation = bin_residual as f64 - mean_residual;
    score += 0.15 * deviation * deviation * horizon;

    // New-bin candidate handling: opening a bin is expensive early, cheap late.
    if bin_residual == bin_capacity {
        let base_cost = 40.0 * (1.0 - 0.6 * horizon);
        // Opening is more attractive when existing bins fit poorly (large item, few options).
        let poor_options = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let big_item_bonus = (item_size as f64 / 100.0) * 25.0 * poor_options;
        score += base_cost - big_item_bonus;
    }

    // Mild preference for fuller bins when many bins are open (consolidation).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + progress * (1.0 - progress) * 4.0 * (1.0 - norm_pr));

    // Penalize large dead space more aggressively as the stream matures
    score += norm_pr * norm_pr * cap * progress;

    // Reward tight fits (small post_residual) with a non-linear bonus
    score -= (1.0 - norm_pr).powi(3) * cap * 0.5;

    // Last-chance bin bonus: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap;
    }

    // New-bin candidate: penalize slightly so open bins are preferred unless fit is poor
    if bin_residual == bin_capacity {
        score += cap * (0.25 + 0.5 * progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= (pr - next_item_size as f64).abs().min(cap) * 0.3;
    }

    // Mild penalty when bin residual deviates from mean residual across open bins
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // capacity fraction remaining

    // Dead-space classes: residuals that are hard to fill get penalized.
    // Small unusable slivers (1..=9) are dead space -> strong penalty.
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }
    // Harmonic "good" classes: residuals that are common item complements
    // (multiples of 10 and near-half capacity) get rewards.
    let residue_class = post_residual % 10;
    if residue_class == 0 {
        score -= 6.0;
    } else if residue_class >= 5 {
        score -= 2.0;
    } else {
        score += 3.0; // awkward residue class
    }

    // Integer-division thresholds on post_residual / 10 (harmonic band index).
    let band = post_residual / 10;
    match band {
        0 => score += 8.0,            // nearly full bin: excellent
        1 => score -= 4.0,            // 10-19 left: very usable
        2 | 3 => score -= 1.0,        // moderate
        4 => score += 2.0,            // mid-capacity: mediocre
        5 => score -= 3.0,            // exactly half: flexible
        6..=8 => score += 1.0,
        _ => {}                        // large residual: near-empty bin
    }

    // Fraction-based coupling with mean residual: prefer bins tighter than average.
    let mean_frac = mean_residual / cap;
    if frac < mean_frac {
        score -= 4.0 * (mean_frac - frac);
    } else {
        score += 3.0 * (frac - mean_frac);
    }

    // Last chance: only one bin fits -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits in post_residual (chain packing),
    // penalize if next item would be blocked by this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 7.0;
            // Harmonic bonus if next item lands on a clean class too.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer existing bins in general; opening a bin is costly.
        score += 12.0 + open_bins_count as f64 * 0.5;
        // But if many open bins exist and none is a good fit (many fitting bins
        // means fragmentation), a fresh bin may be fine; soften slightly late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 6 {
            score -= 6.0 + 3.0 * progress;
        }
    }

    // Mild stream-progress scaling: later, tighten up more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    score = post_residual as f64 * 1.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly or nearly: strong reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 - slack.min(60.0);
            if post_residual == next_item_size {
                score -= 500.0; // chain of perfect fits
            }
        } else {
            // Post-residual is dead space for the next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 2.0;
        }
    } else {
        // Last item: only tightness matters.
        score -= 50.0;
    }

    // Compare against mean residual: bins tighter than average are precious,
    // loose bins should absorb the item.
    if (bin_residual as f64) < mean_residual {
        score += 30.0; // this bin is already tight, prefer others
    } else {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e. this call happens with many fitting bins meaning competition is high,
    // push new bin down; when fitting bins are scarce the subtraction above
    // already favors existing bins, so make new bin moderately costly).
    if bin_residual == bin_capacity {
        score += 250.0;
        // Early in the stream, opening bins is cheaper (builds diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 150.0 * (1.0 - progress);
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 100.0;
        }
        // Don't open a new bin if many bins already fit the item.
        if fitting_bins_count > 2 {
            score += 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual (wasted space), superlinearly.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo_waste = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.5 * combo_waste;
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving a gap that is neither useful nor zero.
        score += 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly everywhere else. Base penalty for opening a bin.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 90.0 + 0.2 * open_bins_count as f64;
        // Late in the stream, discourage proliferation of open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_penalty += 40.0 * progress;
        // If next item is large, a fresh bin is valuable as a reserve.
        if next_item_size >= bin_capacity / 2 {
            new_bin_penalty -= 30.0;
        }
        score += new_bin_penalty;
    }

    // Favor filling bins whose residual is already below the mean (consolidating waste).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.4 * dev;
    }

    // Global balance: if many bins are open, prefer placements that shrink residuals
    // of the emptiest bins (large bin_residual).
    score += 0.15 * (bin_residual as f64 - mean_residual) * (open_bins_count as f64 / 10.0).min(1.5);

    // Early-stream exploration: prefer tighter fits more aggressively at the start.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 40.0 * (1.0 - progress) * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let cap = bin_capacity as f64;
    let mut score = r;

    // Smooth non-linear coupling: quadratic/cubic in post residual, modulated by progress
    let poly = r * r * (1.0 - r) * 4.0; // hump peaking at r=0.5
    score -= 12.0 * poly * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    let tightness = (1.0 - r).powi(3);
    score -= 10.0 * tightness * progress;

    // Penalize dead space that can't fit average future item
    let avg_next = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
    let unusable = ((avg_next - post_residual as f64).max(0.0)) / cap;
    score += 8.0 * unusable * unusable;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: mildly penalize early, mildly favor late
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - progress) - 1.5 * progress;
        // penalize opening new bin if a decent fit exists (mean residual large)
        score += 0.02 * mean_residual * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 9.0 * fit_quality * fit_quality;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Congestion term: many open bins -> prefer consolidating
    score += 0.05 * open_bins_count as f64 * r;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into modulo-10 residue classes.
    let class = post_residual % 10;
    // Residues that are "usable" by typical small items (multiples of 10/20 align with common sizes).
    let class_bonus: f64 = match class {
        0 => 6.0,       // perfectly harmonic residual
        5 => 3.0,       // half-harmonic
        1 | 2 | 8 | 9 => 1.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: post_residual in "decades"
    let decade = post_residual / 10;
    score -= (decade as f64).powf(0.5) * 1.5;

    // Reward near-perfect fills strongly
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            // harmonic classes of the chain residual
            if next_post % 10 == 0 { score -= 8.0; }
            if next_post <= 5 { score -= 5.0; }
            score -= (next_post as f64) * 0.15;
        } else {
            // next item won't fit here; penalize leaving large dead space
            if post_residual > 30 { score += (post_residual as f64 - 30.0) * 0.3; }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus pressure from open bins
        score += 12.0 + (open_bins_count as f64).sqrt() * 2.0;
        // allow new bin if mean residual is small (open bins nearly full)
        score -= (mean_residual / 10.0) * 1.2;
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Mild preference for tighter bins among fitting ones
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mean-residual coupling: if this bin is far below mean residual, it's a poor target
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.1;

    // Modulo coupling between item and residual (harmonic gcd-like bonus)
    let g = gcd_like(item_size, post_residual);
    score -= g as f64 * 0.4;

    score
}

fn gcd_like(a: u32, b: u32) -> u32 {
    let mut a = a;
    let mut b = b;
    while b > 0 {
        let t = a % b;
        a = b;
        b = t;
    }
    a
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 20 {
        // Medium gaps: mildly risky unless the lookahead item can use them.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Lookahead coupling: reward if the next item fits exactly in post_residual.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 80.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Open-bin pressure: discourage scattering into many bins unless the fit is good.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate: make it attractive only when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tightness_penalty = if post_residual < 10 { 0.0 } else { 30.0 };
        score -= 40.0 - tightness_penalty + mean_residual * 0.2;
    }

    // Prefer bins with below-average residual (tighter bins) for large items.
    if (item_size as f64) > mean_residual * 0.7 {
        score += 5.0;
    }

    // Slight stream-progress tilt: later in the stream, be more conservative with new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits leaving small remainder
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.8;
    }
    // Next item does NOT fit in the leftover: penalize creating dead space
    else if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.5;
    }

    // Reward tight fits relative to mean residual of open bins
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.3;
    } else {
        score += (pr - mean_residual) * 0.15;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good alternative exists
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 20.0 + (fitting_bins_count as f64) * 2.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.5;

    // Strongly prefer minimal post residual (best-fit core)
    score += pr * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 25.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0 * (post_residual as f64) / (next_item_size as f64).max(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize crowding when many bins are open and this bin is far from mean residual.
    let deviation = (bin_residual as f64) - mean_residual;
    score += 0.3 * deviation;

    // Time horizon: early in stream, be conservative (favor filling existing bins);
    // later, allow opening new bins for large items.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    if item_size > 60 && progress > 0.5 {
        score -= 8.0;
    }
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();

    // New-bin candidate: only attractive if item is large and no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > 70 && fitting_bins_count == 0 {
            score -= 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prn = pr / cap;
    let fill = 1.0 - prn;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = prn * (1.0 + 0.6 * progress) - 1.4 * fill * fill * (1.0 + 0.8 * progress);

    // Reward tight fits non-linearly
    let fit_ratio = it / br.max(1.0);
    score -= 1.2 * fit_ratio * fit_ratio * (1.0 - progress);

    // Penalize dead space near mid-range residuals (smoothly)
    let mid = (prn - 0.5) * (prn - 0.5);
    score += 0.5 * mid * (1.0 - progress);

    // Lookahead: reward leaving space for the next item smoothly
    if next_item_size > 0 {
        let nx = (next_item_size as f64).min(cap);
        let slack = (pr - nx).max(0.0) / cap;
        score -= 0.8 * slack * slack;
        // penalize if next item won't fit here
        let miss = (nx - pr).max(0.0) / cap;
        score += 0.6 * miss * miss;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 1.0;
    }

    // Mild penalty for opening new bins when many already open
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // residue classes (dead space) are penalized more than linearly.
    let pr = post_residual;
    if pr > 0 {
        let class = pr % 10;
        // residue classes 1..=4 are near-unusable dead space
        if class >= 1 && class <= 4 {
            score += (5 - class) as f64 * 2.5;
        }
        // residue classes 8..=9 still pairable with tiny items: slight reward
        if class >= 8 {
            score -= 1.5;
        }
    }

    // Perfect fill is golden.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Quotient classes: post_residual / 10 thresholds (capacity fractions).
    let q = post_residual / 10;
    if q == 0 {
        score -= 8.0; // very tight fit
    } else if q >= 5 {
        score += 6.0; // half-empty bin kept: wasteful
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 45.0;
        } else if diff <= 5 {
            score -= 18.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // leftover cannot host the next item: mild penalty scaled by size gap
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // mean residual across open bins is small (existing bins are nearly full)
    // or the item would leave a very bad residue everywhere.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = open_bins_count as f64;
        // base reluctance to open new bins
        score += 25.0;
        // if open bins are tight (small mean residual), new bin becomes better
        score -= (cap - mean_r).max(0.0) * 0.35;
        // early in stream, be more willing to open bins
        score -= (1.0 - progress) * 10.0;
        // many open bins: prefer consolidation
        score += openness * 1.2;
    }

    // Mild preference for filling bins with larger residual when many bins compete.
    if fitting_bins_count > 3 {
        score -= (bin_residual as f64) * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (unusable leftovers) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 12.0;
    } else if post_residual > 10 && post_residual < item_size {
        // Medium gap that likely cannot host the next item either.
        if (next_item_size as u32) > post_residual && next_item_size > 0 {
            score += 8.0;
        }
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many bins when a tight fit exists.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    score += ((bin_residual as f64 - item_size as f64) / bin_capacity as f64) * 5.0;

    // Lookahead: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size as u32 == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= (post_residual - next_item_size as u32) as f64 * 0.3;
    }

    // New-bin candidate: keep it attractive only when existing fits are bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 10 && (next_item_size == 0 || (next_item_size as u32) > post_residual);
        if bad_fit && fitting_bins_count > 0 {
            score -= 15.0;
        } else {
            score += 5.0 + (open_bins_count as f64) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward exact match of post_residual to next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item: big bonus.
        if post_residual == next_item_size {
            score -= 120.0;
        } else {
            // Proportional penalty for mismatch between leftover and next item.
            score += diff * 0.6;
            // If the next item cannot fit in the leftover, penalize dead space harder.
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.8;
            }
        }
        // If next item fits and leaves a small remainder again, extra reward.
        if next_item_size <= post_residual {
            let second_leftover = post_residual - next_item_size;
            score -= (second_leftover as f64).min(20.0) * 0.5;
        }
    } else {
        // Last item: just minimize leftover, slightly reward tight fits.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tighter",
    // prefer filling those first to consolidate waste.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 + item_size as f64 * 0.2;
    }

    // Penalize new-bin candidate mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
        // But if no open bin fits well (post_residual huge relative to capacity),
        // the base post_residual already makes this attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Slight progression term: early on, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 - open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is unusable for typical items (post_residual < 10).
    if post_residual < 10 {
        score -= 15.0; // perfectly sealed bin is great
    } else if post_residual < 25 {
        score += 8.0; // small awkward gap is bad
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            score += 5.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if mean residual across open bins is very low (nothing fits well), relax.
        score -= 0.5 * mean_residual;
        // Early in stream, allow more bins; late in stream, be frugal.
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - t);
    }

    // Mild penalty for bin proliferation: keep open bins consolidated.
    score += 1.5 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps the pool of usable gaps uniform) unless it's a tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping.
    let mut score = pr;

    // Quadratic/cubic coupling of post_residual with stream progress:
    // early on, prefer tight fits mildly; late in stream, punish large residuals harder.
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) + norm_pr * norm_pr * norm_pr * (2.0 * progress);
    score += poly * cap * 0.5;

    // Reward filling a bin nearly exactly, smoothly via exponential of normalized residual.
    score -= 8.0 * (-norm_pr * 4.0).exp() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits in post_residual, reward leaving useful space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - (pr - nxt) / cap;
            score -= 5.0 * fit_quality * (0.5 + progress);
        } else {
            // Penalize residuals that cannot host the next item proportionally to waste.
            score += 2.0 * (pr / cap) * progress;
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (denser bins).
    score += 1.5 * ((pr - mean_residual) / cap).clamp(-1.0, 1.0);

    // Discourage spreading across many open bins late in the stream.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: keep neutral-ish but slightly worse than a good existing fit.
    if bin_residual == bin_capacity {
        score += 6.0 - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f; // 0.0 .. 1.0

    // Dead-space classes: residual in (0, 10) is nearly useless -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Harmonic bins: residual that is a multiple of small item classes (10s) is reusable.
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 12.0;
    }

    // Coupling with next item: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0;
        } else if next_item_size < post_residual {
            let nfrac = (post_residual - next_item_size) as f64 / cap_f;
            // penalize by leftover after chaining, extra if it lands in dead zone
            score += nfrac * 25.0;
            if post_residual - next_item_size < 10 && post_residual - next_item_size > 0 {
                score += 30.0;
            }
        } else {
            // next item cannot follow here: slight penalty scaled by waste
            score += frac * 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += cap_f * 0.55;
        // cheaper to open new bin when existing bins are crowded / many open bins
        score -= (open_bins_count as f64).min(10.0) * 3.0;
        // if item is large relative to mean residual, new bin is more attractive
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
    } else {
        // prefer tighter existing bins: reward small residual
        score -= (bin_residual as f64) * 0.15;
    }

    // Stream progression: late in stream, consolidate harder (favor existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 20.0;
    } else {
        score += progress * 15.0;
    }

    // Mean-residual coupling: if this bin's post-residual is far below mean, it's a tight fit -> good.
    score -= (mean_residual - post).clamp(-50.0, 50.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are the enemy.
    // Any post_residual that can never be filled by a future item (gap < 10
    // under classic regime, or < smallest plausible item) is heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize gaps that the lookahead item cannot use (wasted for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Tightness reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins early,
    // but relax pressure as the stream progresses (consolidation late).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (3.0 - 2.0 * progress);

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (new bin would add a whole bin).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when this item fits poorly
    // anywhere else (large residual waste avoided by a fresh bin).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0 + open_bins_count as f64 * 2.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 30.0 * fill_ratio;
        // If few bins fit the item, opening new is more acceptable.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Mild preference toward bins whose residual is close to the item
    // (best-fit character), scaled by mean residual context.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: perfect match with next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            // next item fits here too: mild reward proportional to leftover after both.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item will NOT fit in this residual: penalize dead space,
            // worse when dead space is small (nearly wasted).
            let dead = (next_item_size - post_residual) as f64;
            score += dead * (1.0 + 60.0 / (dead + 5.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Prefer tighter bins relative to mean residual across open bins.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Mild penalty for opening new bins when many are open and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 30.0 * (1.0 - progress);
    }

    // Favor bins that already have content when residuals are otherwise similar.
    if bin_residual < bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Exact fit is nearly free.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item can fit exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // partial lookahead fit, scaled by how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // next item won't fit here; penalize leaving awkward gaps
            let gap_ratio = post_residual as f64 / (next_item_size as f64);
            if gap_ratio > 0.35 && post_residual < 30 {
                score += 8.0 * gap_ratio;
            }
        }
    } else {
        // Last item: waste minimization dominates.
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin generally, but relax the
    // penalty when existing bins fit poorly (high mean residual waste potential
    // or item is large relative to typical residual).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 55.0;
        // If no existing bin leaves enough room for a plausible follow-up,
        // opening fresh is less bad.
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty -= 10.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += 20.0 * progress;
        // Many open bins with small residuals: opening new is fine.
        if mean_residual < 25.0 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    } else {
        // Mild penalty for spreading across many bins when residuals are large.
        if (bin_residual as f64) > mean_residual + 20.0 {
            score += 5.0;
        }
    }

    // Discourage using large-residual bins for tiny items (save space for big items).
    if item_size < 25 && bin_residual > 60 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth non-linear polynomial coupling between post_residual and stream progress
    let poly = pr / cap;
    let coupling = poly * poly * (0.5 + 0.5 * progress) * cap;

    score += 0.6 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = (item_size as f64 / cap).powi(2);
    score -= tightness * (10.0 + 20.0 * progress);

    // Penalize waste when lookahead item can use the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 8.0 * progress;
    } else if next_item_size > post_residual {
        score += 0.3 * (next_item_size as f64 - pr);
    }

    // Penalize dead space relative to mean residual (quadratic)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Slight preference for consolidating into fewer bins early
    score += (open_bins_count as f64) * (1.0 - progress) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: how "usable" is the leftover space?
    // Class residuals into bands via integer division on capacity fractions.
    let quarter = bin_capacity / 4;           // 25
    let half = bin_capacity / 2;              // 50
    let eighth = bin_capacity / 8;            // 12

    // Perfect-fit reward: residual exactly fills a harmonic fraction class.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= eighth {
        score -= 120.0;
    } else if post_residual <= quarter {
        score -= 40.0;
    } else if post_residual <= half {
        score -= 10.0;
    } else {
        score += 30.0; // large dead space is bad
    }

    // Modulo arithmetic: residuals that are multiples of small harmonic units
    // (e.g. 10, 20, 25) are more likely to be filled by future items.
    let harmonic_unit = quarter / 5; // 5
    if post_residual % (2 * harmonic_unit) == 0 && post_residual > 0 {
        score -= 25.0;
    }
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let nxt_res = post_residual - next_item_size;
            score -= 60.0 * (1.0 - nxt_res as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 20.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer tighter existing bins: closeness of item to residual (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 50.0 * tightness;

    // Early stream: be slightly conservative about wasting big residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && post_residual > half {
        score += 40.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when open bins have small residuals
    // or the item fits nowhere well.
    if bin_residual == bin_capacity {
        score = 80.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0;
        }
        score += 10.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Residuals in [1, 12] are nearly unusable dead space: punish hard.
    if post_residual >= 1 && post_residual <= 12 {
        score += 40.0 * (13.0 - post_residual as f64);
    }
    // Moderate residuals [13, 30] are mildly wasteful.
    else if post_residual > 12 && post_residual <= 30 {
        score += 8.0;
    }
    // Perfect / near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // --- Lookahead coupling (k=2) ---
    // If the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.5;
        if slack == 0.0 {
            score -= 20.0; // chain of perfect fits
        }
    }
    // Next item cannot use the leftover: dead space likely terminal.
    if next_item_size > post_residual {
        score += 6.0;
    }

    // --- Last-chance bin pressure ---
    // If this is the only bin that fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    // Many competing bins: prefer tighter fits (relative tightness bonus).
    if fitting_bins_count > 1 {
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * (1.0 - tightness) * (1.0 - tightness);
    }

    // --- Open-bin pressure ---
    // Encourage filling existing bins rather than proliferating bins.
    score += open_bins_count as f64 * 0.8;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Base penalty keeps it behind good fits, but mean_residual signals
        // that open bins are cluttered with unusable space.
        score += 25.0 + mean_residual * 0.1;
        // Late in the stream, slight preference to consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // --- Mean-residual coupling ---
    // If the average residual across open bins is small, we are doing well;
    // prefer bins close to the mean (avoid outliers creating dead zones).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the item exactly fills the bin (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item size,
    // so the next item can also fit perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }

    // Penalize wasted residual relative to mean residual of open bins:
    // leaving more slack than average creates dead space.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward bins whose residual is "tight" relative to the mean (well-packed).
    if (post_residual as f64) < mean_residual {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make an empty bin slightly attractive by
    // default (its post_residual == capacity), but penalize opening a new bin
    // when the item would fit reasonably well elsewhere.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 500.0; // still allow new bin if it enables perfect next fit
        }
    }

    // Mild penalty for small unusable residuals (dead space 1..=10).
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on leftover space.
    score += 0.8 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: if the next item fits into the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        // Perfect chaining: next item exactly fills the remainder.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead-end residue: penalize small unusable scraps unless they are near zero.
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 5.0 * fill_ratio * (open_bins_count as f64).ln().max(1.0);

    // Global residual pressure: if mean residual is low, avoid wasting space anywhere.
    score += 0.05 * (post_residual as f64 - mean_residual).max(0.0);

    // Time horizon: early in the stream, be more tolerant of loose fits (keep flexibility);
    // late in the stream, prioritize exact packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * fill_ratio;

    // New-bin candidate: make it unattractive unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If no open bin fits well (large post residuals elsewhere), allow opening a new bin.
        if mean_residual < item_size as f64 && fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && post_residual == 0 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 12.0 * poly;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 8.0 * gap * gap;
        // Reward leaving exactly enough space for the next item
        let fit_gap = (pr - nxt).abs() / cap;
        score -= 6.0 * (1.0 - fit_gap) * (1.0 - fit_gap) * progress;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Mild pressure relative to mean residual across open bins
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: prefer opening a bin early, discourage late
    if bin_residual == bin_capacity {
        score += 20.0 - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly favor bins that end with small residual.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Harmonic class logic: classify post_residual into capacity-fraction classes.
    let quarter = bin_capacity / 4; // 25
    let eighth = bin_capacity / 8;  // 12
    // Exact-fill class is golden.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Small post-residual classes (<= 1/8, <= 1/4) are good dead-space outcomes.
    if post_residual <= eighth {
        score -= 30.0;
    } else if post_residual <= quarter {
        score -= 10.0;
    } else if post_residual % quarter == 0 {
        // Residuals aligned to quarter boundaries are reusable targets.
        score -= 8.0;
    } else {
        // Penalize awkward residual classes via modulo structure.
        score += (post_residual % eighth) as f64 * 0.6;
    }

    // Integer-division threshold: how many next-size items would fit in post_residual.
    if next_item_size > 0 {
        let fits_next = post_residual / next_item_size.max(1);
        if fits_next >= 1 {
            // Reward bins whose leftover can host the lookahead item.
            score -= 12.0 * fits_next as f64;
        } else {
            // Leftover cannot host next item: dead space penalty scaled by waste.
            score += 6.0;
        }
        // Perfect pairing: post_residual exactly equals next item size.
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is huge
    // relative to mean residual spread (i.e., open bins are too full to matter).
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If many bins could fit, opening new bins is wasteful.
        score += fitting_bins_count as f64 * 5.0;
    }

    // Mild preference for filling fuller bins (lower residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Crowding: with many open bins, discourage spreading.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, minimum item size)
    // are unusable and count as full waste; treat them as heavily penalized.
    if post_residual < 10 {
        // Perfect closure is excellent: reward strongly.
        score -= 40.0;
    } else if post_residual <= 20 {
        // Small gaps are nearly dead space: penalize extra.
        score += 15.0;
    }

    // Reward tight fits (item fills a large fraction of the bin's residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Open-bins pressure: discourage spreading across many bins when
    // mean residual is already high (bins are fragmented).
    if open_bins_count > 4 && mean_residual > 30.0 {
        score += 3.0 * (open_bins_count as f64).ln();
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral baseline, slightly penalized so we only open
    // a new bin when existing fits are truly bad.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if the next item is large, a fresh bin is attractive for pairing.
        if next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Lookahead: if the post residual exactly matches the next item,
    // this placement enables a perfect follow-up fit.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap just barely too small for the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where item exactly fills residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual,
    // this bin creates a perfect chain placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }

    // If next item fits into post_residual (chain continuation), reward mildly
    // proportional to how snugly it fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 && next_item_size > post_residual {
        let dead = post_residual as f64;
        // Dead space is worse if it's small-but-unusable (wasted sliver).
        if dead > 0.0 {
            score += 0.5 * dead + (30.0 * dead / (dead + next_item_size as f64));
        }
    }

    // Relative to mean residual: prefer bins tighter than average when
    // residuals are plentiful, but don't over-punish.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when no good chain placement exists. Penalize it
    // modestly so tight fits into existing bins win, but keep it viable
    // when post_residual of existing bins would be tiny unusable slivers.
    if bin_residual == bin_capacity {
        // Base penalty: opening new bins is expensive.
        score = bin_capacity as f64 + 150.0;
        // But if the current item is large and would leave a big awkward
        // residual in any existing bin, a fresh bin is fine.
        if item_size >= 50 {
            score -= 40.0;
        }
        // Lookahead: opening a new bin then placing next item cleanly
        // (item + next <= capacity) is a good chain start.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 100.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // Many open bins: discourage opening more.
        score += 5.0 * open_bins_count as f64;
    }

    // Small tie-breaker toward tighter bins.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: minimize wasted space (post_residual), weighted by how "dead" the space is
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2));

    // Reward tight fits strongly
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; mild penalty for leaving awkward gap
            score += 3.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // Among multiple fitting bins, prefer fuller ones (smaller residual)
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Global state: penalize opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are quite full or item is large
        let mean_load = bin_capacity as f64 - mean_residual;
        let pressure = mean_load / bin_capacity as f64;
        if pressure > 0.75 || fitting_bins_count == 0 {
            score -= 15.0; // opening a new bin is reasonable
        } else {
            score += 10.0 + 20.0 * (1.0 - pressure); // discourage wasting a fresh bin
        }
    }

    // Time horizon: early in the stream, be more conservative (keep bins flexible);
    // late in the stream, pack aggressively (accept tighter fits, less worry about flexibility)
    let flexibility_weight = 1.0 - progress;
    score += flexibility_weight * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual is small but nonzero (awkward dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Slight preference to balance load across bins early on
    score += (1.0 - progress) * 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: penalize wasted residual, with non-linear growth (dead space is super-linearly bad)
    let mut score = pr * (1.0 + 0.015 * (pr / cap) * (pr / cap) * 100.0);

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, keep residuals flexible; late, prefer tight fills.
    let flex = 1.0 - progress * progress;
    score += flex * 12.0 * (pr / cap) * (1.0 - pr / cap);

    // Reward tight fits smoothly (small post_residual relative to capacity)
    let tightness = (1.0 - pr / cap).powi(3);
    score -= 8.0 * tightness;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // mild crowding penalty when many bins fit the item
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits the post-residual, reward; else penalize smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 6.0 * snug * (nx / cap);
        } else {
            let gap = (nx - pr) / cap;
            score += 5.0 * gap * gap;
        }
    }

    // Encourage consolidation when many bins are open: prefer bins below mean residual
    score += 0.05 * (pr - mean_residual) * (open_bins_count as f64).sqrt();

    // New-bin candidate: make an empty bin moderately attractive only when
    // the item fits poorly anywhere else (handled via fitting count) —
    // otherwise penalize spreading across bins.
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * progress * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward near-exact fits: post_residual in {0, 1..=3} gets strong subtraction.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Modulo classes on post_residual: residuals that divide cleanly into
    // common item sizes (10,20,25,50) are reusable -> reward.
    let reusable = post_residual % 10 == 0 || post_residual % 25 == 0;
    if reusable {
        score -= 6.0;
    } else if post_residual < 10 {
        // dead space below minimum item size
        score += 12.0;
    }

    // Harmonic fraction thresholds: bins in the [0,0.1] leftover band are
    // near-perfect; [0.4,0.6] half-full band is flexible.
    if frac <= 0.1 {
        score -= 8.0;
    } else if frac >= 0.4 && frac <= 0.6 {
        score -= 3.0;
    } else if frac > 0.85 {
        score += 5.0; // leaving a huge empty bin mostly untouched is wasteful
    }

    // Lookahead coupling: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // exact chain: post_residual == next_item_size -> perfect chain
            if next_item_size == post_residual {
                score -= 10.0;
            }
            // next item leaves another reusable residual
            let pr2 = post_residual - next_item_size;
            if pr2 % 10 == 0 || pr2 == 0 {
                score -= 4.0;
            }
        } else {
            score += 4.0; // chain broken
        }
    } else {
        // last item: prefer zero residual strongly
        score -= (cap - pr) * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, penalize opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    // New-bin candidate handling: empty bin should only win when current fits
    // are poor. Penalize the fresh bin mildly, scaled by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 14.0;
        // if no open bin fits well (item leaves big residual everywhere),
        // relax the penalty so a new bin can win
        if next_item_size > 0 && next_item_size > item_size && fitting_bins_count <= 1 {
            penalty -= 10.0;
        }
        score += penalty * (0.5 + 0.5 * progress);
    }

    // Mean residual context: if this bin's residual is far below mean, it is
    // tight already -> good to fill it.
    let diff = mean_residual - pr;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.15;
    }

    // Integer-division threshold on post_residual: quartile classes.
    let q = post_residual / 25; // 0..4
    score -= match q {
        0 => 5.0,
        1 => 2.0,
        2 => 1.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny nonzero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, encourage filling.
    score += (open_bins_count as f64) * 2.5;

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap < 10 {
            score += 10.0;
        }
    }

    // New-bin candidate: make it attractive only when open bins are scarce
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        score += 10.0 * (open_bins_count as f64);
        score -= 30.0 * mean_residual / (bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is excellent.
    if post_residual == 0 {
        score -= 200.0; // perfect fit, strongly favored
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 150.0; // next item will perfectly fill this bin
        } else if (gap as f64) < 10.0 {
            score -= 80.0 - gap as f64 * 4.0;
        } else {
            // penalize leaving residual that is awkwardly larger than next item
            score += gap as f64 * 0.8;
        }
    }

    // Relative-to-mean coupling: bins with residual far from the mean
    // are less reusable; prefer bins whose residual is already tight.
    let pr = post_residual as f64;
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: an empty bin should only win when
    // open bins would waste a lot of space.
    if bin_residual == bin_capacity {
        // neutral-ish baseline: post_residual = capacity - item_size
        // penalize slightly so tight fits in open bins win,
        // but keep it low enough to beat bad fits.
        score += 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 40.0; // fresh bin also accommodates the next item well
        }
    }

    // Late in the stream, prefer closing bins out (reduce fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * (0.1 + 0.4 * progress);

    // Many open bins: discourage spreading across bins; prefer consolidation.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward snug placements, punish large dead space
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible
            score -= 18.0 * (next_item_size as f64 / 100.0);
            // Reward perfect chain (residual exactly consumed by next item)
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here; penalize leaving awkward small residuals
            let awkward = post_residual as f64;
            if awkward < next_item_size as f64 && awkward > 0.0 {
                score += 0.35 * awkward * (1.0 - progress * 0.5);
            }
            // If this bin could have taken the next item instead, slight penalty
            if next_item_size <= bin_residual && next_item_size > item_size {
                score += 4.0;
            }
        }
    } else {
        // Last item: any placement is fine, slight preference for exact fill already handled
        score -= 5.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless
    // current open bins have poor fits or stream is early
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score += 45.0;
        // Cheaper to open a bin early when few bins exist
        score -= (open_bins_count as f64).ln().max(0.0) * 6.0;
        // If no open bin fits at all, opening is necessary
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid proliferation of bins
        score += 20.0 * progress;
        // If mean residual across open bins is small, open bins are nearly full — new bin reasonable
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
        // Large items deserve fresh bins when residuals are fragmented
        if item_size > 60 && mean_residual < item_size as f64 * 1.2 {
            score -= 10.0;
        }
    } else {
        // Using an existing bin: reward keeping bin count low
        score -= 8.0 / (open_bins_count as f64).max(1.0);
        // Reward bins whose residual is far from mean (balancing fragmentation)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Penalize placing tiny items into large residual (wasteful)
        if item_size < 30 && bin_residual > 70 {
            score += 6.0;
        }
    }

    // Mild global pressure: as stream progresses, tighten placements
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mut score = pr;

    // Reward tight fits: smooth polynomial in normalized fill ratio.
    let fill = 1.0 - pr / cap;
    score -= 2.5 * fill * fill * fill * (1.0 + progress);

    // Penalize dead space quadratically, scaled by stream progress.
    let dead = pr / cap;
    score += 1.8 * dead * dead * (0.5 + progress);

    // Lookahead coupling: reward bins whose post-residual fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 1.2 * snug * snug;
        } else {
            // Post-residual cannot host next item: mild penalty growing with waste.
            score += 0.6 * (pr / nxt.min(cap));
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 3.0 * (0.5 + 0.5 * progress);
    }

    // Many open bins with high mean residual: penalize spreading waste.
    let open_f = open_bins_count as f64;
    score += 0.15 * (mean_residual / cap) * (open_f.sqrt()) * (1.0 - progress);

    // New-bin candidate handling: reserve fresh bins for large items or
    // when no open bin is a good home; penalize otherwise.
    if bin_residual == bin_capacity {
        let big = it / cap;
        score += 4.0 * (1.0 - big * big) * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) > it {
            score -= 1.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse quantization into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds: class index 0..8 over post_residual / 12
    let class = (post_residual / 12) as f64;

    // Reward placements whose residual class matches a "harmonic" slot that
    // small items (<= 12, <= 25, <= 50) can still fill.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 12 {
        score -= 35.0; // small dead space, near-perfect
    } else if post_residual <= 25 {
        score -= 15.0;
    } else if post_residual <= 50 {
        score -= 5.0;
    } else {
        score += 10.0; // large residual left behind: wasteful
    }

    // Modulo arithmetic on post_residual: multiples of 10 align with common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Reward when the residual stays in a usable harmonic class for the next item.
            let leftover = post_residual - next_item_size;
            if leftover <= 12 {
                score -= 20.0;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item cannot use this residual: penalize large residuals that strand space.
            score += (post_residual as f64 - mean_residual).max(0.0) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        let poor_fit = if post_residual > 50 { 30.0 } else { 0.0 };
        // Base cost of opening a new bin, reduced when many bins are open (amortized)
        score = 40.0 - pressure * 3.0 + poor_fit;
        // Early in the stream, opening bins is cheaper (build a diverse pool)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 12.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin guarantees room for the next item
            score -= 5.0;
        }
    }

    // Mild tie-break: prefer bins whose residual is below the open-bin mean (tighter bins first)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Small penalty for wasting a big bin on a tiny item late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if item_size < 25 && post_residual > 60 {
        score += 10.0 * progress;
    }

    // Class-based smooth tiebreak using integer division thresholds
    score += class * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that no realistic item (>=1) can use are worst;
    // gaps of 1..=9 are "unusable" under typical distributions -> hard penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0; // unusable tiny gap: penalize
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 5.0; // moderately awkward gap
    } else {
        // Larger residual is somewhat usable; mild reward relative to raw value
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0; // next item fits, leaving near-perfect state
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 10.0; // dead space AND next item can't use it
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and stream progress.
        score += 20.0 + open_bins_count as f64 * 6.0 + (step_index as f64 / total_items.max(1) as f64) * 30.0;
        // But if all open bins have tiny residuals and item is large, new bin is fine.
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 0 {
            score -= 40.0;
        }
    }

    // Prefer filling bins below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.5;

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize large leftover gaps
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare post_residual against mean residual: keep bins near average fill
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless all fits are very poor
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.1 * next_item_size as f64;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(0.0);

    // Penalize unusable dead space (small fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual is already the base; amplify near-perfect fits)
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 20.0 / (post_residual as f64);
    }

    // Penalize dead space that is too small to be useful later (items >= 1, but small items rare)
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 1.5; // unusable sliver penalty
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + (next_item_size as f64) * 0.1;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins: relative fill tightness
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Time horizon: early in stream, be conservative (favor tight fits only);
    // late in stream, prefer consolidating into existing bins over opening new ones
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * 5.0;

    // Global state: many open bins with high mean residual -> encourage using existing bins
    if bin_residual != bin_capacity {
        score -= (mean_residual / bin_capacity as f64) * 3.0;
        score -= (open_bins_count as f64) * 0.3;
    } else {
        // New-bin candidate: penalize opening new bins, more so when open bins exist
        // and mean residual is large enough to absorb the item
        score += 25.0;
        if open_bins_count > 0 && (mean_residual as u32) >= item_size {
            score += 10.0;
        }
        // Late in stream, opening new bins is even less desirable
        score += t * 15.0;
    }

    // Mild penalty for very large leftover that could still serve big items — keep it usable
    if post_residual >= 40 {
        score -= 3.0; // residual still valuable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res_norm = pr / cap;

    // Reward tight fits: non-linear penalty on wasted space, stronger later in stream
    let tightness = (item_size as f64) / cap;
    score -= 25.0 * (1.0 - res_norm).powi(3) * (0.5 + progress);

    // Penalize small unusable residuals (dead space) with smooth quadratic coupling
    if post_residual > 0 {
        score += 15.0 * res_norm * (1.0 - res_norm) * (1.0 - progress);
    }

    // Lookahead coupling: bonus if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / cap) * (0.6 + 0.4 * progress);
    } else if next_item_size > post_residual {
        score += 6.0 * ((next_item_size - post_residual) as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild pressure to prefer fuller bins when many bins are open
    score -= (mean_residual - pr) * 0.05;
    score += 0.02 * open_bins_count as f64 * res_norm;

    // New-bin candidate: keep it neutral-to-slightly-attractive early, unattractive later
    if bin_residual == bin_capacity {
        score += 8.0 * progress - 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: perfect fits and small dead space rewarded
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else if pr <= 30 {
        score -= 3.0;
    }

    // Modulo classes: residual divisible by common item granularity is reusable
    if pr > 0 && (pr % 10 == 0) {
        score -= 6.0;
    } else if pr > 0 && (pr % 5 == 0) {
        score -= 3.0;
    }

    // Dead-space penalty for large residuals that few items can use
    if pr > 50 {
        score += (pr as f64 - 50.0) * 0.6;
    }

    // Lookahead: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0; // chain placement possible
            // harmonic coupling: next item fills residual to a low class
            let pr2 = pr - next_item_size;
            if pr2 <= 10 { score -= 8.0; }
        } else {
            score += 6.0; // next item won't fit here
        }
    } else {
        // last item: strongly prefer closing bins tightly
        score -= 30.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitter
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full / poor fits
    let is_new = bin_residual == bin_capacity;
    if is_new {
        // opening a new bin wastes the aggregate residual of open bins
        score += open_bins_count as f64 * 1.5;
        // early stream: opening bins is fine; late stream: prefer packing into existing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if item is small relative to mean residual, prefer existing bins
        if (item_size as f64) < mean_residual {
            score += 15.0;
        }
        // large item with no tight fit: new bin reasonable
        if item_size as u32 > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter existing bins overall
    score += (bin_residual as f64 / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps (1..=10) are heavily penalized; mid gaps (11..=25) mildly penalized.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - (post_residual as f64) * 2.0; // dead space: worst when tiny
    } else if post_residual <= 25 {
        score += 15.0;
    } else if post_residual >= 40 {
        // Large leftover space is flexible; reward it slightly.
        score -= 8.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // This bin can still host the next item: keep it attractive.
            let slack = post_residual - next_item_size;
            score -= 12.0 - slack as f64 * 0.15;
        } else {
            // Next item won't fit here: residual is likely to become dead space.
            score += (post_residual as f64).min(35.0) * 0.6;
        }
    } else {
        // Last item: closing a bin fully is ideal.
        score -= 20.0;
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        // Only this bin fits; avoid opening a new bin unless the fit is terrible.
        score -= 25.0;
        if post_residual <= 30 {
            score -= 15.0;
        }
    }

    // --- Open bins count pressure ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    score += bin_pressure;

    // Deviation from mean residual: prefer bins whose residual stays near the pack norm.
    score += (mean_residual - post_residual as f64).abs() * 0.25;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Fresh bin: baseline cost of opening one. Attractive when existing fits are poor
        // (dead-space penalties above push bad fits above this), unattractive otherwise.
        score = 95.0 + item_size as f64 * 0.3 - (post_residual as f64) * 0.2;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 40.0; // strongly discourage abandoning the sole fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: if the NEXT item exactly matches the
    // post_residual, this bin is a perfect chain -> huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how well it uses
            // the leftover (chain utilization).
            let chain_use = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * chain_use;
            // Second-order residual after hypothetically placing next item.
            let second_residual = post_residual - next_item_size;
            if second_residual <= 10 {
                score -= 60.0;
            }
        } else {
            // Next item will NOT fit here: penalize leaving a residual that
            // is too small to be useful for the known next item.
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 40.0; // near-miss: dead space likely
            }
        }
    }

    // Compare post_residual against the mean residual across open bins:
    // leaving less than average is good (tight packing), leaving more than
    // average wastes potential.
    if mean_residual > 0.0 {
        let diff = post_residual as f64 - mean_residual;
        score += 0.5 * diff;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when good fitting bins exist: make the
    // empty-bin candidate expensive unless the item is huge relative to
    // typical residuals or we have many bins already (early stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 220.0;
        // Large items benefit from fresh bins late in the stream.
        if item_size >= 60 && progress > 0.5 {
            penalty -= 100.0;
        }
        // Many open bins: opening another spreads residuals poorly.
        penalty += 5.0 * open_bins_count as f64;
        score += penalty;
    }

    // Small general bonus for filling bins tightly relative to capacity.
    score -= 0.3 * (item_size as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-perfect packing by penalizing loose fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Reward when the leftover space is too small for the smallest plausible item (dead-space elimination).
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to wasted opportunity.
            score += 3.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: minimize leftover aggressively.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 * (1.0 - 0.5 * progress);
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Global residual pressure: if mean residual is low, preserve bins with large residuals
    // (keep them for big future items) by penalizing placement into them slightly.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel > 1.5 {
            score += 6.0 * (rel - 1.5);
        } else {
            score -= 3.0 * (1.5 - rel);
        }
    }

    // New-bin candidate: default attractiveness; open a new bin only when the item is large
    // or no open bin offers a good fit (post_residual would be large).
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        // Penalize new bin when item is small (easy to place elsewhere); reward for large items.
        score += 20.0 - 0.25 * item_size as f64 + urgency;
        // Late in the stream, prefer closing out existing bins rather than opening new ones.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer low post residual, with a smooth convexity that grows over the stream.
    let mut score = pr * (1.0 + 0.8 * progress) + 30.0 * x * x * (0.5 + progress);

    // Reward tight fits (small x) with a smooth decaying bonus.
    score -= 25.0 * (1.0 - x) * (1.0 - x) * (1.0 - progress);

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (n - pr).max(0.0) / cap;
        score += 20.0 * gap * (1.0 + progress);
        // Bonus if post residual still accommodates the next item smoothly.
        let fits_next = if pr >= n { 1.0 } else { 0.0 };
        score -= 12.0 * fits_next * x * (1.0 - x);
    }

    // Last-chance bin: smooth reward scaled by scarcity.
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 15.0 * scarcity * (1.0 - x) * (0.5 + 0.5 * progress);

    // Penalize bins far from mean residual (smooth dispersion term).
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild penalty for opening a new bin late in the stream when many bins exist.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect-fit class: post residual zero is ideal
    if pr == 0 {
        score -= 500.0;
        return score;
    }

    // Class A: post_residual is a multiple of 10 (aligns with typical size grid)
    if pr % 10 == 0 {
        score -= 60.0;
    }
    // Class B: post_residual divisible by 20 (large-grained harmony)
    if pr % 20 == 0 {
        score -= 40.0;
    }
    // Class C: post_residual divisible by 5
    if pr % 5 == 0 {
        score -= 15.0;
    }

    // Integer-division thresholds on post_residual
    let pr_class = pr / 10; // 0..=9 coarse class
    score -= (pr_class as f64) * 8.0; // larger leftover (in coarse class) is better than tiny dead space

    // Penalize tiny unusable residuals (dead space) more than proportionally
    if pr < 10 {
        score += 120.0;
    } else if pr < 20 {
        score += 45.0;
    }

    // Coupling with next item size (lookahead harmony)
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly into the leftover: harmonic chaining
            score -= 90.0;
            if next_item_size == pr {
                score -= 150.0; // exact chain fill
            } else if (pr - next_item_size) % 10 == 0 {
                score -= 35.0;
            }
        } else {
            // next item cannot use this residual; residual likely wasted
            score += 25.0;
        }
    }

    // Capacity fraction coupling: reward filling a large fraction of the bin
    let fill_frac = (item_size as f64) / cap;
    score -= fill_frac * 70.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 130.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early or when many bins already open
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 - 150.0 * progress;
        score += (open_bins_count as f64) * 6.0;
        // If current item is large, fresh bin is attractive
        score -= (item_size as f64) * 0.8;
        // If next item is small, existing bins may absorb it; keep new bin less attractive
        if next_item_size > 0 && next_item_size <= 30 {
            score += 40.0;
        }
    }

    // Mean residual context: prefer bins below mean residual (tighter bins) to be filled
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit even the
    // smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 18.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += tightness * 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading into
    // fresh bins; encourage filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += pressure * 6.0;
    } else {
        score -= pressure * 0.8;
    }

    // Lookahead: if next item fits into post_residual, this placement is good.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 10.0;
    }

    // Slight preference for bins with residual close to mean (avoid outliers).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual perfectly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack.min(30) as f64) * 0.5; // next item fits with small slack
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3; // next item won't fit here
        }
    }

    // Tight fits are valuable: penalize large post_residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins could take the item well.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // fresh bin chains nicely with next item
        }
        if open_bins_count > 0 && fitting_bins_count > 0 && post_residual > 40 {
            score += 8.0; // don't open bins leaving big unusable space
        }
    }

    // Late in the stream, prefer closing out bins (reduce fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small unusable post-residuals (dead space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra bonus if post-residual is a near-perfect match for the next item.
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - next_fit / bin_capacity as f64);
    }
    // Penalize leaving a residual just below the next item's size (frustrating near-miss).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying over the stream as bins accumulate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + 10.0 - 5.0 * progress;
        // Opening a bin is better if existing mean residual can't host the item well.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // If only one fitting bin exists, discourage opening a new bin.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
        // Lookahead: a fresh bin can host both current and next item.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residual close to the global mean (balance).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Mild penalty for having many open bins: favor consolidation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Normalize residuals
    let cap = bin_capacity as f64;
    let pr_norm = post_residual as f64 / cap;
    let item_norm = item_size as f64 / cap;

    // Smooth polynomial coupling: tight fits are rewarded more strongly as stream progresses.
    // reward = (1 - pr_norm)^k, amplified by progress
    let tightness = (1.0 - pr_norm).max(0.0);
    let tightness_poly = tightness * tightness * (3.0 - 2.0 * tightness); // smoothstep-like
    score -= 12.0 * tightness_poly * (0.4 + 0.6 * progress);

    // Polynomial interaction between item size and progress:
    // large items placed late are extra-rewarded (get rid of big items while bins exist)
    let size_coupling = item_norm * item_norm * (1.0 + p2 * 2.0);
    score -= 6.0 * size_coupling;

    // Lookahead: if next item fits exactly into the post residual, strong reward (smooth decay)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let slack = (post_residual as f64 - nxt) / cap;
            let exactness = (1.0 - slack).max(0.0);
            score -= 10.0 * exactness * exactness * (0.5 + 0.5 * progress);
        } else {
            // next item won't fit here: mild penalty growing with progress (close-out pressure)
            let overflow = (nxt - post_residual as f64) / cap;
            score += 4.0 * overflow * overflow * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bin: strong smooth reward, amplified late in stream
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress) * (1.0 + 0.5 * p3);
    } else if fitting_bins_count > 2 {
        // many alternatives: slight penalty to avoid scattering items
        score += 2.0 * ((fitting_bins_count - 2) as f64).ln().max(0.0) * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins deviating from mean toward fullness
    let mean_pr = mean_residual / cap;
    score += 3.0 * (pr_norm - mean_pr) * (0.5 + p2);

    // Mild penalty on opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 8.0 * (0.3 + 0.7 * progress) * (1.0 + open_bins_count as f64 / 20.0);
        // unless the item is huge and would leave big dead space anywhere
        if item_norm > 0.7 {
            score -= 6.0 * item_norm * item_norm;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo 10: small dead space classes
    // (0,1,2) are nearly useless; larger classes can still host future items.
    let pr = post_residual as i64;
    let cls = pr % 10;
    let dead_penalty = match cls {
        0 => -2.0,          // exact decade residual is still valuable
        1 | 2 => 6.0,       // dead space: cannot fit anything (min item 1..10)
        3 | 4 => 3.0,
        _ => 0.0,
    };
    score += dead_penalty as f64;

    // Integer-division harmonic tiers: reward residuals that can host
    // whole multiples of common item classes.
    let tiers = post_residual / 10;
    score -= tiers as f64 * 0.5;

    // Fraction-of-capacity coupling: residual as a fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= frac * 10.0;

    // Lookahead harmony: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here: penalize leaving a big residual
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits, mild bonus
        score -= 2.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its post_residual = capacity - item_size is large, but opening a new
    // bin should only win when all existing fits are bad.
    if bin_residual == bin_capacity {
        // neutral base for new bin; discourage when decent fits exist
        score += 15.0;
        // but encourage early in the stream when few bins are open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if open_bins_count == 0 {
            score -= 100.0;
        } else if progress < 0.2 && open_bins_count < 4 {
            score -= 10.0;
        }
        // if next item is large and current fit leaves awkward residual,
        // opening fresh can be better
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 20 {
            score -= 12.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a tight bin — finishing it off is good (reduces bin fragmentation).
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (min size 1..=10)
    // can ever use are pure waste — penalize them quadratically.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10.0 - post_residual as f64) * 8.0;
    }
    // Moderately small gaps (11..25) are also risky under unknown distributions.
    if post_residual > 10 && post_residual <= 25 {
        score += (post_residual as f64 - 10.0) * 1.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Exact-fill bonus when the item exactly matches the residual.
    if post_residual == 0 && bin_residual == item_size {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading items out.
    score += open_bins_count as f64 * 1.2;

    // Last-chance bin: if this is the ONLY bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when this bin would otherwise
    // leave a bad gap, or when no open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; make it slightly worse than a good fit
        // but better than a bin leaving a dead gap.
        score += 15.0;
        if mean_residual < 15.0 {
            // Existing bins are nearly full; a new bin is reasonable.
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward leaving exactly that amount of space.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 - (post_residual - next_item_size) as f64 * 0.3;
    }
    // If next item almost fits (misses by a little), penalize leaving that gap.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Late-stream tightening: as the stream progresses, be greedier about
    // filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    // Prefer bins whose residual is close to the item (tight relative fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after next item would be placed: penalize remaining slack
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack_after_next * 0.5;
        } else {
            // Next item won't fit after placing current item: penalize
            score += 15.0;
        }
    }

    // Compare post_residual relative to mean residual of open bins
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score += (post_residual as f64 - mr) * 0.3;

    // Last-chance bin bonus: avoid wasting a scarce fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize tiny dead space that becomes unusable (min item size 1)
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Prefer tighter fits overall
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Late in stream: consolidate into existing bins rather than opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses
        score += 20.0 + 40.0 * progress;
        // Opening a new bin is acceptable only if item is large
        score -= (item_size as f64 / 100.0) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead-aware).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 + 0.25 * post_residual as f64;
        } else if post_residual >= next_item_size {
            score -= 8.0; // leaving room for the lookahead item is good
        }
    } else {
        // Last item: any bin that fits is fine; prefer most filled.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = (mean_residual - item_size as f64).max(0.0);
        score = bin_capacity as f64 - 30.0 * progress - 0.5 * waste_pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // room for pairing in a fresh bin
        }
    }

    // Mild preference to fill bins with larger residuals when many bins are open.
    score -= 0.05 * open_bins_count as f64 * (bin_residual - item_size) as f64 / bin_capacity as f64;

    // Early stream: be slightly conservative, keep bins balanced.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 40.0 * poly * (0.5 + t);

    // Tight fits are strongly favored, weighted more as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 20.0 * t);

    // Penalize large residual waste non-linearly
    score += x * x * x * 15.0 * (1.0 - t);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * t;
    }

    // Lookahead: reward if next item fits the resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (pr - nxt) / cap * (1.0 + t);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Mild pressure against hoarding many open bins with slack
    let slack = (mean_residual - pr) / cap;
    score += slack * slack * 3.0;

    // New-bin candidate: penalize unless current bins fit poorly
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * t;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity
    let pr = post_residual;
    let class = pr % 10;
    // Reward residuals that form "harmonic" pairings: 0, 25, 50 exactly
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr == 25 || pr == 50 {
        score -= 25.0;
    } else if pr < 10 {
        score += 40.0; // dead space below smallest item
    }

    // Integer-division threshold: post_residual bucketed by quarter capacity
    let quarter = bin_capacity / 4;
    let bucket = pr / quarter;
    score += match bucket {
        0 => 15.0,          // tiny leftover: likely waste
        1 => -5.0,          // sweet spot
        2 => 0.0,
        _ => -10.0,         // bin still roomy, fine
    };

    // Modulo coupling with next item: if next item exactly fits post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 30.0; // harmonic alignment leaves multiple-of-10 residual
        } else if next_item_size > pr {
            score += 10.0; // next item won't fit here regardless
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing unless fit is bad
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 0.5;
        // but if current item would leave a bad class residual in any bin, new bin is fine
        if item_size % 10 == 0 && item_size >= bin_capacity / 2 {
            score -= 55.0;
        }
    }

    // Progression: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * (0.3 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range)
    // are pure waste — penalize them heavily.
    if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space (smaller than any item): severe penalty.
        score += 120.0;
    } else {
        // Usable residual: mild bonus scaled by how much usable space remains.
        score -= 8.0;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Open-bin pressure: when many bins are open, discourage opening/leaving new ones.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item would fit the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Mean residual coupling: avoid bins far from the mean (keeps residual profile uniform).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for reusing existing bins over the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * step_index as f64 / total_items.max(1) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward near-exact match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain (next item exactly fills the remaining space) -> strong reward.
        if post_residual == next_item_size {
            score -= 40.0;
        } else {
            score += gap * 0.6;
        }
        // Penalize leaving residual that neither fits next item nor is useful.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are preferred targets.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Penalize large dead space that nothing (min size 1) can later use well.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalized slightly so we
    // only open a new bin when existing fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if lookahead won't chain well anywhere, opening fresh is fine:
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Progress-aware tightening: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.3;

    // Prefer packing into already-open bins when many are open (consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) non-linearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Penalize leaving residuals that are too small to be useful later
    // (dead space): residual < 10 is essentially wasted capacity.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // this placement is excellent — reward it heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else {
            score -= 15.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // every other open bin. Penalize proportionally to how many bins are open
    // and how much mean residual would be stranded.
    if bin_residual == bin_capacity {
        let stranded = mean_residual * open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening bins late in the stream is fine (few future items to strand),
        // but early on it wastes capacity.
        score += 15.0 + stranded * 0.3 * (1.0 - progress);
        // If many bins fit already, a new bin is rarely better.
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).sqrt();
        }
        // Exception: item is large and next item pairs with a fresh bin nicely.
        if item_size >= 50 && next_item_size >= 50 && item_size + next_item_size <= bin_capacity {
            score -= 25.0;
        }
    }

    // Mild preference for filling fuller bins when many bins are open,
    // to consolidate residual space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill_ratio * (open_bins_count as f64).ln().max(0.0) * 0.2;

    // Time horizon: early in the stream, prefer placements that keep residuals
    // flexible (moderate residuals); late, just fill as much as possible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        // Early: penalize very large post_residual (fragmentation risk).
        if post_residual > 50 {
            score += 6.0;
        }
    } else if progress > 0.7 {
        // Late: reward using the fullest bins.
        let used = bin_capacity as f64 - bin_residual as f64;
        score -= 8.0 * used / bin_capacity as f64;
    }

    // Coupling: mean residual high means fragmentation; favor bins below mean
    // residual (fill the emptier ones first to balance).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial base: reward tight fits, penalize large leftovers,
    // with the shape of the penalty evolving over the stream.
    let t = progress;
    let poly = x * x * (1.0 - x) * (1.0 - x); // smooth bump peaking mid-residual
    let mut score = pr as f64 * (1.0 + 0.8 * t) - 30.0 * poly * (1.0 + t);

    // Lookahead coupling: favor bins whose post-residual matches the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_term = (pr - nx).abs() / cap;
        score += 20.0 * match_term * match_term;
        // Perfect lookahead fit bonus
        if post_residual as u32 == next_item_size {
            score -= 15.0 * (1.0 - t);
        }
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * t);
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (reduce fragmentation variance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev * (0.5 + t);

    // New-bin candidate: penalize opening a new bin more as stream progresses,
    // unless open bins are very fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).min(1.0);
        score += 40.0 * (1.0 - 0.6 * t) * (1.0 - 0.5 * frag);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class penalty: residuals that no plausible item (1..=80, min 10)
    // can ever fill are dead space. Classify residual by integer division bands.
    let dead_threshold = 9u32; // no item can fit if residual < 10
    if post_residual < dead_threshold {
        score += 500.0; // unavoidable dead space, but prefer smaller residual
    } else {
        // Usable residual: reward by how finely it can be split (harmonic classes)
        // residual mod common item sizes: leaving residual that is a multiple of
        // small item sizes is easier to fill later.
        let mut div_bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                div_bonus += 15.0;
            }
        }
        score -= div_bonus;

        // Penalize residuals in "awkward" bands: just above multiples of 10
        // (e.g., 11..19 can only be filled by tiny items).
        let r = post_residual % 10;
        if r >= 1 && r <= 9 {
            score += r as f64 * 2.0;
        }
    }

    // Lookahead coupling: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0;
        // extra reward if post_residual - next_item_size is also small or zero
        let rr = post_residual - next_item_size;
        if rr == 0 {
            score -= 200.0;
        } else if rr < 10 {
            score -= 50.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot follow: dead space risk proportional to how much
        // post_residual is below next_item_size
        let gap = next_item_size as f64 - post_residual as f64;
        if gap > 0.0 && gap <= 20.0 {
            score += gap * 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer fuller bins among many open bins (mild pressure to close bins).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 40.0;

    // When many bins are open, discourage opening new bins; when few, allow it.
    if bin_residual == bin_capacity {
        // new-bin candidate score: baseline slightly above a good fit
        score = 60.0 + mean_residual * 0.1 - (open_bins_count as f64) * 2.0;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // late in stream, prefer reusing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 5.0 * post_residual as f64; // gap 1 => +55, gap 10 => +10
    } else if post_residual > 10 && post_residual <= 25 {
        score += 8.0; // moderate waste zone
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is excellent
    }

    // Reward tight fits (small leftover relative to bin capacity).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating;
    // when few bins are open, spreading is less costly.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., unusually full bin) is good; penalize bins far above mean.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Lookahead: if next item fits the post residual exactly, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size <= 10 {
            score -= 20.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 5.0; // dead space that next item cannot use
        }
    }

    // New-bin candidate: default attractiveness, adjusted by stream position
    // and pressure. Early in stream, new bins are cheap; late, prefer reuse.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score = 55.0 + 40.0 * progress + 1.5 * open_bins_count as f64;
        // If the only alternative creates dead space, new bin stays attractive;
        // if a perfect fit exists elsewhere, that bin's -40 dominates.
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 10.0; // item nearly fills a fresh bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // 2-step lookahead: reward when post_residual closely matches next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_gap = (post_residual as f64 - nxt).abs();
        // Perfect match => next item fills this bin completely
        if post_residual == next_item_size {
            score -= 60.0; // chain bonus: two items pack this bin exactly
        } else if post_residual > next_item_size {
            score -= (20.0 * (1.0 - match_gap / 100.0)).max(0.0);
        } else {
            // next item won't fit here; penalize proportionally to leftover dead space
            score += 0.35 * post_residual as f64;
        }
        // lookahead aware tightness: small post_residual is good unless it matches next item
        score -= (bin_capacity as f64 - post_residual as f64) * 0.05;
    } else {
        // last item: strongly prefer tightest fit
        score -= (bin_capacity as f64 - post_residual as f64) * 0.5;
    }

    // Relative-to-mean residual coupling: prefer bins with residual below mean
    // (consolidate into fuller bins), scaled by stream progress.
    score += (post_residual as f64 - mean_residual) * (0.3 + 0.4 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins would leave big dead space
    if is_new_bin {
        let open_penalty = if open_bins_count == 0 {
            -100.0 // must open first bin
        } else if next_item_size > 0 {
            // new bin has full residual; check if it matches next item too
            let perfect_chain = post_residual == bin_capacity && bin_capacity - item_size == next_item_size;
            if perfect_chain {
                10.0
            } else {
                55.0 + 20.0 * progress // penalize opening bins as stream progresses
            }
        } else {
            80.0 // never open a bin for the last item if any bin fits
        };
        score += open_penalty;
    }

    // Mild preference for tighter fits among open bins
    score += 0.1 * (bin_residual as f64 - post_residual as f64).signum() * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Penalize small unusable post-residuals that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 4.0 * (1.0 - post_residual as f64 / (next_item_size as f64).min(bin_capacity as f64));
        }
    } else {
        // Last item: prefer the bin that ends up fullest.
        score -= 50.0 * tightness;
    }

    // Scarcity: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        // Many alternatives: be pickier, penalize mediocre fits.
        score += 3.0 * (1.0 - tightness);
    }

    // Discourage opening new bins when open bins have plenty of slack on average.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        score += 20.0 * (mean_residual / bin_capacity as f64);
        // Early in the stream, opening bins is cheap; late, it is expensive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If many bins are already open, prefer consolidation into them.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Reward using existing bins relative to their slack vs. mean.
        score -= 5.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Mild non-linear preference for near-perfect fills.
    if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let fit = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - pr / bin_capacity as f64;

    let mut score = pr;

    // Reward tight fits, amplified by stream progress (be greedy late).
    score -= 60.0 * tightness.powf(2.0) * (0.5 + progress);

    // Non-linear coupling: penalty for post_residual that is unusable
    // relative to the next item (dead space) — smooth interaction.
    let next = next_item_size as f64;
    if next > 0.0 {
        let waste = (pr - next).max(0.0) / bin_capacity as f64;
        score += 40.0 * (waste * (1.0 + progress)).powf(1.5);
        // Reward bins whose post_residual exactly accommodates next item.
        let match_bonus = 1.0 - ((pr - next).abs() / bin_capacity as f64);
        score -= 25.0 * match_bonus.powf(3.0) * pr.signum();
    }

    // Last fitting bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0 * (1.0 + progress);
    }

    // New-bin candidate: prefer it early or when no open bin fits well.
    if bin_residual == bin_capacity {
        let openness = (mean_residual / bin_capacity as f64).min(1.0);
        score = 100.0 - 30.0 * progress - 20.0 * openness * fit;
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).powf(0.8) * (1.0 - tightness) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Dead-space penalty grows non-linearly for residuals that are hard to reuse
    // (items are 1..100, so residual r is reusable only if some item <= r arrives).
    // Penalize residuals in "awkward" bands: just above common item sizes.
    if post_residual > 0 {
        let awkward = if post_residual <= 10 {
            0.5
        } else if post_residual <= 25 {
            0.0
        } else if post_residual <= 50 {
            0.15 * frac
        } else {
            -0.1 * frac // large residuals are quite reusable
        };
        score += awkward * (post_residual as f64);
    }

    // Modulo-10 harmonic class: residuals that are multiples of 10 pair well
    // with typical item granularities.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Residuals that are 1 mod 10 are nearly useless (only tiny items fit)
    if post_residual % 10 == 1 && post_residual > 1 {
        score += 5.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it packs
            score -= 10.0 * (next_item_size as f64) / (post_residual as f64).max(1.0);
        } else {
            // next item won't fit here: slight penalty for leaving a bin that
            // will strand the next item
            let slack = (next_item_size - post_residual) as f64;
            score += 0.05 * slack;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity.
    // Penalize opening a new bin unless existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity
        score += 20.0;
        // More acceptable late in the stream or when many bins already open
        // (consolidation matters less then)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        // If mean residual across open bins is small, open bins are nearly full:
        // opening a new bin is more reasonable.
        score -= 0.2 * (cap - mean_residual.min(cap)).max(0.0);
        // Perfect fit on existing bins should never lose to a new bin
        if post_residual == 0 { score -= 2000.0; }
    }

    // Tightness reward: prefer bins where item fills a large share of residual
    let fill_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 8.0 * fill_ratio;

    // Mild preference for fuller bins overall (best-fit flavor)
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64).signum() * -1.0 * 0.0; // no-op guard

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100 unknown, use a
    // conservative "unusable gap" threshold) are heavily penalized with a non-linear kick.
    let unusable_threshold: f64 = 12.0;
    if (post_residual as f64) < unusable_threshold && post_residual > 0 {
        score += (unusable_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: eliminate score entirely.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Near-perfect fit bonus.
    if post_residual > 0 && post_residual <= 3 {
        score -= 15.0;
    }

    // Reward bins whose residual is "consumed" proportionally more (tight packing).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so penalize it there.
    if bin_residual == bin_capacity {
        score += 25.0 + 5.0 * open_bins_count as f64;
    } else {
        // Favor reusing existing bins slightly more when bin count grows.
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item cannot fit in post residual but could fit in a tighter bin, mild penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (smaller gaps get used first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Stream progression: early on, be slightly more tolerant of slack; late, be strict.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: an empty bin is only attractive when the item
    // leaves a residual that is likely reusable by the next item, or when no
    // good fit exists among open bins.
    if bin_residual == bin_capacity {
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
            -12.0 * (next_item_size as f64 / bin_capacity as f64)
        } else {
            0.0
        };
        // Penalty grows with how many open bins could have fit the item.
        let crowd_penalty = 8.0 * (fitting_bins_count as f64).max(1.0);
        // Late in the stream, avoid spawning bins with dead space.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let late_penalty = 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
        score += 25.0 + crowd_penalty + late_penalty + lookahead_bonus;
        return score;
    }

    // Strong reward for a perfect fit.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Reward small leftovers, but only if they are "usable" sizes.
        let usable = post_residual >= 1 && (next_item_size == 0 || post_residual >= next_item_size.min(20));
        if usable {
            score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
        // 2-step lookahead: if next item exactly fills the post residual,
        // this is a chained perfect fit — heavily favor it.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 180.0;
        } else if next_item_size > 0 && post_residual > next_item_size {
            // Next item fits here afterwards: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else if next_item_size > 0 {
            // Next item cannot use the leftover: penalize dead space.
            score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Relative-to-mean coupling: bins with residual below the mean are "tighter"
    // and better candidates; penalize selecting much looser bins.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Early in the stream, encourage consolidation into few bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 4.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.05;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves more fragmentation; mild penalty proportional to waste.
            score += (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here: mild bonus for keeping residual large-ish for later.
            score -= (post_residual as f64 - next_item_size as f64).abs() * 0.1;
        }
    } else {
        // Last item in stream: any bin that fits is fine; prefer fullest.
        score -= 5.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating into bins
    // with residual close to mean (avoid outlier fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // If many bins are open, discourage opening new bins (favor existing fitting bins).
    if open_bins_count > 3 {
        if bin_residual < bin_capacity {
            score -= 4.0 + open_bins_count as f64 * 0.5;
        } else {
            score += 6.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer tight fits less aggressively,
    // keep flexibility); late in the stream, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= tightness * 10.0 * progress;
    score += (1.0 - progress) * (post_residual as f64) * 0.08;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Discourage leaving residuals that no plausible item (1..=100) can use well:
    // residuals below the smallest item size are pure dead space unless 0.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Mild penalty for very large residuals being consumed by small items (waste of big space).
    if item_size <= 20 && bin_residual >= 70 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Penalize large residuals more aggressively as stream progresses (quartic term)
    score += 40.0 * norm_pr * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth exponential shaping
    score -= 12.0 * (-norm_pr * 6.0) * (0.5 + progress);

    // Prefer bins whose residual is close to the mean (keep bin pool homogeneous)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (-slack * 4.0);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: smooth penalty that decays with progress and poor fits elsewhere
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 30.0 + 20.0 * (1.0 - progress) - 3.0 * open;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals divisible by common
    // item sizes are "harmonic" and more likely to be filled later.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else {
        // Class-1: residual is a multiple of small common sizes -> good.
        let mut harmonic_bonus = 0.0;
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 {
                harmonic_bonus += 15.0;
            }
        }
        score -= harmonic_bonus;

        // Class-2: residual below the minimum item size is dead space -> penalize.
        if pr < 10 {
            score += 200.0;
        }

        // Class-3: residual in awkward bands (just above multiples) -> penalize.
        let band = pr % 50;
        if band > 0 && band < 10 {
            score += 40.0;
        }

        // Lookahead coupling: if next item exactly fits post residual, reward.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 500.0;
            } else if next_item_size <= pr {
                let slack = pr - next_item_size;
                score -= 30.0 - (slack as f64).min(30.0);
            } else {
                // next item cannot use this residual: mildly penalize tight residuals.
                if pr < next_item_size && pr >= 10 {
                    score += 20.0;
                }
            }
        }

        // Last-chance bin: if this is the only fitting bin, reward using it
        // to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }

        // New-bin candidate: empty bin has full residual. Penalize opening a
        // new bin unless current residuals are very fragmented.
        if bin_residual == bin_capacity {
            score += 80.0;
            if mean_residual < 25.0 && open_bins_count > 0 {
                // fragmented state: opening fresh bin is reasonable
                score -= 100.0;
            }
            if next_item_size > 0 && next_item_size >= bin_capacity - 40 {
                score -= 50.0;
            }
        }

        // Prefer filling bins with small residuals (tight packing) using
        // integer-division thresholds.
        let tier = pr / 25; // 0..=4 harmonic tier
        score += tier as f64 * 5.0;
    }

    // Slight preference to keep number of open bins low early in stream.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never hold a minimum
    // item (size 1..100 stream, but tiny gaps are near-unusable) are heavily
    // penalized. Treat gaps < 5 as pure waste.
    if post_residual < 5 {
        score += 40.0;
    } else if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly (subtracted).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Tightness: smaller post_residual relative to item gets bonus.
        let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
        score -= 30.0 * tightness * fill_ratio;
    }

    // If this bin's leftover can exactly host the lookahead item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that neither fits the next item nor is tiny.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // still useful for lookahead
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // gap breaks the chain
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor
    // filling existing bins; also makes new empty bin less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // New-bin candidate handling: empty bin starts with post_residual ==
    // capacity, which already scores high; add extra penalty that grows
    // with how well the item would fit elsewhere (mean residual context).
    if bin_residual == bin_capacity {
        score += 10.0 + 0.2 * open_bins_count as f64;
        // If item is large relative to mean residual, opening new bin is
        // more acceptable: soften the penalty.
        if (item_size as f64) > mean_residual {
            score -= 8.0;
        }
    }

    // Slight nudge toward bins whose residual is closest below mean: keeps
    // residual distribution balanced.
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: item + next item exactly fills the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Near-perfect match: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 150.0 - leftover * 2.0;
    }
    // Penalize if next item cannot use the leftover (dead space ahead).
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward tight fits relative to mean residual across open bins.
    if (post_residual as f64) < mean_residual {
        score -= 30.0;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize leaving tiny unusable residuals (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Slight preference to keep fresh bins for later large items:
    // penalize using a nearly-empty bin early in the stream.
    if bin_residual == bin_capacity {
        score += 120.0;
    } else if post_residual == 0 {
        score -= 100.0; // perfect closure
    }

    // Mild stream-progression pressure: pack tighter as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but normalized against capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Reward near-perfect fills strongly.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless the
    // current bin's post residual would be large dead space that also
    // cannot host the next item.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 35.0 + 2.0 * open_bins_count as f64;
        // If placing here wastes a lot and the next item could use the waste,
        // opening fresh is more attractive (reduce penalty).
        let waste = post_residual as f64;
        let next_fits_waste = next_item_size > 0 && (next_item_size as f64) <= waste;
        if waste > 25.0 && next_fits_waste {
            new_bin_penalty -= 30.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += progress * 15.0;
        score += new_bin_penalty;
    } else {
        // Penalize leaving residual close to (but below) typical small items,
        // creating unusable slivers.
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
        // If next item exactly fits the post residual, big reward (chain fit).
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            score -= 12.0;
        }
    }

    // Global state coupling: when mean residual across bins is high,
    // encourage consolidating into existing bins.
    if bin_residual != bin_capacity {
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
    }

    // Slight preference for bins that are already fairly full.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: minimize wasted residual, with smooth non-linear penalty growth
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Tight fits rewarded more strongly as stream progresses (smooth coupling)
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * cap * (0.3 + 0.7 * progress);

    // Lookahead: if the next item fits into post_residual, reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / cap;
        score -= cap * (0.15 + 0.35 * progress) * next_fit * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        // Dead space for next item: penalize smoothly
        score += 8.0 + 12.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Penalize bins far from mean residual (encourage residual homogenization)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * dev * cap * 0.4;

    // New-bin candidate: slightly discourage early, allow late when fits are scarce
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 20.0 * (1.0 - progress) * (1.0 - scarcity) + 5.0 * open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse granularity buckets.
    // Residuals that are "useless" (very small) should be penalized;
    // residuals in reusable classes (multiples of common item sizes) rewarded.
    let class = post_residual / 10;
    match class {
        0 => score += 25.0,          // dead space < 10
        1 => score += 8.0,           // 10-19: only tiny items fit
        2 => score -= 2.0,           // 20-29
        3 => score -= 5.0,           // 30-39
        4 => score -= 8.0,           // 40-49
        5 => score -= 10.0,          // 50-59 sweet spot
        6 => score -= 6.0,
        7 => score -= 3.0,
        _ => {}
    }

    // Reward residuals that are exact multiples of common sizes (10,20,25,50).
    if post_residual > 0
        && (post_residual % 10 == 0 || post_residual % 25 == 0 || post_residual % 50 == 0)
    {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use the leftover: penalize proportional waste
            score += (next_item_size - post_residual).min(40) as f64 * 0.2;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin leaves a good fit
    // or when the stream is early and bins are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        score = 70.0 + 20.0 * progress - scarcity * 40.0
            + (open_bins_count as f64) * 1.5
            - (mean_residual / bin_capacity as f64) * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += (bin_capacity - next_item_size) as f64 * 0.1;
        }
    }

    // Mild preference for filling already-open bins when many are open.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + (post_residual - next_item_size) as f64 * 0.1;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: residual too small for next item -> penalize small leftovers.
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 80.0;
    }

    // Compare residual to mean residual: prefer bins that tighten the spread.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f) * 0.3;
    } else {
        score += (post_f - mean_residual) * 0.15;
    }

    // New-bin candidate: neutral baseline so it wins only when open bins are bad fits.
    if is_new_bin {
        score = bin_capacity as f64 * 0.9 + 50.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
    }

    // Slight late-stream conservatism: prefer tight packing as stream progresses.
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        0.0
    };
    score -= 12.0 * tightness;

    // Penalize dead space: post_residual too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            // next item won't fit here; penalize leaving awkward gap
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 30.0;
        // If many bins fit the item, opening new is wasteful.
        score += 10.0 * (fitting_bins_count as f64).min(5.0);
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If mean residual across open bins is large, use existing bins instead.
        score += (mean_residual - item_size as f64).max(0.0) * 0.4;
    }

    // Slight preference to fill bins that are already more depleted than average.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score -= 0.3 * diff;
    }

    // Mild penalty on proliferation of open bins.
    score += 0.05 * open_bins_count as f64;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: residual squared normalized, growing with stream progress
    let norm_pr = pr / cap;
    score += 60.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (small post_residual) with smooth cubic falloff
    score -= 25.0 * (1.0 - norm_pr).powi(3);

    // Lookahead coupling: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 15.0 * (nx - pr) / cap;
        } else {
            // smooth reward when next item fits into the leftover
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 10.0 * fit_quality * fit_quality;
        }
    }

    // Last-chance bonus: only one fitting bin strongly favors using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins when residuals are large
    let mean_dev = (mean_residual - pr).abs() / cap;
    score += 8.0 * mean_dev * mean_dev;

    // New-bin candidate: keep it slightly unattractive unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - item_size as f64 / cap) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear weighting
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    score = post_f * (1.0 + 0.02 * (post_f / cap_f) * (post_f / cap_f));

    // Harmonic class of post_residual: dead-space classes are bad.
    // Residuals that are multiples of 25 (quarter capacity) are "reusable" classes.
    let quarter = post_residual % 25 == 0 && post_residual > 0;
    if quarter {
        score -= 4.0;
    }
    // Very small residuals (< 10) are dead space unless zero
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    if post_residual == 0 {
        score -= 8.0; // perfect fill
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score += 0.05 * slack as f64;
            // harmonic classes: next item leaves a quarter-class residual
            if slack % 25 == 0 {
                score -= 2.0;
            }
        } else {
            // next item won't fit here; slight penalty for near-full bins
            score += 1.5;
        }
    }

    // Last chance: only bin that fits -> strong reward to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate: penalize so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 18.0 + 0.1 * open_bins_count as f64;
    } else {
        // Prefer fuller bins relative to the mean residual
        score -= 0.05 * (mean_residual - post_f).max(-20.0);
    }

    // Early stream: be slightly more willing to open bins for future flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.3 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any future
    // item (min item size 1, but practically small gaps < 10 are hard to reuse)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - post_residual as f64 * 3.0; // tiny gaps: up to +57
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is excellent
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize large leftover that is "wasteful" relative to item size:
    // placing a small item into a huge bin wastes the bin.
    if post_residual as f64 > 2.5 * item_size as f64 {
        score += 0.35 * (post_residual as f64 - 2.5 * item_size as f64);
    }

    // Open bins pressure: discourage spreading across many open bins.
    score += 1.2 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it, else a new bin opens.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // (mean residual far below item size) or item is huge.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            score -= 30.0 + (-mean_gap); // existing bins can't fit well -> new bin good
        } else {
            score += 25.0 + mean_gap * 0.8; // existing bins fine -> new bin bad
        }
        if item_size >= 70 {
            score -= 10.0; // big items are hard to place later
        }
        if post_residual < 10 {
            score += 40.0; // never open a bin to create a tiny dead gap
        }
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Early stream: be slightly conservative with opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect or near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 120.0;
        // Extra bonus if next item fills the bin nearly completely after placement.
        let post2 = post_residual - next_item_size;
        if post2 == 0 {
            score -= 300.0;
        } else if post2 <= 5 {
            score -= 150.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residual that the next item cannot use (dead space).
        score += 60.0;
        // Penalize more when the leftover is small-but-unusable (worst dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins could still fit the item,
    // unless the item is large and fits almost exactly.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = post_residual as f64 + 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 120.0;
        }
        if fit_ratio > 0.7 {
            new_bin_score -= 100.0;
        }
        // Late in the stream, be more reluctant to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += progress * 50.0;
        score = score.max(new_bin_score.min(score + 200.0));
        score = new_bin_score;
    }

    // Slight penalty for wasting large residual space with a small item.
    if post_residual > 40 {
        score += (post_residual - 40) as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear penalty on wasted space.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can never be used again given the size range.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are waste
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else {
        // Mild penalty when many alternatives exist, encouraging spreading load.
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect pairing
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if we leave large awkward gap
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, allow opening new bins for better long-run packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax later; also penalize when few bins open.
        score += 15.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If no open bin fits well (large item), allow new bin more readily.
        if item_size > bin_capacity / 2 {
            score -= 10.0 * progress;
        }
    } else {
        // Filling existing bins slightly preferred overall.
        score -= 3.0;
        // Prefer bins whose residual deviates favorably from the mean (below-mean residual = tighter bin).
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Global pressure: many open bins with high mean residual -> consolidate into fullest bins.
    if open_bins_count > 2 && mean_residual > 40.0 {
        score += 0.1 * (bin_residual as f64 - mean_residual);
    }

    // Small coupling: reward placing large items into large-residual bins.
    let size_frac = item_size as f64 / bin_capacity as f64;
    let resid_frac = bin_residual as f64 / bin_capacity as f64;
    score -= 5.0 * size_frac * resid_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post_norm * (1.0 + 0.8 * progress * progress);

    // Penalize large unusable dead space more than proportionally
    score += 0.6 * post_norm * post_norm;

    // Reward tight fits (small post residual), stronger late in the stream
    score -= (1.0 - post_norm) * (0.5 + 1.5 * progress);

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Slight preference for bins below mean residual (balancing load)
    score += 0.1 * ((bin_residual as f64) - mean_residual) / cap;

    // Lookahead: reward bins whose post residual can still host the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 1.0 + 0.5 * (1.0 - post_norm);
    }

    // Mild pressure against accumulating many open bins
    score += 0.02 * open_bins_count as f64 * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity / k
    let class = post_residual % (bin_capacity / 4).max(1);
    score += class as f64 * 0.35;

    // Reward near-perfect fits (small post residual)
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 8 {
        score -= 12.0;
    }

    // Penalize dead space: post residual too small for any future item (min size 1)
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // dead space of awkward size
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        let rem = post_residual - next_item_size;
        score -= 10.0 * (1.0 - rem as f64 / bin_capacity as f64);
        // penalize if leftover after next item is dead space
        if rem > 0 && rem < 10 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 45.0;
        // if the item is large relative to capacity, a fresh bin is attractive
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
        // if no other bin fits, opening a bin is fine
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // early in stream, fresh bins are cheap (long stream ahead to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins below mean residual (filling emptier bins keeps tight bins flexible)
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.15;
    }

    // Harmonic modulo classes on item size: large items into tight bins
    let item_class = item_size / 20; // coarse class 0..4
    score -= item_class as f64 * (bin_capacity - bin_residual) as f64 * 0.02;

    // Integer division threshold on post_residual quarters
    let quarter = bin_capacity / 4;
    match post_residual / quarter.max(1) {
        0 => score -= 8.0,   // <25% left: good packing
        1 => score += 0.0,
        2 => score += 3.0,
        _ => score += 6.0,   // >75% left: wasteful placement
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual is "dead" if it is too small to hold even the smallest
    // plausible item (assume min size ~1, but practically gaps < 12 are poor).
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 3.0;
    }
    // Perfect fit: zero waste is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight-fit reward: leaving a gap that exactly matches the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap the lookahead item cannot use but could fragment.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 25 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading further
    // unless the fit is good; with few bins, opening is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 2.0;

    // Prefer bins whose residual is already below average (consolidation).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 10.0;

    // Brand-new empty bin: only attractive when it produces a perfect
    // structural split (item <= half capacity) and few alternatives exist.
    if bin_residual == bin_capacity {
        if item_size * 2 <= bin_capacity && fitting_bins_count <= 2 {
            score -= 10.0;
        } else {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: nothing wasted.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward exact match between post_residual
    // and the next item size (this bin absorbs two items perfectly).
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 80.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact two-item match: huge bonus.
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // Penalize residuals just slightly too small for the next item
        // (dead space that likely can never be used).
        if (post_residual as i64) < (next_item_size as i64) {
            score += 25.0;
        }
    }

    // Reward tight fits relative to item size.
    score -= 30.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Compare against mean residual: bins with less residual than average
    // are "tighter" and better candidates.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Penalize leaving very small unusable residuals (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Mild penalty for opening new bins when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead: if next item fits into post_residual, this bin stays useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain potential: reward, scaled by how snugly the next item fits.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Bin becomes dead space for the next item: penalize large residuals.
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize new-bin candidate unless it's genuinely needed.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 400.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early on, prefer filling open bins; later, new bins are cheaper.
        score += 350.0 - 150.0 * progress - scarcity;
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    }

    // Global state coupling: prefer bins far from the mean residual (diversity of sizes).
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs());

    // Prefer filling bins with the largest residual when many bins are open.
    score -= 0.3 * bin_residual as f64 * (open_bins_count as f64).ln().max(1.0) / 10.0;

    // Small penalty for very small unusable leftovers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth in (0,1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Normalized residuals
    let post_n = post_residual as f64 / cap;
    let item_n = item_size as f64 / cap;
    let mean_n = mean_residual / cap;

    // Non-linear waste penalty: dead space is quadratic in smallness of post-residual,
    // amplified later in the stream when consolidation matters most.
    let waste = (1.0 - post_n) * (1.0 - post_n);
    score += 40.0 * waste * (0.5 + 0.5 * prog2 + prog3);

    // Reward tight fits: smooth bonus peaking when post_residual is near zero
    let tightness = (-8.0 * post_n).exp();
    score -= 30.0 * tightness * (0.6 + 0.4 * progress);

    // Reward filling the bin relative to current mean residual state
    score -= 10.0 * item_n * (1.0 + mean_n) * (1.0 - prog3);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 15.0 * (1.0 - slack) * (1.0 - slack);
    } else if next_item_size > 0 {
        // Next item won't fit: mild penalty growing with stream progress
        score += 8.0 * (0.5 + 0.5 * progress);
    }

    // Penalize scattering across many open bins when residuals are fragmented
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * mean_n * (1.0 - prog2);

    // New-bin candidate handling: empty bin gets a base cost that shrinks as the
    // stream progresses, so late in the stream we prefer squeezing into open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - prog3);
        // But allow a new bin if item is huge and would leave a very poor residual anywhere
        if item_n > 0.7 {
            score -= 15.0 * (item_n - 0.7) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: slivers that no item (min size 1..) can use well
    if post_residual > 0 && post_residual < 5 {
        score -= 45.0; // near-perfect fill, almost no waste
    } else if post_residual < 15 {
        score -= 25.0; // small dead space, likely unusable
    }

    // Modulo classes: residuals divisible by common item sizes stay reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 18.0;
        } else if post_residual % 25 == 0 {
            score -= 14.0;
        } else if post_residual % 5 == 0 {
            score -= 8.0;
        }
    }

    // Integer-division thresholds on post_residual (capacity fractions)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score += 12.0; // leaving half a bin free is wasteful commitment
    } else if post_residual >= quarter {
        score += 4.0;
    }

    // Lookahead coupling (k=2)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 350.0; // next item exactly fills this bin
        } else if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.6;
        } else {
            // next item cannot fit here: residual becomes dead space
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: avoid opening a new bin when only one bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        // prefer new bin only for large items or when few bins fit
        score += 90.0 - 70.0 * frac;
        if fitting_bins_count > 2 {
            score += 30.0; // plenty of alternatives; spreading is wasteful
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // new bin can host the next item too
        }
    }

    // Stream progression: later in stream, consolidate into open bins
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 12.0 * t;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter packs)
    score += (mean_residual - post_residual as f64) * 0.05;

    // Mild penalty for many open bins relative to progress
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 6.0; // gap too small for any item (min size 1..100 stream)
    } else if dead >= 10.0 && dead < 20.0 {
        score += (20.0 - dead) * 2.0; // risky narrow gap
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving space exactly matching the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap smaller than the next item wastes it.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 5.0 + open_bins_count as f64 * 2.5;
    } else {
        score -= 1.0;
    }

    // Slight preference for bins tighter than the current mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late-stream consolidation: tighten packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += dead * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= 25.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(6);

    // 2-step lookahead: strongly reward bins whose post_residual can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack after also placing the next item: smaller slack is better.
            let two_step_slack = post_residual - next_item_size;
            score -= 18.0 * (1.0 - (two_step_slack as f64) / (bin_capacity as f64)).powi(5);
        } else {
            // Penalize residual that wastes space just below the next item size
            // (dead space the lookahead cannot use).
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * gap.sqrt();
        }
    }

    // Compare against mean residual: prefer consuming bins with above-average space
    // (keeps many small residuals from accumulating).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 6.0 * (mean_residual - res).sqrt();
    } else {
        score += 4.0 * (res - mean_residual).sqrt();
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild preference for keeping the number of open bins low early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing else fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post residual gets strong discount.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (post_residual as f64);

    // Penalize leaving awkward small gaps that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if next item can use the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64) / (post_residual as f64).max(1.0);
        } else {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.25 * waste.min(60.0);
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // later, allow opening new bins more freely when residuals are poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 15.0 * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        // New bin candidate: base penalty plus residual (full).
        score += new_bin_penalty;
        score -= 2.0 * open_bins_count as f64;
        // Opening a new bin is attractive if existing residuals are large relative to item.
        if mean_residual > (item_size as f64) * 1.5 {
            score -= 10.0;
        }
    } else {
        // Existing bin: slight preference as open bins grow (fill them).
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer using larger residual bins when item is large (avoid opening bins for big items).
    if item_size > 50 && bin_residual >= item_size {
        score -= 0.2 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic-ish preference for small post residual, smooth.
    let mut score = x * x * 40.0 + x * 10.0;

    // Non-linear coupling with stream progress: early on, tolerate larger leftovers;
    // late in the stream, squeeze tightly (progress-weighted penalty).
    score += 30.0 * x * x * (1.0 - progress) * (1.0 - progress) - 20.0 * x * progress;

    // Perfect fit reward (smooth bump near zero residual).
    score -= 15.0 * (-pr / 5.0).exp();

    // Dead-space penalty: residual too small to ever fit typical items (min size ~1..10).
    let dead = (10.0 - pr).max(0.0) / 10.0;
    score += 25.0 * dead * dead;

    // Lookahead coupling: reward residual that still fits the next item, penalize near-miss.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin when it wastes capacity,
    // scaled by how many open bins already exist and mean residual.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        score -= 10.0 * (mean_residual / cap).min(1.0);
    }

    // Mild preference to keep bin count low: reward filling already-open bins.
    score -= 3.0 * (1.0 - x) * (open_bins_count.min(20) as f64 / 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes in integer division buckets.
    let class = post_residual / 10; // 0..10 harmonic class
    // Penalize awkward classes (small but unusable slivers) more than exact fits.
    score += match class {
        0 => -40.0,                 // perfect fit: post_residual == 0
        1 => 15.0,                  // 1..10 sliver: worst dead space
        2 => 6.0,                   // 10..20
        3 => 2.0,                   // 20..30
        4 => -2.0,                  // 40..50: half-capacity-ish, reusable
        5 => -5.0,                  // 50..60
        6 => 0.0,
        7 => -3.0,                  // 70..80
        8 => -6.0,                  // 80..90
        _ => -10.0,                 // 90..100: near-empty, very reusable
    };

    // Harmonic coupling with next item: reward residuals that can host next item exactly
    // or in the same decade class.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0;      // chains a perfect fit for the lookahead
            } else if slack / 10 == class {
                score -= 8.0;       // next item leaves residual in same harmonic class
            } else {
                score -= (slack as f64) * 0.15;
            }
        } else {
            // next item won't fit here; penalize proportionally to how much it misses
            let miss = next_item_size - post_residual;
            score += (miss as f64) * 0.25;
        }
    } else {
        // last item: just minimize waste
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // competition: mildly prefer tighter fits among many candidates
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: only attractive when current bin would leave a bad class
    // and the stream is early enough to amortize the new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = class > 0 && class < 4; // sliver-producing placement
        if bad_fit && progress < 0.7 {
            score -= 18.0;
        } else {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Modulo-25 harmonic bonus: residuals divisible by 25 align with quarter capacity.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the smallest
    // plausible item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        // small gaps are semi-unusable: graded penalty
        score += (25.0 - post_residual as f64) * 2.5;
    }

    // Reward tight fits (post_residual close to zero but still usable).
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        // fraction of bin consumed by this item: tighter is better
        let fill = item_size as f64 / bin_capacity as f64;
        score -= fill * 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins early,
    // but relax late in the stream when consolidation matters less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).powf(1.4) * (1.2 - 0.5 * progress);
    score += pressure * 0.8;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.5;

    // Lookahead: if the next item could exactly use the leftover space,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.4;
    }
    // If next item would NOT fit leftover, leftover is likely dead space.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(30) {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + item_size as f64 * 0.1;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and
    // mean residual suggests consolidation is possible; allow it when the
    // item is large and fits would leave bad gaps anyway.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        } else {
            let waste_here = (bin_capacity - item_size) as f64;
            let best_open_gap = mean_residual - item_size as f64;
            // opening is attractive only if every open fit would waste more
            score += 35.0 + waste_here * 0.3 - best_open_gap.max(0.0) * 0.6;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // 2-step lookahead: reward if next item fits into post_residual exactly/well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let next_fit = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 35.0 * next_fit;
        } else {
            // next item cannot follow here: penalize wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 100.0);
        }
    }

    // Compare residual against mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += 2.0 * (post_residual as f64 - mean_residual);
    } else {
        score -= 1.5 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 45.0 * fill_frac;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Early stream: be more liberal opening bins to keep flexible residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 5.0 * (1.0 - progress / 0.3);
    }

    // Many open bins: discourage spreading, prefer consolidation
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: minimize wasted space nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing can use (below min item size 1..100 range,
    // treat residuals < 10 as dead weight since typical items are >= 10).
    if post_residual < 10 {
        score -= 15.0; // perfect-ish closure, reward
    } else if post_residual < 20 {
        score += 8.0; // awkward dead zone
    }

    // Lookahead: reward if next item fits exactly in post_residual; penalize if it barely misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty scaled by how much it misses
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 * (1.0 - (miss / bin_capacity as f64)).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive when many bins are open
    // or when the stream is early (future consolidation possible).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 35.0 + 20.0 * (1.0 - progress) + 5.0 * openness;
        // allow opening a new bin late in the stream when residuals are fragmented
        if progress > 0.8 && mean_residual < 15.0 {
            score -= 30.0;
        }
    }

    // Prefer bins below mean residual (they are the "tightest" bins): equalizing residuals
    // keeps a portfolio of usable gaps.
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // Mild penalty for very large open-bin count (fragmentation control).
    score += 0.2 * open_bins_count as f64 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open_c = open_bins_count as f64;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, compactness of residual space matters more.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress;
    score += poly * cap * 0.5;

    // Penalize dead space (small but nonzero residuals) more aggressively as stream advances.
    let dead = (norm_pr * (cap - norm_pr * cap)) / cap; // peaks mid-range
    score -= dead * (1.0 - progress) * 10.0;

    // Reward scarce fitting options (last-chance bin) with a smooth sigmoidal term.
    let scarcity = 1.0 / (1.0 + fit);
    score -= scarcity * 40.0 * (0.5 + progress);

    // Mild pressure against scattering across many open bins, growing with progress.
    score += open_c * progress * 2.0;

    // Lookahead: reward bins whose post residual accommodates the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let gap_norm = gap / cap;
        score += gap_norm * gap_norm * cap * (0.3 + 0.7 * progress);
        // Bonus if next item fits exactly-ish (tight chaining).
        score -= (1.0 - gap_norm).max(0.0) * 15.0;
    }

    // Slight pull toward bins near the mean residual (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * cap * 0.25;

    // New-bin candidate: penalize opening a new bin smoothly, stronger late in stream.
    if bin_residual == bin_capacity {
        score += cap * (0.6 + 0.8 * progress) + open_c * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes get strong rewards
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 12.0;
    } else if pr <= 20 {
        score -= 4.0;
    }

    // Modulo classes: residuals that pair with common item sizes (multiples of 10)
    let pr_mod10 = (pr % 10) as f64;
    score += pr_mod10 * 0.8; // penalize residuals not aligned to decade grid

    // If next item can exactly fill this bin's post-residual, big reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // next fits: reward proportionally to how tightly
        let tight = 1.0 - (pr - next_item_size) as f64 / cap;
        score -= 10.0 * tight;
    }

    // Dead-space penalty: post residual too small for any plausible item (min size 1..10)
    if pr > 0 && pr < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize when open bins are roomy
    if bin_residual == bin_capacity {
        score = cap * 0.75 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / cap);

    // Penalize bins far below mean residual (fragmentation avoidance)
    score += ((mean_residual - post_residual as f64).abs()) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly worthless.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 60.0 * (10.0 - gap); // unusable sliver -> heavy penalty
        } else if gap < 20.0 {
            score += 12.0 * (20.0 - gap) / 10.0; // hard-to-fill zone
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward filling most of the bin (waste ratio).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 8.0 + 15.0 * progress + 0.6 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: attractive only if current bin fit is poor.
        score += new_bin_penalty;
        // But if this bin would end with a tiny dead gap, opening a new bin is fine.
        if post_residual > 0 && post_residual < 10 {
            score -= new_bin_penalty * 0.9;
        }
    } else {
        // Using an existing bin slightly relieves pressure.
        score -= 0.15 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            if post_residual - next_item_size < 10 {
                score -= 6.0; // chain of perfect fits
            }
        } else if post_residual > 0 && next_item_size > post_residual {
            score += 5.0; // next item won't use this gap
        }
    }

    // Mean-residual coupling: prefer bins near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is good, but reward perfect fits extra).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (sets up a perfect follow-up).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item won't fit here after placement; slight penalty for wasting a slot
            score += 8.0;
        }
        // Reward leaving residuals that match typical item sizes
        if post_residual >= 10 && post_residual <= 40 {
            score -= 10.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are precious, use them well.
    let rel = (bin_residual as f64) - mean_residual;
    if rel < 0.0 {
        // tighter-than-average bin: reward filling it (it's hard to reuse)
        score -= 0.35 * (-rel);
    } else {
        // looser-than-average bin: penalize chipping small items off it
        score += 0.15 * rel;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize opening new bins, but less when the item is large relative to capacity
        // or when few bins can fit the item.
        let mut penalty = 45.0;
        penalty -= 0.25 * (item_size as f64);
        if fitting_bins_count == 0 {
            penalty -= 100.0; // no alternative: opening a bin is required
        } else if fitting_bins_count == 1 {
            penalty -= 30.0;
        }
        // Late in the stream, avoid spawning many nearly-empty bins
        penalty += 20.0 * progress;
        // If item leaves a large dead zone in a fresh bin and next item could share it, ok
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 10.0;
        }
        score += penalty;
    }

    // Mild tie-break: prefer bins with more residual used already (older bins)
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize large dead space, scaled by how "wasted" the bin is.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 40.0;
    score += (post_residual as f64).powi(2) * 0.15;

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
        // Extra reward if next item exactly fills the bin afterwards.
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover; penalize proportionally to leftover size.
        score += post_residual as f64 * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits) or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Base penalty so open bins are usually preferred.
        score += 120.0;
        // Discount the new bin when mean residual is high (fragmented bins)
        // or the item is large and would leave a big hole elsewhere.
        score -= (mean_residual / bin_capacity as f64) * 90.0;
        score -= big_item * 40.0;
        // Late in the stream, avoid spawning bins unless really needed.
        score += progress * 30.0;
        // If several bins fit already, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 60.0;
        }
    }

    // Mild preference for filling emptier bins when many bins are open.
    if open_bins_count > 4 {
        score += (bin_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, warped by a smooth polynomial in progress
    let p = progress;
    let warp = 0.5 + p * p * 1.5; // later in stream: care more about residual tightness
    let mut score = pr * warp;

    // Non-linear polynomial coupling of residual with progress
    let quad = x * x * (30.0 + 40.0 * p);
    let cubic = x * x * x * (10.0 - 20.0 * p);
    score += quad + cubic;

    // Perfect-fit reward, stronger as stream progresses
    if x < 1e-9 {
        score -= 25.0 + 25.0 * p;
    }

    // Penalize tiny unusable slivers (dead space), smoothly
    if pr > 0 && pr < item_size.max(1) {
        score += 8.0 * (1.0 - pr as f64 / item_size as f64);
    }

    // Last-chance bin: avoid opening a new bin, reward this one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: bonus if next item fits the post residual (chain packing)
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 5.0 + 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0 * (1.0 - p); // early on, keep room flexible
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).ln().max(0.0);
        let tight = ((mean_residual - pr) / cap).abs();
        score = 20.0 + crowded * 6.0 - tight * 10.0 - 20.0 * p * p;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as f64; // 8 harmonic octaves of residual
    score += class * 6.0;

    // Perfect-fit harmonic classes: residual that is a clean divisor-ish remainder
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual % 10 == 0 {
        score -= 40.0;
    } else if post_residual % 5 == 0 {
        score -= 15.0;
    }

    // Integer-division threshold: small post_residual relative to item granularity
    let small_grain = post_residual / 10; // usable slots of size 10
    score -= small_grain as f64 * 4.0;

    // Lookahead coupling: does post_residual accommodate the next item's class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.8;
            // harmonic bonus if next item leaves another clean remainder
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 25.0;
            }
        } else {
            // next item cannot fit here: penalize wasting this bin's future
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 / (mean_residual / 20.0 + 1.0);
        // opening a bin is good if mean residual is small (bins are tight)
        score += 30.0 + mean_residual * 2.0 - crowded * 3.0 - progress * 10.0;
        // never open a new bin if a near-perfect fit exists elsewhere
        if item_size % 10 == 0 && bin_residual - item_size < 10 {
            score += 200.0;
        }
    } else {
        // prefer tighter existing bins mildly
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Late-stream consolidation: favor filling bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 {
        score -= post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are unusable for the smallest
    // future item (size 1) are fine, but residuals that are too small for typical
    // items yet nonzero are the worst outcome. Penalize tiny non-zero gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tight-fit reward scaled by how snugly the item sits in the bin.
    let snugness = item_size as f64 / bin_residual.max(1) as f64;
    score -= snugness * 20.0;

    // Dead space relative to capacity: large leftovers are wasteful unless the
    // bin is a fresh empty bin candidate.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * 15.0;

    // Lookahead: if the next item fits exactly in the post-residual, this is a
    // golden placement; reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild bonus proportional to leftover after that.
        score -= 5.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: the leftover may become dead space; penalize
        // proportionally to how stranded it is.
        score += 8.0;
    }

    // Open-bins pressure: prefer consolidating into existing bins when many are
    // open; make new bins less attractive as open_bins_count grows.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor (large post_residual) or nothing fits elsewhere.
    if bin_residual == bin_capacity {
        // Base attractiveness of a fresh bin: neutral-ish, slightly above a
        // perfect fit, below a bad fit.
        score = 30.0
            + open_bins_count as f64 * 0.5
            - (next_item_size as f64 / bin_capacity as f64) * 10.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 5.0;
    }

    // Mean residual coupling: when open bins are on average quite full
    // (small mean residual), prefer placing into them to consolidate.
    if bin_residual != bin_capacity {
        score += (mean_residual - post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still host the next item: reward closeness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here afterwards; penalize wasted potential.
        let gap = (next_item_size - post_residual) as f64;
        score += 15.0 * (gap / cap);
    }

    // Penalize tiny unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 30.0 * (1.0 - post_residual as f64 / cap);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Compare against mean residual: prefer bins that reduce dispersion.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Late in the stream, consolidate: prefer existing bins over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward low post_residual non-linearly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else {
        // Penalize large dead space quadratically.
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);
    }

    // Perfect fill of a small residual (item exactly matches bin residual).
    if item_size == bin_residual {
        score -= 80.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack * 0.1; // exact next-fit bonus, decaying with slack
    }
    // If next item would NOT fit here, mildly penalize creating a bin that
    // strands the next item (unless post residual is already tiny).
    if next_item_size > post_residual && post_residual > 5 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins with high mean residual: encourage consolidating into
    // bins that are already partially filled (avoid bin proliferation).
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += consolidation * 0.05;
        // Prefer bins whose residual is below mean (denser bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when no
    // open bin offers a decent fit, i.e. when this empty bin would be the
    // best home. Penalize the fresh bin so it only wins on truly bad fits.
    if bin_residual == bin_capacity {
        // Base penalty: prefer reusing open bins.
        score += 40.0;
        // If many bins can fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
        }
        // Early in the stream, opening bins is cheaper (future items can
        // share); late in the stream, waste is locked in.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        // If the item is large relative to capacity, a fresh bin is natural
        // since leftovers are small anyway.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= large_item * 30.0;
        // If next item is large too, a fresh bin can host the pair.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild global pressure: when few bins fit the item anywhere, prefer
    // the bin that leaves the most usable residual for the future.
    if fitting_bins_count <= 2 {
        score -= post_residual as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with quadratic shaping
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Smooth non-linear coupling of post-residual with stream progress:
    // later in the stream, dead space becomes costlier
    let coupling = pr / cap;
    score += (pr * coupling) * (progress * progress * (3.0 - 2.0 * progress));

    // Penalize large post-residual relative to mean residual (wasted potential)
    score += 0.3 * (pr - mean_residual).abs() / cap;

    // Lookahead: reward leaving space that fits the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 2.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 1.5 * (ns - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Mild preference for existing bins over opening new ones early
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * progress;
    }

    // Slight penalty for spreading across too many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes; small classes are dead space.
    let class = post_residual % 10;
    if class > 0 {
        // penalize unusable slivers: residual < 10 can never fit any item
        score += (10 - class) as f64 * 2.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain-friendly: residual can host next item
            let chain_util = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_util;
        } else {
            // residual too small for next item -> likely dead space
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer fuller bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: penalize so we only open when existing fits are terrible
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if next item is huge and current item is small, opening may pay off
        if next_item_size > 60 && item_size < 40 {
            score -= 25.0;
        }
    }

    // Progress term: later in stream, tighten packing (favor tight fits more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1..=100 unknown, assume >=10 typical) are waste.
    // Penalize "unusable" small gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits strongly (waste minimization core).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 30.0;

    // Perfect fit: near-zero residual gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open-bins pressure: prefer consolidating into existing bins when many
    // are open; discourage spreading across too many bins.
    score += open_bins_count as f64 * 1.5;

    // Encourage using bins whose residual is already below mean (filling
    // nearly-full bins first, classic best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid needless bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive if
    // the item is large relative to capacity or fits would leave big gaps.
    if bin_residual == bin_capacity {
        // baseline cost of a new bin
        score += 20.0;
        // but if the item is big, a fresh bin wastes little
        score -= (item_size as f64 / bin_capacity as f64) * 25.0;
        // if placing in an existing bin would leave a large residual that
        // cannot host the lookahead item, fresh bin becomes attractive
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    // Lookahead synergy: residual after placement that exactly fits the next
    // item is valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Late-stream consolidation: near the end, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
