pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tight * tight;

    // Penalize dead space that no future item could plausibly use.
    let usable = |r: u32| (r >= 10) as f64;
    if usable(post_residual) == 0.0 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += 10.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        // More alternatives -> slight penalty for hoarding this one's space.
        score += 2.0 * (fitting_bins_count as f64).min(8.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits for the item.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual - item_size as f64).max(0.0) / (bin_capacity as f64);
        // Base cost of a fresh bin, discounted when open bins have large residuals
        // that the item fits poorly in (pressure high) or few bins fit.
        score = 100.0
            - 30.0 * pressure
            - (if fitting_bins_count <= 1 { 45.0 } else { 0.0 });
        // Late in stream, prefer consolidation over new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 15.0; // fresh bin guarantees room for lookahead
        }
        return score;
    }

    // Prefer fuller bins relative to the fleet average.
    score -= 8.0 * ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);

    // Mild preference to keep number of open bins low early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.5 * (open_bins_count as f64);

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: penalize leftover space, non-linearly (dead space grows quadratically in importance)
    let mut score = post;

    // Quadratic coupling of post_residual with stream progress:
    // early on, large leftovers are tolerable; late, they become costly.
    score += 2.0 * progress * (post * post) / cap;

    // Tightness reward: smooth polynomial in fill ratio after placement.
    let fill = 1.0 - post / cap;
    score -= 30.0 * fill * fill * fill;

    // Penalize bins whose residual is far below mean (already poor), reward above-mean slack usage.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        // More fitting bins -> mild penalty to encourage consolidation into tightest ones
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in the post residual, reward; if it barely misses, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * (-gap / nxt).min(1.0);
        }
    }

    // New-bin candidate: penalize opening a new bin, more so early (amortization) and
    // when many bins are already open but slack exists elsewhere.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 40.0 + 30.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
        // Allow new bin only if item is huge and no tight fit exists
        score -= 20.0 * (item / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo 10 defines "usable" classes
    let post = post_residual;
    let class = post % 10;
    // Class 0 residuals are perfectly reusable for the 10..80 integer regime
    if class == 0 {
        score -= 12.0;
    } else if class <= 2 {
        score += 6.0; // tiny slivers are dead space
    } else if class >= 8 {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Exact-fill reward
    if post == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post {
            // Next item fits: reward proportionally, especially tight fits
            let slack = (post - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize, worse if residual large but unusable
            let waste = post as f64 / bin_capacity as f64;
            score += 6.0 + 10.0 * waste;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    let fill_frac = 1.0 - (post as f64 / bin_capacity as f64);
    score -= fill_frac * 8.0;

    // Early stream: be pickier about wasting space; late stream: consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * fill_frac;

    // Mean-residual coupling: if this bin's residual is far below mean, it's already tight — favor it
    let dev = mean_residual - post as f64;
    if dev > 0.0 {
        score -= (dev / 20.0).min(6.0);
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
        if next_item_size > 0 && next_item_size > post.max(item_size) && fitting_bins_count <= 1 {
            score -= 15.0; // open fresh bin for big upcoming item
        } else {
            score += 10.0 + crowded * 0.5; // discourage proliferation
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // Dead space = residual too small to hold even the smallest plausible item.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual <= 15 {
            score += 25.0;
        }
        // Nonlinear penalty for gap just below next item size (near-miss waste).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Perfect fit bonus.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Reward bins whose residual was already small (tight packing pressure).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Open-bin pressure: with many open bins, prefer reusing existing ones;
    // with few open bins, allow opening new bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize moderately so it's chosen only when
    // open bins would create bad dead space; scale with stream progress.
    if bin_residual == bin_capacity {
        score += 45.0 + 25.0 * progress;
        // But if next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 15.0;
        }
        // Early in stream, opening bins is cheap.
        if progress < 0.2 {
            score -= 20.0;
        }
    }

    // Mild preference for bins below mean residual (use up fuller bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: minimize post_residual aggressively (quadratic).
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 20.0;

    // Perfect fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: strongly reward when next item fills post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Chain fit: next item leaves small gap -> excellent packing.
        score -= 30.0 / (1.0 + gap / 10.0);
        // Exact chain fit is ideal.
        if gap == 0.0 {
            score -= 40.0;
        }
    }

    // Penalize post_residual that is too small for any future item (dead space).
    // Items are 1..100, so residual < some small threshold is likely wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to next item, scaled by how close we are to the end.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (next_item_size - post_residual) as f64 * (1.0 + progress);
    }

    // Relative-to-mean coupling: prefer bins whose residual is tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening new bins.
        score += 35.0;
        // But if next item is large and current post_residual would be tiny,
        // a fresh bin may be justified: relax the penalty.
        if next_item_size > 0 && post_residual < next_item_size.min(15) {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Slight preference for tighter bins overall.
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space nonlinearly (small leftovers are hard to reuse).
    if post_residual > 0 {
        let pr = post_residual as f64;
        score += 0.6 * (pr / 10.0).powf(1.7);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 3.0; // next item won't fit here; mildly deprioritize
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 30.0 && open_bins_count > 2 {
        score -= 0.05 * mean_residual * (open_bins_count as f64).sqrt();
    }

    // New-bin candidate logic: only attractive early or when this fit is terrible.
    if bin_residual == bin_capacity {
        let bad_fit = fit_ratio < 0.35 && post_residual as f64 > 45.0;
        if bad_fit && progress < 0.9 {
            score -= 8.0 + 10.0 * (1.0 - fit_ratio);
        } else {
            score += 20.0 + 15.0 * progress; // prefer existing bins later in stream
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear waste pressure: quadratic post-residual scaled by capacity
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    score += 0.6 * norm_pr * norm_pr * cap;

    // Polynomial coupling of post-residual with stream progress:
    // later in the stream, tight fills matter more -> reward small post_residual
    let coupling = (norm_pr - 0.5) * (norm_pr - 0.5);
    score -= (1.0 - progress) * 3.0 * (0.25 - coupling) * cap * 0.1;
    score += progress * 2.0 * coupling * cap * 0.05;

    // Reward near-perfect fits with a smooth cubic bonus
    let tightness = 1.0 - (pr / cap);
    score -= 4.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 1.5 * (nx - pr) / cap;
        }
    }

    // Prefer bins below mean residual (concentrate waste) with smooth term
    score += 0.8 * ((bin_residual as f64) - mean_residual) / cap;

    // Slight preference to reuse existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 2.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are exact capacity
    // fractions are "harmonic" (reusable by common item sizes), others are dead space.
    let harmonic: [u32; 9] = [0, 10, 20, 25, 30, 40, 50, 60, 80];
    let is_harmonic = harmonic.contains(&post_residual);
    if is_harmonic {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Strong reward when next item nearly fills the bin completely
        if post_residual - next_item_size <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this residual: penalize proportionally to waste
        score += (post_residual as f64) * 0.3;
    }

    // Last chance: this is the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Prefer tightest fit implicitly via post_residual, but slight
        // penalty for spreading across many candidate bins
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let base = 30.0 + (post_residual as f64);
        // Early in stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = base + 20.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        // If this bin is the only fitting option, opening a new bin is bad.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a tight-fit direction
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Small coupling: penalize leaving residuals that no typical item (1..100)
    // in the lower harmonic classes can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64;
    }

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Slight preference for tighter bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * (0.3 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits: small post_residual is good dead-space-wise.
    if post_residual == 0 {
        score -= 200.0; // perfect closure
    } else if post_residual <= 5 {
        score -= 80.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0; // chain: this bin closes perfectly after next item
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack * 0.8; // moderate reward, decaying with slack
        } else {
            // next item cannot use the leftover: leftover becomes dead space
            score += (post_residual as f64) * 0.5;
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving a residual close to mean keeps bins interchangeable; large deviation is bad.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless all alternatives are bad.
    if bin_residual == bin_capacity {
        score += 70.0;
        // Early in stream, opening new bins is cheaper (more future flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 55.0;
    }

    // Slight penalty for leaving residuals in the awkward 20..40 "dead zone"
    // that few item sizes can use.
    if post_residual >= 20 && post_residual <= 40 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual is close to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize leaving small unusable gaps (< 10) but less if gap is tiny.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 4.0;
        }
        // Chain fit quality: prefer post_residual close to next item size.
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.15 * gap;
    } else {
        // Last item: prefer filling bins as fully as possible.
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.5 * open_bins_count as f64;
        // Late in stream, slightly discourage new bins (less time to amortize).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins below mean residual (spread load evenly) mildly.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Prefer more-filled bins early (fewer bins), less aggressively late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = 1.0 - pr / cap;
    let mut score = pr;
    // reward tight fits non-linearly
    score -= 40.0 * tight * tight;
    // exact fit bonus
    if pr == 0 { score -= 100.0; }
    // penalize small dead space (unusable slivers) with smooth polynomial
    let sliver = (pr / cap) * (1.0 - pr / cap);
    score += 30.0 * sliver * (1.0 - progress);
    // lookahead coupling: favor bins leaving room for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = 1.0 - ((pr - nx).abs() / cap);
        score -= 25.0 * compat.max(0.0) * compat * (1.0 - progress);
        if nx > pr { score += 15.0 * (1.0 - progress); }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 { score -= 35.0; }
    // prefer fuller bins among many open bins
    score += 5.0 * (open_bins_count as f64).ln() * (pr / cap);
    // mean residual pull
    score += 10.0 * (pr - mean_residual) / cap;
    // late stream: consolidate more aggressively
    score -= 20.0 * progress * tight;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are dead weight; punish them super-linearly.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // exact fit: perfect, but guard anyway
    }
    let dead_threshold = 10u32; // smallest classic item size
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 12.0;
    }

    // Reward tight fits (small non-zero post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or fits nowhere else well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins mildly; open_bins pressure raises this.
        score += 25.0 + 8.0 * open_bins_count as f64;
        // If item fills a new bin well, encourage it.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 60.0;
        // If this is the ONLY fitting bin, strongly prefer using it over new bin.
        if fitting_bins_count == 1 {
            score += 400.0;
        }
        // Lookahead: if next item could pair with the leftover, opening is better.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strong reward to avoid opening a new bin.
        score -= 150.0;
    }

    // Lookahead synergy: leftover that can host the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size).min(20) as f64 * 1.5;
    } else if next_item_size > 0 {
        // Leftover cannot host next item: mild dead-space penalty.
        score += 10.0;
    }

    // Open bins pressure: prefer packing into existing bins when many are open.
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: bins far below mean residual are good targets
    // (they absorb space that would otherwise be stranded).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (is_new_bin as i32 as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by mean residual context.
    score += 0.35 * (post_residual as f64 - mean_residual).max(-50.0);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as f64 >= next {
            // Perfect chain: item fits exactly next step -> strong reward.
            score -= 18.0 * (1.0 - diff / 50.0).max(0.0);
        } else {
            // Slightly too small leftover: mild penalty.
            score += 0.25 * diff;
        }
        // If neither this bin nor post-residual can host next item, penalize
        // leaving fragmented space unless post_residual is near zero.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.10 * post_residual as f64;
        }
    } else {
        // Last item: minimize leftover directly.
        score -= 5.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let poor_fit = (fitting_bins_count == 0)
            || (post_residual as f64 - mean_residual > 15.0 && fitting_bins_count <= 2);
        if poor_fit {
            score -= 8.0;
        } else {
            // Penalize opening new bins when existing bins fit reasonably.
            score += 14.0 + 2.0 * open_bins_count as f64 * 0.1;
        }
    }

    // Early in stream: be slightly conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 0.05 * post_residual as f64;
    }

    // Dead-space penalty for large unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0; // tiny leftover is excellent (near-perfect packing)
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 80.0 + 10.0 * (6 - post_residual) as f64;
    }

    // Penalize large leftover space relative to typical item sizes.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste * waste;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 25.0 + 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // leftover too small for next item: penalize proportionally to dead space
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 40.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: only attractive when the item is big and few bins fit it.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let openness = open_bins_count as f64;
        score = 30.0
            + 40.0 * (1.0 - item_frac)              // small items don't deserve fresh bins
            + 25.0 * (1.0 - progress)               // early on, be a bit more willing
            - 12.0 * openness.min(6.0)              // many open bins: prefer reusing
            - 20.0 * mean_residual / 100.0;         // plenty of slack available: reuse
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 10.0; // big item now, keep flexibility for smaller next
        }
    }

    // Mild preference for filling fuller bins among equals.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fill = 1.0 - (bin_residual as f64) / cap;

    // Base: minimize post_residual (tight fit preferred)
    let mut score = norm_pr;

    // Smooth polynomial coupling: tightness valued more as stream progresses
    score -= 0.35 * fill * (t * t * (3.0 - 2.0 * t)) * (1.0 - norm_pr * norm_pr);

    // Quadratic penalty on dead space that is unlikely usable
    let dead = if next_item_size > 0 {
        (norm_pr - (next_item_size as f64 / cap)).max(0.0)
    } else {
        norm_pr
    };
    score += 0.5 * dead * dead;

    // Smooth scarcity bonus: last fitting bin gets rewarded via sigmoid-like term
    let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 0.25 * scarcity * (1.0 - norm_pr);

    // Mild pull toward bins with low mean residual (keeps large spaces free)
    score += 0.10 * ((mean_residual / cap) - norm_pr).abs();

    // New-bin candidate: penalize slightly, relax as stream progresses
    if bin_residual == bin_capacity {
        score += 0.30 - 0.20 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "dead"
    // (too small for the smallest plausible item, <= 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Dead space relative to the lookahead item: if the next item cannot fit
    // into the post-residual, this placement wastes the remainder.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (post_residual as f64);
    }

    // Reward exact / near-exhausting placements (harmonic residue class 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Modular classes on post_residual: quantize it into capacity-fraction
    // buckets and prefer buckets that keep future pairings feasible.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    score -= match class {
        0 => 15.0, // very tight fit, excellent
        1 => 6.0,  // roomy enough for a mid item
        2 => 0.0,  // neutral
        _ => -4.0, // nearly empty bin, opening fresh is fine
    };

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral baseline anchored to mean residual.
    if bin_residual == bin_capacity {
        score = mean_residual * 0.5 + 8.0;
        // Open a new bin when existing fits are all poor (large post_residual
        // or dead-space creation) or the lookahead pairs badly.
        if next_item_size > 0 {
            let pair_waste = if post_residual >= item_size + next_item_size { 0.0 } else { 10.0 };
            score += pair_waste;
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // Early in the stream, fresh bins are cheap; late, prefer packing.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Slight preference to fill bins that are already below mean residual
    // (consolidation of partial bins).
    if bin_residual != bin_capacity {
        let res_f = bin_residual as f64;
        if res_f < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range)
    // are pure waste. Penalize gaps below the minimum item size heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Penalize gaps that cannot hold the lookahead item but could hold other items:
    // mild penalty proportional to the mismatch.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Perfect fit: fully reward closing a bin exactly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the item size (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - waste_ratio) * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 20.0 + 6.0 * open_bins_count as f64 + 15.0 * progress;
        // But if no open bin fits well (this call only happens for the new bin),
        // keep it viable: the base comparison handles it.
    } else {
        // Slight pressure to fill existing bins when many are open.
        score -= 0.3 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor)
    score += 0.5 * ((bin_residual - item_size) as f64).abs() * 0.1;

    // Align with mean residual: bins far below mean residual are "emptier";
    // filling emptier bins is slightly less valuable than filling tight ones.
    score += 0.2 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 8.0 / (1.0 + tightness * 4.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after next placement
            let second_left = post_residual - next_item_size;
            score -= 20.0 / (1.0 + second_left as f64 / 10.0);
        } else {
            // next item won't fit here: penalize leaving a gap that traps it
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are wasteful targets
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.4;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when current bin would be
    // left with unusable dead space and the item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_residual - item_size) as f64;
        score = 15.0 + waste * 0.5 - 25.0 * progress * (1.0 - waste / bin_capacity as f64);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual nonlinearly
    let fit = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit * fit;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Dead-space penalty: leftover that no future item (>=1) can use well
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - t);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: check whether next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain two items into this bin
            score -= 10.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else if next_item_size <= bin_residual {
            // Next item fits in residual but not post-residual: bad to place here
            score += 10.0;
        }
        // Penalize leaving residual too small for the average item
        if post_residual > 0 && (post_residual as f64) < (item_size as f64 * 0.25) {
            score += 5.0 * (1.0 - t);
        }
    }

    // New-bin candidate logic: empty bin gets a moderate default score;
    // prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        let base = 30.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Early in stream, opening new bins is cheap; later it is expensive
        score = base * (0.5 + t) + 0.3 * mean_residual;
    }

    // Prefer filling bins that are already mostly full (best-fit flavor)
    score -= 0.2 * (bin_capacity - bin_residual) as f64;

    // Slight penalty when many bins are open (encourage consolidation)
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * pr / cap) - 0.5 * it * (pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late, strongly punish wasted space
    let coupling = pr * pr / cap * (0.5 + 2.5 * progress * progress + 2.0 * progress);
    score += coupling;

    // Reward tight fits smoothly (item_size close to bin_residual)
    let tightness = (it / bin_residual as f64).clamp(0.0, 1.0);
    score -= 6.0 * tightness * tightness * (1.0 + progress);

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Lookahead: reward leaving space usable by the next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        let fit = 1.0 / (1.0 + diff * diff / (cap * cap) * 4.0);
        score -= 5.0 * fit;
        // penalize post-residual that is just barely unusable
        if pr < nx {
            score += 3.0 * (1.0 - pr / nx.max(1.0)) * (1.0 + progress);
        }
    }

    // Mild pressure against bin proliferation, scaled by stream progress
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Pull score toward mean-residual-aware target: prefer bins near mean slack
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev * cap * (0.3 + 0.7 * progress);

    // New-bin candidate: baseline score so it wins only when open bins score poorly
    if bin_residual == bin_capacity {
        score = 30.0 + 20.0 * progress - 3.0 * (it / cap) * 10.0;
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            if bin_capacity as f64 - it >= nx {
                score -= 6.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod small divisors reveals
    // how "reusable" the leftover space is for common item sizes.
    let pr = post_residual;
    let mut bonus = 0.0;

    // Residuals divisible by 10 align with the classic size grid.
    if pr % 10 == 0 && pr > 0 {
        bonus -= 6.0;
    }
    // Residuals divisible by 5 are second-class reusable.
    if pr % 5 == 0 && pr % 10 != 0 {
        bonus -= 3.0;
    }
    // Odd residuals are hardest to fill.
    if pr % 2 == 1 {
        bonus += 2.0;
    }

    // Perfect-fit reward.
    if pr == 0 {
        bonus -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            bonus -= 40.0;
        } else if next_item_size <= pr {
            bonus -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; penalize small leftovers less if they
            // belong to a "harmonic" class (mod 10).
            if pr % 10 == 0 {
                bonus += 1.0;
            } else {
                bonus += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        bonus -= 8.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Baseline cost of a fresh bin grows slightly over stream.
        bonus += 15.0 + 5.0 * progress;
        // If many bins open and mean residual high, discourage new bin.
        bonus += 0.5 * (open_bins_count as f64).sqrt();
        bonus += 0.2 * mean_residual;
        // But if current item is large relative to capacity, new bin is fine.
        bonus -= (item_size as f64 / cap) * 10.0;
    }

    // Penalize tiny dead space that is not harmonically aligned.
    if pr > 0 && pr < 10 {
        bonus += (10 - pr) as f64 * 0.5;
    }

    // Mild tightness reward: bins with small residual before placement are precious.
    let tight = (bin_residual as f64) / cap;
    bonus -= (1.0 - tight) * 4.0;

    score + bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }
    // Small-but-usable gaps are also risky if the next item can't use them.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.5 * post_residual as f64;
    }
    // Reward exact/near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }
    // Reward bins that can also host the lookahead item (chain fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.3 * (post_residual - next_item_size) as f64;
    }
    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.35 * open_bins_count as f64;
    // Prefer bins with residuals below the mean (consolidate emptier space elsewhere).
    score += 0.2 * (mean_residual - post_residual as f64);
    // New-bin candidate: attractive early, or when it enables a big lookahead chunk.
    if bin_residual == bin_capacity {
        score -= 18.0;
        if next_item_size > 0 {
            score -= 0.1 * next_item_size as f64;
        }
        if open_bins_count > 0 && post_residual as f64 > mean_residual + 20.0 {
            score += 30.0; // opening fresh bins while open ones stay roomy wastes capacity
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        // Perfect 2-chain bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Chain that leaves a still-usable residual (>= next + small margin)
        if post_residual > next_item_size && post_residual - next_item_size <= 20 {
            score -= 10.0;
        }
    }

    // Reward tight fits relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize dead space (very small post_residual that is unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist and item fits reasonably
    if bin_residual == bin_capacity {
        score += 35.0;
        // But allow new bin if lookahead chain is perfect and current bins are fragmented
        if next_item_size > 0 && post_residual == next_item_size && mean_residual < item_size as f64 {
            score -= 50.0;
        }
    }

    // Late-stream consolidation: fewer open bins preferred as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness * tightness;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small leftover dead space (< 10) is nearly useless; penalize creating it
    // unless it's an exact fit (already handled).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item would fit into this bin's post-residual,
    // reward the placement (keeps chains going).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.08 * next_item_size as f64;
        } else if next_item_size >= bin_residual {
            // Next item can't fit here even before placement; this bin's
            // remaining space is dead weight for the lookahead horizon.
            score += 2.0;
        } else {
            // Next item fits now but not after placement: mild penalty.
            score += 1.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of
    // this empty bin's potential; make it attractive only when it's genuinely
    // better than poor fits. Base cost for a fresh bin.
    if bin_residual == bin_capacity {
        // A new bin is fine when few bins are open or mean residual is high
        // (existing bins are full-ish).
        score += 15.0 - 0.5 * mean_residual - 1.0 * open_bins_count as f64;
        // If no open bin can fit the item at all, new bin must win.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Prefer consolidating into existing bins when many are open.
        score -= 0.3 * open_bins_count as f64;
    }

    // Global state: if mean residual across open bins is large, prefer the bin
    // whose residual is closest to the mean (balanced depletion) — approximate
    // by penalizing deviation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be conservative with new bins
    // (favor filling existing ones); late in the stream, allow slightly more
    // freedom since long-term fragmentation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 5.0 * progress;
    } else {
        score += 3.0 * (1.0 - progress);
    }

    // Mild preference for larger post_residual among otherwise-equal bins is
    // already in the base score; add small noise-free tiebreak on residual.
    score += 0.01 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with a non-linear polynomial shaping of tightness
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - t));

    // Smooth coupling of post_residual with stream progress
    let progress_coupling = pr * t * (1.0 - t) * 4.0;
    score -= 0.6 * progress_coupling;

    // Penalize small-but-not-zero residuals quadratically (dead space)
    let dead = if next_item_size > 0.0 as u32 && (next_item_size as f64) > pr {
        let gap = next_item_size as f64 - pr;
        gap * gap * 0.05
    } else {
        0.0
    };
    score += dead;

    // Reward near-full fills smoothly
    score -= 12.0 * (norm_pr * norm_pr * norm_pr);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 5.0 * (1.0 - t);
    }

    // Mild pressure to prefer open bins over opening new ones as bins accumulate
    score += (open_bins_count as f64).ln().max(0.0) * (0.3 + 0.7 * t);

    // Prefer bins whose residual is close to the item (tight fit), smoothly
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 4.0 * tight * tight;

    // Lookahead: if next item fits in post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 2.0 * (1.0 - pr / cap);
    }

    // Mean residual context: penalize deviating far from mean residual
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by 10 are
    // "clean" (likely reusable by typical item sizes); odd/waste classes are penalized.
    let r = post_residual;
    if r == 0 {
        score -= 25.0; // perfect closure, highly desirable
    } else {
        let class = r % 10;
        match class {
            0 => score -= 6.0,               // clean residual, easy to refill
            1 | 2 | 3 => score += 8.0,       // sliver residual, near-dead space
            4 | 5 | 6 => score += 2.0,       // awkward mid residual
            _ => score -= 1.0,               // 7..9 moderately reusable
        }
    }

    // Integer-division threshold: can the next item fit exactly or nearly?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Lookahead fits: reward tight co-packing, especially exact fits.
            if r == next_item_size {
                score -= 15.0;
            } else {
                let gap = r - next_item_size;
                if gap % 10 == 0 {
                    score -= 7.0; // leaves a clean class after lookahead
                } else {
                    score -= 3.0;
                }
            }
        } else {
            // Lookahead cannot use this residual: penalize proportional waste.
            let over = next_item_size - r;
            score += (over as f64) * 0.35;
            if r < 10 {
                score += 6.0; // residual too small for anything (min item size fallback)
            }
        }
    } else {
        // Last item: prefer closing bins tightly.
        score += (r as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // spread across open bins; only attractive when current fit is poor.
    if bin_residual == bin_capacity {
        let waste = mean_residual * (open_bins_count as f64);
        score += 20.0 + waste * 0.15;
        // Late in the stream, avoid spawning bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size <= 30 && progress > 0.5 {
            score += 15.0;
        }
    } else {
        // Mild preference for tighter existing bins when many are open.
        score += (open_bins_count as f64) * 0.05;
    }

    // Coupling: if this bin's residual is far below the mean, it's a scarce
    // small gap; reward using it before it becomes dead space.
    let diff = mean_residual - (bin_residual as f64);
    if diff > 0.0 {
        score -= diff * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1..10) can use
    // are pure waste. Penalize unusable gaps super-linearly.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Risky zone: only items <= post_residual fit; small gaps are fragile
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits strongly (tight packing).
    if post_residual == 0 {
        score -= 35.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // Extra pull if the next item could also use the resulting residual.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // New-bin candidate: only attractive when open bins are crowded or the fit
    // into existing bins would leave large dead space.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let poor_fit = (post_residual as f64 / bin_capacity as f64) * 40.0;
        score = 45.0 + pressure * 25.0 - poor_fit;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin is good if the next item is large (will need space anyway).
            if next_item_size > 50 {
                score -= 12.0;
            }
        } else if next_item_size == 0 {
            score += 20.0; // no lookahead: prefer finishing in existing bins
        }
    }

    // Open-bin pressure: mildly discourage spreading across many bins.
    score += open_bins_count as f64 * 0.4;

    // Prefer bins whose residual is below average (consolidate emptier space).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Lookahead harmony: residual after placement that can host the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (post_residual as f64 - next_item_size as f64) / 10.0;
    }

    // Late in the stream, tighten up: dead space matters more when few items remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: does the next item fit into the residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Reward tightness of the lookahead match
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 - slack * 1.5;
        // Extra reward if next item exactly fills the bin afterwards
        if post_residual == next_item_size {
            score -= 500.0;
        }
    } else if next_item_size > 0 {
        // Penalize residuals that are dead space relative to next item
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 2.0;
    }

    // Penalize small unusable residuals (< 10, assuming min item size 1..100 use small threshold)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer fuller bins relative to mean residual
    score += (mean_residual - post_residual as f64) * 0.5;

    // Mild preference for opening new bins early in stream when many bins open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: baseline penalty so it is chosen only when open bins look bad
        score += 40.0 + 100.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post-residuals non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_left = post_residual - next_item_size;
        score -= 60.0 * (1.0 - next_left as f64 / bin_capacity as f64);
        if next_left == 0 {
            score -= 120.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use: penalize.
        score += 0.3 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 - mean_residual).abs();
        score += 50.0 + 30.0 * (1.0 - progress) - 0.5 * poor_fit;
        if item_size == bin_capacity {
            score -= 500.0; // full item in fresh bin is perfect
        }
    }

    // Mild preference for fuller bins when many bins are open.
    score += 0.05 * mean_residual * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1)

    // Base: prefer tight fits (small post residual), with non-linear shaping.
    let mut score = pr as f64;

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // late in stream, penalize residual more aggressively (quartic term).
    let tightness = x * x * x * x;
    score += tightness * cap * (0.5 + 2.0 * progress);

    // Smooth reward for residuals that exactly fit a plausible next item
    // (lookahead coupling, smooth via gaussian-like bump).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let bump = (-gap * gap / (2.0 * 25.0 * 25.0)).exp();
        score -= 30.0 * bump * (1.0 - progress);
    }

    // Penalize bins that waste space relative to the fleet mean residual.
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (smoothly scaled by how full the bin already is).
    if fitting_bins_count == 1 {
        let fullness = 1.0 - x;
        score -= 80.0 * fullness * fullness;
    }

    // Mild penalty for opening a new bin when many bins are already open,
    // relaxing as the stream progresses (consolidation pressure).
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (open_bins_count as f64) * (1.5 - progress);

    // Small smooth preference for near-perfect fills (x close to 0).
    score -= (1.0 - x).exp() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band it lands in.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i32; // 0..10 harmonic decile

    // Reward tight fits strongly (low post_residual => low class index).
    let tightness_bonus = match class {
        0 => 60.0,
        1 => 35.0,
        2 => 20.0,
        3 => 8.0,
        _ => 0.0,
    };
    score -= tightness_bonus;

    // Penalize dead space that cannot fit the next item (wasted residual).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + (next_item_size - post_residual) as f64 * 0.4;
    }

    // Reward residual that exactly chains with the next item (perfect follow-up).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Reward residual that can host next item with a harmonic remainder (e.g. 100% k, 50% k).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 || slack % 10 == 0 {
            score -= 12.0;
        }
    }

    // Modulo arithmetic on post_residual: values divisible by common item sizes are reusable.
    let pr = post_residual;
    if pr > 0 && (pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is very poor.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64) < bin_residual as f64 * 0.45
            && fitting_bins_count > 0
            && (post_residual as f64) > 0.5 * bin_capacity as f64;
        if poor_fit {
            score -= 18.0; // allow opening when fit would waste half a bin
        } else {
            score += 70.0; // discourage new bins generally
        }
    }

    // Mean-residual coupling: prefer bins far below mean residual (pack them tighter first).
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Late in the stream, be extra conservative with new bins and prefer tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - frac);
    if bin_residual == bin_capacity && progress > 0.8 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it's smaller than the smallest plausible item (1),
    // but practically gaps below ~20 are hard to fill for unknown distributions.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 3.0; // harsh nonlinear penalty for tiny gaps
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open bins pressure: prefer using existing bins when many are open,
    // penalize opening new bins when few are open (encourage consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.5;

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if this bin is a last chance
        // and the fit would leave a large dead gap.
        if fitting_bins_count == 1 && post_residual > 30 {
            score -= 10.0; // better to open fresh bin than waste a nearly-full bin
        } else {
            score += 25.0 + pressure * 0.3; // discourage new bins otherwise
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(20) {
        score += 5.0; // next item won't fit here; gap likely dead
    }

    // Mean residual coupling: bins far below mean residual are underfilled;
    // prefer filling bins with residuals close to mean to balance usage.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect two-item fill
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 20.0 - leftover as f64 * 0.3; // next fits, penalize leftover
        } else {
            // next item cannot follow into this bin
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Compare post_residual to mean residual: leaving less than average is good.
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strong incentive to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer tight fits generally.
    score += (item_size as f64 / bin_residual.max(1) as f64) * -10.0;

    // New-bin candidate: penalize mildly so we only open new bins when fits are bad.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Late in stream: consolidate more strongly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the average incoming item.
    let avg_item = (bin_capacity as f64) * 0.4;
    if (post_residual as f64) < avg_item * 0.5 {
        score += 8.0;
    }

    // Lookahead: if next item fits perfectly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let fit_frac = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fit_frac;
        } else {
            score += 6.0;
        }
    } else {
        // Last item: strongly prefer minimal waste.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // Time horizon: early in stream, be conservative (prefer filling open bins);
    // late in stream, minimize waste aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // nearly-full bin; reward placing items there to close it out.
    let residual = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = residual / mean_residual;
        if rel < 0.8 {
            score -= 6.0 * (0.8 - rel);
        } else if rel > 1.5 {
            score += 4.0 * (rel - 1.5);
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and lookahead doesn't help.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > bin_capacity as f64 * 0.5 && next_item_size > post_residual;
        let mut new_bin_score = 45.0 + open_bins_count as f64 * 2.0;
        if bad_fit {
            new_bin_score -= 30.0;
        }
        score = score.max(new_bin_score);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 40.0 * pr_norm * pr_norm * cap
        + 25.0 * pr_norm.powi(3) * cap;

    // Stream progress coupling: as stream advances, tolerate less waste
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 30.0 * prog_term * pr_norm * cap;

    // Dead-space penalty: residuals too small for typical items are wasted
    let dead = if pr < 10.0 { (10.0 - pr) * 3.0 } else { 0.0 };
    score += dead;

    // Lookahead: reward residuals that can still fit the next item smoothly
    if next_item_size > 0 {
        let fits = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score += 15.0 * gap * gap * cap;
        score -= 10.0 * fits * (1.0 - gap);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Slight preference for bins tighter than average (good fits)
    let fit_quality = 1.0 - (pr / bin_residual.max(1) as f64);
    score -= 20.0 * fit_quality * (item_size as f64 / cap);

    // New-bin candidate calibration: empty bins get a mild opening cost,
    // reduced late in the stream or when many bins are already open
    if bin_residual == bin_capacity {
        let open_factor = (open_bins_count as f64).ln().max(0.0);
        score += 45.0 - 25.0 * progress - 3.0 * open_factor;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "small" residue classes are more valuable to fill tightly.
    let cap = bin_capacity as f64;

    // Reward exact / near-exact fits strongly (post_residual small).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common small item sizes (10..20) remain reusable; odd residues are dead space.
    let pr = post_residual;
    if pr > 0 {
        let reusable = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0);
        if reusable {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Integer-division thresholds: how many "medium" chunks (size 30) still fit
        let chunks = pr / 30;
        score -= chunks as f64 * 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this bin is a perfect chain link — reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.8;
        } else {
            // next item cannot use this residue: mild penalty proportional to waste
            score += 4.0;
        }
    } else {
        // Last item: any bin works, prefer tightest (post_residual already small)
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when nothing fits anywhere, but wasteful when
        // existing bins fit and residual classes are healthy.
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of a fresh bin: high, since it spends a full capacity unit.
        let mut new_bin_score = cap * 0.9;
        // Late in the stream, opening bins is cheap (few future items to place).
        new_bin_score -= progress * cap * 0.4;
        // If many open bins already, avoid fragmenting further.
        new_bin_score += open_bins_count as f64 * 3.0;
        // If no bin fits, new bin must look attractive.
        new_bin_score -= pressure * cap * 2.0;
        // Harmonic check: if item is large (> half capacity), fresh bin wastes little.
        if item_size > bin_capacity / 2 {
            new_bin_score -= 30.0;
        }
        score = score.max(new_bin_score) * 0.0 + if bin_residual == bin_capacity { new_bin_score } else { score };
    }

    // Mean residual coupling: when average residual is small, protect tight bins.
    score += (mean_residual - (post_residual as f64)) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible item are pure waste.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 1000.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // Prefer bins whose residual was tight relative to the item (good fit ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Last chance: if this is the only fitting bin, strongly favor using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when item barely fits elsewhere or open bins are wasteful.
    if bin_residual == bin_capacity {
        score += 80.0 + 5.0 * open_bins_count as f64;
        // If the next item could use this bin's residual after placement, opening is less costly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    } else {
        // Prefer reusing bins with larger residuals when open-bin pressure is high.
        score -= 0.05 * bin_residual as f64;
    }

    // Lookahead: penalize placements that leave a residual useless for the known next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Open-bin pressure: more open bins -> discourage marginal placements.
    score += 0.3 * open_bins_count as f64;

    // Slight preference to fill bins below the mean residual (balance).
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but penalize exact-zero
    // residuals less than near-zero dead space (a full bin is "done", not wasted).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score += 8.0; // tiny dead space is worst: unusable sliver
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.55;               // mismatch penalty
        if post_residual >= next_item_size {
            // Next item fits here: strong reward, scaled by tightness.
            let fit_tightness = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fit_tightness;
        } else {
            // Next item won't fit here: penalize leaving large unusable space.
            score += 0.35 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: bins far above mean residual are "loose";
    // prefer filling them before tighter bins.
    score -= 0.45 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Make the empty bin moderately
    // expensive so tight fits in existing bins win, but cheap enough to
    // beat bins that would waste lots of space.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.2 * item_size as f64;
        // Late in the stream, opening fresh bins is safer (fewer chances
        // to consolidate later).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * progress;
    }

    // Mild preference to keep the number of open bins from exploding.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing (min size 1..100) can reuse.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < item_size as f64 {
            score += 3.0 + 0.35 * dead;
        }
        // Waste grows superlinearly with unusable leftover relative to capacity.
        score += 0.012 * dead * dead / bin_capacity as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + 3.0 * (next_item_size as f64 / 100.0);
        } else {
            score += 1.5;
        }
    }

    // Global state: prefer bins with residual below mean residual (tighter bins),
    // scaled by how many open bins exist.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.08 * dev * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Time horizon: late in the stream, consolidate aggressively (fewer new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening bins, more so as stream progresses
        // and when open bins can fit.
        score += 4.0 + 10.0 * progress + 0.6 * (open_bins_count as f64);
        if post_residual >= next_item_size && next_item_size > 0 {
            score += 2.0;
        }
    } else {
        score -= 2.0 * progress;
    }

    // Mild penalty on huge open-bin counts to encourage closing gaps.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling: small post-residuals rewarded super-linearly.
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - norm_post);

    // Penalize mid-range dead space (quadratic hump around half-capacity).
    score += 6.0 * 4.0 * norm_post * (1.0 - norm_post) * (norm_post - 0.25).abs() * 2.0;

    // Stream progress coupling: tighten packing more aggressively later in the stream.
    score -= (8.0 + 14.0 * progress) * (1.0 - norm_post) * (1.0 - norm_post);

    // Perfect-fit bonus, scaled by progress.
    if post_residual == 0 {
        score -= 20.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving space for the next item, penalize blocking it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let tight = 1.0 - ((pr - nxt) / cap).abs();
            score -= 6.0 * tight * tight;
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when many bins are open and this placement wastes space.
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 2.0;

    // Mean-residual coupling: prefer bins whose residual differs from mean (consolidation).
    score -= 3.0 * (1.0 - ((pr - mean_residual) / cap).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals near multiples of 50
    // (half-capacity) are highly reusable; tiny residuals are dead space.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Reward residuals that form "harmonic" classes: 0, C/4, C/2, 3C/4.
    let dist_to_class = [
        (post_residual as i64 - 0).abs(),
        (post_residual as i64 - quarter as i64).abs(),
        (post_residual as i64 - half as i64).abs(),
        (post_residual as i64 - (3 * quarter) as i64).abs(),
    ];
    let min_class_dist = *dist_to_class.iter().min().unwrap();
    score -= (quarter as f64 - min_class_dist as f64).max(0.0) * 0.8;

    // Penalize dead space below the smallest plausible item band.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < quarter {
        score += (quarter - post_residual) as f64 * 0.35;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward; if next item cannot ever fit, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            score -= (gap as f64).min(30.0) * 0.5;
        } else {
            let overflow = next_item_size - post_residual;
            score += (overflow as f64).min(60.0) * 0.25;
        }
        // Harmonic pairing: post_residual % next_item_size == 0 means future
        // perfect fill potential.
        if next_item_size != 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: neutral-ish, but slightly worse than a
    // decent fit so we only open new bins when fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.1;
    }

    // Stream progression: late in the stream, tighten up — avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // Congestion: many open bins with high mean residual -> prefer filling
    // existing bins (penalize the new-bin alternative implicitly).
    if open_bins_count > 4 && mean_residual > half as f64 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are worthless; penalize them super-linearly.
    let dead_threshold = 20u32;
    if post_residual < dead_threshold {
        let waste = (dead_threshold - post_residual) as f64;
        score += 25.0 + waste * waste * 0.35;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is excellent
    }

    // Reward tight fits generally (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 10.0;

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; penalize candidates only mildly by count.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // extra reward for near-exact follow-up fit
        let gap = (post_residual - next_item_size) as f64;
        score -= (10.0 - gap.min(10.0)) * 0.8;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here; small residual becomes dead space
        score += 8.0;
    }

    // Mean-residual coupling: if this bin's residual is far below average, it's
    // already well-utilized; slightly favor it.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or all open bins would leave large dead space.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            // open new bin only if best existing option is bad
            score += 20.0 + mean_residual * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: bin becomes exactly filled by next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits tightly with small slack left after two placements.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 150.0 - (slack as f64) * 10.0;
        }
    }
    // Penalize leaving dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 5.0;
    }

    // Favor bins whose residual is below mean (tight bins), penalize loose bins.
    score += (mean_residual - bin_residual as f64).abs() * 0.3;
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits or item is huge.
    if bin_residual == bin_capacity {
        let penalty = if fitting_bins_count == 0 { -50.0 } else { 120.0 + open_bins_count as f64 * 5.0 };
        score += penalty;
        // Opening a new bin is fine if the item is large relative to capacity.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 40.0;
        }
    }

    // Late in the stream, tighten packing (less willing to open new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin achieved by placing the item
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: quadratic bonus for high fill ratio
    score -= 12.0 * fill * fill;

    // Penalize large dead space nonlinearly: residuals that are too small
    // to ever fit another item (min size 1..100 unknown, assume small items exist)
    let dead = post_residual as f64;
    if dead > 0.0 {
        // Dead space that is small relative to capacity is very wasteful
        let dead_ratio = dead / bin_capacity as f64;
        if dead_ratio < 0.10 {
            score += 8.0 * (0.10 - dead_ratio) / 0.10;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement (perfect chain)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses leftover space
            let next_use = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * next_use;
        } else {
            // next item won't fit here: slight penalty proportional to wasted potential
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among multiple candidates, prefer tighter ones (already via post_residual),
        // but add mild penalty for spreading across many open bins
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Global state: if mean residual across open bins is high, we have slack,
    // prefer filling existing bins; if low, opening new bins is less costly
    let mean_r = mean_residual / bin_capacity as f64;
    score -= 5.0 * mean_r * (bin_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize cramming); late in the stream, consolidate aggressively
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    let open_pressure = (open_bins_count as f64).ln().max(0.5);
    score += new_bin * (10.0 * (1.0 - progress) + 4.0) * open_pressure / (open_bins_count as f64).max(1.0);

    // Late-stream consolidation bonus for non-empty bins
    if bin_residual < bin_capacity && progress > 0.5 {
        score -= 6.0 * progress;
    }

    // Exact-fit celebration
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: waste after placement, mildly convex in waste
    let mut score = post + 0.012 * post * post / cap;

    // Reward tight fits (small post_residual), stronger as stream progresses
    let tightness = 1.0 - post / cap;
    score -= (0.5 + 1.5 * progress) * tightness * tightness * cap * 0.05;

    // Penalize bins whose residual is far from mean (outliers create dead space)
    score += 0.08 * (post - mean_residual).abs() * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer fuller bins
        score -= (bin_residual - post_residual) as f64 * 0.02;
    }

    // Lookahead: if next item fits in post_residual, reward leaving usable space
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 3.0 + 4.0 * (1.0 - (post - nxt) / cap);
        } else {
            // post_residual too small for next item: penalize proportionally
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Slight preference to keep bin count low early on
    score -= 0.5 / (1.0 + open_bins_count as f64);

    // New-bin candidate: penalize opening a new bin unless current residuals are poor
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        score += 6.0 - 10.0 * avg_waste * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
