pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Post-residual in the "awkward mid zone" (10..20) is mildly penalized:
    // few items fit there later.
    if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement; if post-residual is just barely too small for
    // the next item, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // discouraging bin proliferation; but favor filling existing bins when few
    // are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins whose residual is below the current mean residual
    // (consolidating into tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild progression term: late in the stream, tighten packing further.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += post_residual as f64 * progress * 0.5;
    }

    // New-bin candidate: make empty bins moderately attractive only when the
    // fit into open bins would be terrible (post_residual tiny or huge waste).
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-step match: this bin absorbs two items completely.
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves a third-level residual: mild reward scaled by tightness.
            let third = post_residual - next_item_size;
            score -= 25.0 * (1.0 - third as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize proportionally to how wasted the gap is.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.4 * gap;
        }
    } else {
        // Last item: only current tightness matters.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: bins tighter than average are better to fill.
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score += 6.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the one that wastes least (already via post_residual),
        // small penalty to keep ordering by tightness.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a new bin unless it enables a perfect pair.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // New bin can host item + next item if they nearly fill it.
            let pair_waste = (bin_capacity - item_size - next_item_size) as f64;
            score = 15.0 + pair_waste;
        } else {
            score = 45.0;
        }
    }

    // Slight stream-phase modulation: early on, be a bit more liberal with good fits.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * (1.0 - phase);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits (low post residual relative to residual)
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space more strongly as stream progresses
    score += 0.9 * (post_residual as f64 / bin_capacity as f64).powf(1.6) * (0.5 + progress);

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty for wasting space
            score += 2.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - progress * 0.4);
    }

    // Many fitting bins: penalize picking among many (prefer best fit via post_residual anyway)
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0).min(8.0);
    }

    // Global residual pressure: if mean residual is high, prefer filling existing bins
    if bin_residual < bin_capacity {
        score -= 3.0 * (mean_residual / bin_capacity as f64) * (1.0 - progress * 0.5);
    }

    // New-bin candidate: only attractive when no good fit exists (item small relative to capacity)
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        let pressure = (open_bins_count as f64).ln().max(0.5);
        score += 12.0 + 0.25 * waste * (0.6 + 0.8 * progress) - 6.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 60.0; // forced: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mean_norm = mean_residual / cap;

    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (0.5 + progress);
    score += 20.0 * poly;

    // Penalize leaving residuals that are too small to be useful, scaled by progress
    let dead = (1.0 - pr_norm).max(0.0);
    score += 15.0 * dead * dead * progress;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - pr_norm) * (1.0 + 2.0 * progress) * 5.0;

    // Interaction with mean residual: prefer bins whose residual deviates from mean
    let dev = (mean_norm - pr_norm).abs();
    score += 8.0 * dev * (0.5 + progress);

    // Lookahead: penalize if next item could have used this residual better
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let waste = (nxt - pr_norm).max(0.0);
        score += 12.0 * waste * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many bins
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by 10 are
    // "harmonic" with the item-size grid and more reusable.
    let class = post_residual % 10;
    if class == 0 {
        score -= 12.0;
    } else if class <= 2 || class >= 8 {
        score += 6.0; // near-full dead space
    } else {
        score += 2.0;
    }

    // Perfect fit is king.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            let ns = next_item_size % 10;
            if slack % 10 == 0 {
                score -= 18.0; // chain of harmonic fits
            } else if slack <= 2 {
                score -= 10.0;
            } else {
                score -= 3.0;
            }
            if ns == 0 {
                score -= 4.0;
            }
        } else {
            // next item won't fit here: penalize mildly, more if residual small
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + gap.min(30.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual <= 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate: penalize opening a new bin when plenty of open bins
    // can still accommodate items; encourage it only when bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frag = (mean_residual - post_residual as f64).abs();
        score += 30.0 - frag * 0.4 - open_bins_count as f64 * 0.2 - progress * 10.0;
        if item_size >= 50 {
            score -= 5.0; // large items pair well with fresh bins
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 8.0;

    // Mild preference for spreading load when mean residual is high.
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=9)
    // are pure waste; penalize them super-linearly.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual > 80 {
        // Large leftover is fine (usable), mild reward.
        score -= 4.0;
    }

    // Reward tight fits (item consumes most of the bin's current space).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Open-bin pressure: with many open bins, prefer reusing existing ones
    // to avoid bin proliferation.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    } else if next_item_size > post_residual && post_residual < 10 {
        // Next item can't use the tiny dead space we'd create; penalize more.
        score += 5.0;
    }

    // Mean residual coupling: if this bin is far below mean residual (i.e. more
    // full than average), it's a good consolidation target.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: make it moderately attractive only when few bins fit
    // the item and existing residuals are small.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 10.0 };
        score += pressure + open_bins_count as f64 * 2.0;
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 120.0; // strong reward for exact lookahead fit
        } else {
            // Smooth penalty growing with mismatch, scaled by lookahead size
            score += (diff as f64).powf(1.3) * 0.25;
        }
        // If bin can't host the next item at all, mild penalty
        if post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable dead space (< smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: prefer it only when it enables a good 2-step chain
    if bin_residual == bin_capacity {
        let chain_bonus = if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            10.0
        } else {
            -20.0
        };
        score += 30.0 - chain_bonus;
        // Less willing to open new bins late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Prefer denser bins slightly (less residual before placement)
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Tiny dead space is nearly unusable later (items >= 1, but fragmentation hurts).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Lookahead (k=2): reward leaving room for the next item, penalize blocking it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if next_item_size > post_residual {
            score += 2.0;
        }
    }

    // Brand-new empty bin candidate.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap; // how scattered open capacity is
        let mut new_bin_score = cap * 0.95 + fragmentation * 10.0 - (item_size as f64 / 10.0);
        // If no open bin can fit the item at all, opening a bin is mandatory.
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0;
        }
        // Late in the stream, avoid spawning extra bins.
        let t = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += t * 5.0;
        score = new_bin_score;
    }

    // Mild time-horizon scaling: early on, be slightly more exploratory (lower scores).
    let t = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap; // normalized post residual in [0,1]
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: prefer tight fits (low post_residual) strongly; late stream: relax slightly
    let coupling = norm_pr * (1.0 - progress) * (1.0 - norm_pr) * 20.0
                 - norm_pr * p2 * 10.0
                 + norm_pr * p3 * 5.0;
    score += coupling;

    // Penalize wasted space relative to mean residual (smooth quadratic interaction)
    let mean_dev = norm_pr - mean_residual / cap;
    score += 8.0 * mean_dev * mean_dev * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - progress) - 15.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 12.0 * snug * (1.0 - progress) + 6.0 * snug * progress;
        } else {
            // penalize leaving a residual that nothing typical can use
            score += 4.0 * norm_pr * norm_pr * progress;
        }
    }

    // New-bin candidate: keep neutral baseline, discourage early opening, allow late opening
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        score += 25.0 * (1.0 - progress) * (1.0 - open_pressure) - 10.0 * progress;
    }

    // Mild reward for filling large fraction of the bin
    score -= 5.0 * (item_size as f64 / cap) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes mod 10
    let class = (post_residual % 10) as f64;
    let decade = (post_residual / 10) as f64;

    // Penalize awkward dead space: residuals not in "useful" classes (0, small multiples)
    // Useful classes: 0, 10, 20, 30, 40, 50 (can host mid-size items later)
    let useful = post_residual % 10 == 0 && post_residual <= 50;
    if useful {
        score -= 6.0 + decade * 0.5;
    } else {
        score += 4.0 + class * 0.3;
    }

    // Perfect fit: extremely rewarding
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic coupling with next item: if next item exactly fits post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: residual class compatible if next leaves useful residue
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 12.0;
            } else {
                score += (next_post % 10) as f64 * 0.4;
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 5.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer tightest: post_residual already encodes that,
        // but add slight normalization by count
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: only attractive when no open bin is a good host
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = bin_capacity as f64 * 0.6;
        // attractive if mean residual across open bins is fragmented / few fitting bins
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if mean_residual > 40.0 {
            score += 10.0; // open bins are full-ish, new bin fine
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild preference for filling fuller bins earlier in the stream
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are fine only if zero; gaps below the item-size
    // mass threshold are unusable dead space -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that can't fit the lookahead item are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits (waste relative to perfect packing).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation.
    score += (open_bins_count as f64) * (2.0 + 30.0 / (post_residual as f64 + 5.0));

    // New-bin candidate: only attractive when it enables a near-perfect
    // pack or no existing bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 80 {
            score -= 45.0;
        }
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Prefer bins already below mean residual (keeps residuals balanced,
    // avoids many half-empty bins).
    score -= 3.0 * (mean_residual - post_residual as f64).max(0.0);

    // Late in stream: waste matters more, keep bins tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: no dead space at all.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Slack that exactly (or nearly) fits the next item is valuable.
            let slack_gap = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack_gap / bin_capacity as f64);
        } else {
            // Dead space: post_residual too small for next item.
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 40.0 * dead * dead;
            // If next item is huge, small leftovers are extra wasteful.
            if next_item_size > bin_capacity / 2 {
                score += 20.0 * dead;
            }
        }
    }

    // Compare bin's residual against the mean residual of open bins:
    // prefer filling below-average (tighter) bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 2.0 * open_bins_count as f64;

    // New empty bin candidate: make it attractive only when the fit is bad
    // or the item is large and no good existing fit exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if item_size >= 50 {
            // Large items pack cleanly into fresh bins.
            score -= 70.0 * fill_ratio;
        } else {
            // Small items should not open new bins unless nothing fits well.
            score += 30.0;
            if post_residual > 0 && post_residual < 10 {
                score -= 25.0; // near-perfect small fit is fine even in a new bin
            }
        }
        // Later in the stream, opening bins is cheaper (fewer future regrets).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score += 0.1 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 10.0;
    }

    // Penalize leaving large unusable dead space relative to smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // sliver space is nearly dead
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    // (poor fit in open bins) or no real alternative exists.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let mut penalty = 55.0 - 40.0 * fill_ratio;
        if fitting_bins_count == 0 {
            penalty = -5.0; // nothing fits anyway, new bin is fine
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 20.0 * progress;
        score += penalty;
    }

    // Lookahead: if the next item would fit in this bin's post-residual,
    // reward the pairing; otherwise penalize wasted pairing opportunity.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else if next_item_size <= bin_residual {
            // next item fits the bin better than the current one does
            score += 4.0;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer packing into existing slack.
    let slack_pressure = mean_residual / bin_capacity as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * slack_pressure;
    }
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 3.0; // consolidate when many bins open
    }

    // Time horizon: early stream -> keep bins flexible (avoid tiny residuals);
    // late stream -> squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score += (1.0 - progress) * (post_residual as f64) * 0.05;
        score -= progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let irn = item_size as f64 / cap;
    let nrn = next_item_size as f64 / cap;
    let mean_n = mean_residual / cap;

    // Base: reward tight fits (low post residual), with non-linear sharpening
    let mut score = prn * (1.0 + 1.5 * prn * prn);

    // Smooth coupling: post residual penalized more when it cannot host the next item
    let fits_next = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
    score += (1.0 - fits_next) * (0.3 + 0.7 * prn) * (0.5 + 0.5 * progress);

    // Bonus when post residual matches next item size well (smooth proximity kernel)
    if next_item_size > 0 {
        let gap = (pr - nrn * cap).abs() / cap;
        score -= 0.6 * (-8.0 * gap * gap) * (0.4 + 0.6 * progress);
    }

    // Dead-space penalty: residual too small to ever be useful (below min item size 1..100 heuristic ~ 10)
    let dead = (10.0 / cap - prn).max(0.0);
    score += 2.0 * dead * dead * cap / 10.0;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 1.2 + 0.8 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - prn);

    // Prefer bins below mean residual slightly (fill emptier space first) — smooth interaction
    score += 0.2 * (mean_n - prn) * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize opening fresh bins unless current fit is bad
    if bin_residual == bin_capacity {
        score += 1.5 + 1.5 * (1.0 - progress) + 0.5 * irn;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and residuals that are
    // multiples of common small sizes are highly reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Modulo classes: residuals divisible by 10/20/25/50 match typical item sizes.
        let divisibility_bonus = if post_residual % 10 == 0 { 60.0 }
                                 else if post_residual % 5 == 0 { 30.0 }
                                 else { 0.0 };
        score -= divisibility_bonus;

        // Dead-space penalty: residuals too small for the minimum item (1..=100 range,
        // assume small items may exist but penalize very tight leftovers).
        if post_residual < 10 {
            score += 120.0;
        } else if post_residual < 20 {
            score += 40.0;
        }

        // Integer-division thresholds on post_residual: quarter/half classes.
        let quarter = bin_capacity / 4;
        let half = bin_capacity / 2;
        if post_residual > half {
            score -= 25.0; // roomy bin, still useful
        } else if post_residual > quarter {
            score -= 10.0;
        } else {
            score += 15.0; // cramped leftover
        }

        // Lookahead coupling: does next item fit the post_residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Harmonic match: exact or near-exact next fit is excellent.
                let slack = (post_residual - next_item_size) as f64;
                if slack == 0.0 {
                    score -= 400.0;
                } else if (post_residual % next_item_size.max(1)) == 0 {
                    score -= 150.0;
                } else {
                    score -= 60.0 * (1.0 - slack / cap).min(1.0);
                }
            } else {
                score += 30.0; // next item won't fit here anyway
            }
        } else {
            // Last item: minimize waste directly.
            score += 0.0;
        }

        // Last-chance bin: strongly favor using the only fitting bin.
        if fitting_bins_count == 1 {
            score -= 80.0;
        }

        // New-bin candidate (empty bin): penalize opening a new bin unless
        // current residuals are nearly exhausted or fit is poor.
        if bin_residual == bin_capacity {
            let progress = step_index as f64 / (total_items.max(1) as f64);
            let pressure = mean_residual / cap; // low mean residual => pressure
            let penalty = 90.0 + 120.0 * pressure + 60.0 * progress;
            // Allow new bin if the alternative leaves big dead space.
            let dead = if post_residual < 15 { 100.0 } else { 0.0 };
            score += penalty - dead;
        }

        // Many open bins: prefer consolidating into existing space.
        if open_bins_count > 8 {
            score -= 5.0 * (open_bins_count.min(40) as f64).log2();
        }

        // Fractional capacity tie-break: favor bins whose residual is a clean
        // fraction of capacity (harmonic class).
        let frac = pr / cap;
        let frac_class = (frac * 4.0).round() / 4.0;
        if (frac - frac_class).abs() < 1e-9 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward filling bins that are the last chance for this item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: fewer open bins => prefer reusing existing bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins tighter than average (good fill), penalize wasteful large bins.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Lookahead: if next item fits the post residual exactly or well, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 20.0;
        } else {
            score -= 10.0 / (1.0 + gap * 0.1);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 12.0; // next item can't use leftover: dead space likely
    }

    // Early in stream: allow new bins more freely; late: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 20.0;
    }

    // Penalize dead space smaller than the minimum plausible item (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Prefer bins whose residual deviates below mean (denser bins) when fit is decent
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize moderately so it is chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0;
        // Opening a new bin is attractive if no open bin gives a tight fit
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 20.0;
        }
    }

    // Mild late-stream conservatism: reuse existing bins more as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later in stream => prefer tighter fills.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of capacity used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits strongly (best-fit core), amplified late in stream.
    score -= fill * (30.0 + 40.0 * progress);

    // Penalize leaving small unusable slivers (dead space) nonlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement heavily (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; mildly penalize leaving awkward gaps.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Many open bins => encourage closing bins (using residual), i.e. prefer
    // bins with small residual relative to mean.
    if open_bins_count > 1 {
        score -= (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64 * 10.0;
        // Penalize bins with residual well above mean (they should absorb more later).
        if (bin_residual as f64) > mean_residual + 15.0 {
            score += 8.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when the fit is
    // poor elsewhere or few bins exist. Penalize the fresh bin moderately.
    if bin_residual == bin_capacity {
        score += 45.0 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open a new bin
        }
        if item_size as f64 / bin_capacity as f64 > 0.9 {
            score -= 50.0; // huge item: fresh bin is natural
        }
    }

    // Mild bonus for near-full placements overall.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap; // filled fraction after placement

    // Base: reward tight fits via non-linear penalty on residual
    let mut score = pr * pr / cap;

    // Smooth coupling: residual weighted by stream progress (later => pack tighter)
    score += pr * (0.5 + progress) * (1.0 - fill * fill);

    // Reward high fill ratio non-linearly
    score -= fill * fill * fill * 20.0;

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        score -= 15.0 / (1.0 + diff * diff / (cap * cap));
        score += 0.05 * diff;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Crowding: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * pr * 0.1;

    // Mean residual context: bins far from mean residual get slight penalty
    let dev = (pr as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0), "half-class" (50),
    // small-dead-space classes, and large-dead-space classes.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let frac = pr as f64 / cap;

    if pr == 0 {
        score -= 500.0; // perfect fit, always take it
    } else if pr == bin_capacity {
        // This is the brand-new empty bin candidate: score its viability.
        // Prefer a new bin only late in the stream or when current bin would
        // leave a large unusable residue and many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0;
        score -= 60.0 * progress;
        score -= 5.0 * open_bins_count as f64;
        // If next item can exactly fill a fresh bin, boost new bin slightly
        if next_item_size > 0 && next_item_size == bin_capacity {
            score -= 200.0;
        }
        // Penalize new bin if existing bins fit well (post_residual small)
        if bin_residual < bin_capacity {
            score += (bin_residual as f64).max(0.0);
        }
    } else {
        // Dead-space harmonic penalty: quadratic in wasted capacity
        score += 2.0 * frac * frac * cap;

        // Modulo classes of post_residual w.r.t. typical small item sizes
        if pr % 10 == 0 {
            score -= 15.0; // aligns with 10-multiple item classes
        }
        if pr % 25 == 0 {
            score -= 10.0;
        }
        // Half-class residue is highly reusable
        if pr == bin_capacity / 2 {
            score -= 40.0;
        }

        // Lookahead coupling: if next item fits exactly into post_residual,
        // strongly reward this bin.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 120.0;
            } else if next_item_size <= pr {
                score -= (pr - next_item_size) as f64 * 0.8;
                // harmonic bonus when next item leaves another nice residue
                let pr2 = pr - next_item_size;
                if pr2 % 10 == 0 { score -= 8.0; }
            } else {
                // next item won't fit here: penalize if this residue is tiny
                if pr < 10 {
                    score += 45.0; // dead space trap
                }
            }
        }

        // Last-chance bin: if this is the only fitting bin, avoid stranding
        if fitting_bins_count == 1 && pr >= 10 {
            score -= 25.0;
        }

        // Discourage packing into bins whose residual diverges from mean
        score += 0.3 * ((bin_residual as f64 - mean_residual).abs());
    }

    // Mild tie-break: prefer fuller bins overall
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: residuals that are too small for any
    // plausible future item (items >= 1, but small gaps < ~10 are dead weight)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 8.0;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 15.0 + 40.0 * pressure + 10.0 * progress;
        // But if no existing bin fits well, allow opening: handled by comparison.
    } else {
        score -= 5.0 * pressure;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Prefer bins whose residual is below mean (packing tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: perfect match with next item is gold ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Bin becomes exactly full after the next item: strongly favor.
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits here: mild reward proportional to closeness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 / (1.0 + gap);
        } else {
            // Next item cannot fit in the leftover: penalize dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    } else {
        // Last item: minimize leftover as tightly as possible.
        score += 0.3 * post_residual as f64;
    }

    // ---- Compare post_residual against mean residual of open bins ----
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            // Leaves less junk than average: reward.
            score -= 8.0 * (0.5 - rel);
        } else if rel > 1.5 {
            // Leaves much more junk than average: penalize.
            score += 6.0 * (rel - 1.5);
        }
    }

    // ---- Last-chance bin: if this is the only bin that fits, use it ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // ---- New empty bin candidate handling ----
    if bin_residual == bin_capacity {
        // Default penalty so a new bin is only opened when open bins fit poorly.
        score += 30.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        score -= 40.0 * (1.0 - progress);
        // If many bins are open already, discourage proliferation.
        score += 2.0 * open_bins_count as f64;
        // If the next item is large and this item is small, a fresh bin is attractive.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Slight preference for tighter existing bins (best-fit flavor).
        score += 0.05 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (non-linear diminishing bonus on small post-residual).
    score -= 14.0 / (1.0 + post_residual as f64);

    // Lookahead coupling: favor bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0 + 0.05 * next_item_size as f64;
        } else if post_residual > 0 {
            // dead space that cannot serve the next item
            score += 7.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only open bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Many fitting bins: mild penalty to prefer the fullest/tautest one via base term.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in stream, be slightly pickier about waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.03 * post_residual as f64;

    // Global state: if open bins are collectively full (low mean residual),
    // discourage scattering into many near-empty bins.
    score += 0.02 * mean_residual.max(0.0);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Baseline attractiveness of a fresh bin: good when existing fits are poor.
        score = 40.0
            + 0.35 * mean_residual
            - 3.0 * (open_bins_count as f64).sqrt();

        // Prefer a new bin when the item is large (hard to fit later).
        score -= 0.08 * item_size as f64;

        // If the next item is large, opening a fresh bin now is risky (it will
        // be fragmented by the current item); discourage.
        if next_item_size > 60 {
            score += 10.0;
        }

        // Late in the stream, prefer closing out existing bins.
        score += 10.0 * progress;

        // If exactly one open bin fits, strongly avoid opening a new bin.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0), prefer tight fits moderately; later, dead space
    // becomes more costly, so post_residual is amplified with higher powers.
    let poly = 1.0 + progress * pr_norm + progress * progress * pr_norm * pr_norm;
    score *= poly;

    // Reward tight fits: subtract a smooth bonus proportional to fill ratio,
    // scaled by progress so late-stream tight fits are extra attractive.
    let fill = item_size as f64 / cap;
    score -= fill * fill * (1.0 + 2.0 * progress) * 10.0;

    // Penalize very small dead space (< ~5) that can't serve typical items,
    // with smooth transition via quadratic term.
    let dead = pr_norm;
    score += dead * dead * (1.0 - dead) * 20.0 * (0.5 + progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - diff / cap).max(0.0) * 8.0;
    }

    // Slight preference for bins below mean residual (keeps larger residuals
    // available for larger future items), smoothly interpolated by progress.
    score += (mean_residual - pr) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer division into capacity-fraction bands (1/8 of capacity).
    let eighth = bin_capacity / 8;
    let band = post_residual / eighth;
    match band {
        0 => score -= 40.0,                       // near-perfect fit
        1 => score -= 20.0,                       // good fit
        2 => score += 5.0,                        // moderate leftover
        3 => score += 15.0,                       // dead-ish space
        _ => {}                                   // large residual, neutral
    }

    // Modulo harmonic: residuals that are multiples of small classes
    // (e.g. 10, 20, 25) are more reusable by typical item sizes.
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 25 == 0 { score -= 6.0; }
    if post_residual % 20 == 0 { score -= 4.0; }

    // Pairing with lookahead item: if next item fits exactly or nearly
    // into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap <= eighth { score -= 18.0; }
            else { score -= gap as f64 * 0.15; }
        } else {
            // next item cannot use this residual at all: penalize
            score += (next_item_size - post_residual) as f64 * 0.10;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when all
    // open fits are bad. Base penalty on empty bin, scaled by stream
    // progress and current congestion.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0 + 20.0 * progress + open_bins_count as f64 * 0.5;
        // If next item is huge, opening fresh may be wise.
        if next_item_size >= bin_capacity * 3 / 4 {
            score -= 25.0;
        }
    }

    // Slight tie-break toward tighter bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Marginal gap: risky, likely unusable later.
        score += 15.0;
    }

    // Reward tight fits (small post_residual) non-linearly.
    if post_residual > 0 {
        score -= 30.0 / (post_residual as f64).sqrt();
    } else {
        // Perfect fill is the best possible outcome.
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained tight packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item cannot use the leftover gap, mild penalty for hoarding space.
    if next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.6 + 0.8 * progress);

    // Mean residual coupling: if this bin's post residual deviates far below
    // the mean, it is being filled efficiently; reward it.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins
    // genuinely have bad fits (post_residual penalties above can override).
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (post_residual close to 0)
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 500.0;
    } else if pr <= 5.0 {
        score -= 300.0 - pr * 20.0;
    }

    // Penalize unusable dead space relative to smallest possible item (1..100 unknown,
    // use a conservative small-item threshold)
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 8.0; // dead space too small to be useful
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size well
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        if n <= pr {
            // next item fits here afterwards: reward tight coupling
            score -= (40.0 - gap.min(40.0)) * 3.0;
            if gap == 0.0 {
                score -= 250.0; // perfect chain: item then next item exactly fills
            }
        } else {
            // next item would NOT fit after this placement: mild penalty scaled by overflow
            score += (n - pr).min(30.0) * 1.5;
        }
    }

    // Relative-to-mean-residual term: prefer placing into bins with residual
    // close to (or below) the mean to keep the residual distribution tight
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin; reduced late in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 120.0 - 40.0 * progress;
        // penalize new bin more when many bins are open and fragmented
        score += open_bins_count as f64 * 5.0;
        // but reward new bin if current item leaves a large awkward residual in any real bin
        if pr > 50.0 {
            score -= 30.0;
        }
    }

    // Prefer filling bins that are already mostly full (low residual)
    score += (bin_residual as f64 / cap) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post residual is small.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize leaving dead space that cannot plausibly fit a future item.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            score -= 5.0 * (next_item_size as f64 / (post_residual as f64 + 1.0));
        } else {
            // next item won't fit here; penalize wasting residual
            score += 0.05 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins below mean residual (under-filled) to balance load when many bins open.
    if open_bins_count > 2 {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is only attractive when no tight fit exists:
        // penalize new bins mildly, more so early when bins are few.
        let horizon = step_index as f64 / (total_items as f64).max(1.0);
        let mut nb = 12.0 + 0.3 * (item_size as f64);
        if fitting_bins_count == 0 {
            nb = -50.0; // must open
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity && (100 - item_size) >= next_item_size {
            nb -= 8.0; // room for pairing
        }
        if horizon > 0.5 && open_bins_count > 6 {
            nb += 5.0; // late stream: prefer consolidating into open bins
        }
        score += nb;
    }

    // Slight preference for larger item into fuller bin (best-fit coupling).
    score -= 0.02 * (item_size as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post residual, with a non-linear (quadratic) sharpening.
    let mut score = post + 0.15 * (post * post) / cap;

    // Smooth progress coupling: later in the stream, dead space matters more.
    score += 2.0 * progress * post / cap * (1.0 + progress);

    // Tight-fit reward (smooth, based on fill ratio of the bin).
    let fill = 1.0 - post / cap;
    score -= 6.0 * fill * fill * fill;

    // Lookahead: reward if next item fits the post residual, penalize near-misses smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 3.0 * (1.0 - nxt / post.max(1.0)) * (1.0 + progress);
        } else {
            let gap = (nxt - post) / cap;
            score += 4.0 * gap * gap * 100.0 / cap;
        }
    }

    // Last chance: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // New-bin candidate handling: mildly discourage opening new bins unless residual is large.
    if bin_residual == bin_capacity {
        score += 5.0 - 4.0 * progress;
        // But if it's genuinely the only option, this penalty is moot.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    }

    // Slight penalty if this bin's residual is far from the mean (keeps bins balanced).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small dead space classes are good
    let pr = post_residual;
    let class = pr % 10;
    // Reward post-residuals that fall in "usable" harmonic classes (small gaps)
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if class <= 2 {
        score -= 12.0; // near-perfect fit class
    } else if class >= 8 {
        score += 8.0; // awkward class: big but not big enough
    }

    // Capacity fraction coupling: post_residual as fraction of capacity
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        // wasteful to leave a half-empty bin when item went in elsewhere
        score += 10.0 * (frac - 0.5);
    } else if frac < 0.1 && pr > 0 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead harmonic: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next fits: reward if next exactly consumes a harmonic class
            let nxt_class = next_item_size % 10;
            let fill = next_item_size as f64 / pr as f64;
            score -= 15.0 * fill;
            if (pr - next_item_size) % 10 == 0 {
                score -= 8.0;
            }
            if nxt_class == class {
                score -= 4.0; // harmonic resonance
            }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Progress-coupled tightening: later in stream, demand tighter fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Mean residual deviation: prefer bins near mean (balanced packing)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / cap; // = 1.0 for empty bin with item
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        } else if poor_fit > 0.6 {
            score -= 5.0; // fresh bin keeps flexibility
        } else {
            score += 20.0; // prefer existing bins for decent fits
        }
        score += 0.05 * open_bins_count as f64; // slight penalty for bin proliferation
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps are the enemy: if post_residual cannot even hold
    // the minimum plausible item, it is pure waste. Penalize quadratically.
    let dead_threshold: u32 = 9; // items are 1..=100 unknown dist; small gaps rarely reusable
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < dead_threshold {
        // Unusable sliver: heavy quadratic penalty.
        score += (dead_threshold - post_residual) as f64 * (dead_threshold - post_residual) as f64 * 1.5;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap too small for the known next item: moderate penalty.
        score += (next_item_size - post_residual) as f64 * 2.0;
    } else {
        // Usable gap: mild reward proportional to how well next item fits.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 - slack.min(20.0) * 0.1;
        }
    }

    // --- Tight fit reward: filling a large fraction of the residual is good ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // --- Open bins pressure: discourage spreading across too many bins ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    // --- Mean residual coupling: prefer bins whose residual deviates well ---
    // A bin with residual far above mean is a good host for a big item.
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.15;

    // --- Last chance bonus: if this is the only fitting bin, avoid opening a new one ---
    if fitting_bins_count == 1 && post_residual < dead_threshold {
        score -= 40.0;
    } else if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // --- New-bin candidate calibration ---
    // An empty bin has bin_residual == bin_capacity. Only prefer it when the
    // current bin would leave a dead sliver; otherwise make new bins unattractive.
    if bin_residual == bin_capacity {
        if post_residual > 0 && post_residual < dead_threshold {
            // Opening a new bin beats creating dead space in an existing bin.
            score -= 30.0;
        } else {
            // Otherwise strongly prefer reusing an existing bin.
            score += 35.0 + 0.1 * mean_residual;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // 2-step lookahead: reward exact/near-exact matches with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            // Perfect 2-item fill: strongly reward.
            score -= 60.0 + 40.0 * progress;
        } else if (post_residual as f64 - next).abs() <= 5.0 {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // Dead space relative to next item: penalize proportionally.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res - mean_residual) / bin_capacity as f64;
        score += 30.0 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalize creating tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: default mild preference when open bins are crowded.
    if bin_residual == bin_capacity {
        // Neutral-ish base; make it attractive only if few bins fit.
        score = 55.0 - 12.0 * (fitting_bins_count as f64).recip() - 20.0 * progress;
        if next_item_size > 0 && next_item_size as f64 >= bin_capacity as f64 * 0.9 {
            score -= 30.0; // reserve fresh bins for huge upcoming items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed residual is worth much less.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item.
    let dead = if post_residual < 10 { post_residual as f64 * 2.5 } else { 0.0 };
    score += dead;

    // Lookahead: bonus if the next item can fit into post_residual (chain packing).
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0;
        } else {
            // Wasted chain opportunity: penalize proportionally to gap.
            score += 0.4 * (next_item_size as f64 - post_residual as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global pressure: many open bins with slack -> prefer consolidating into laggards.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let slack_gap = mean_residual - bin_residual as f64;
    score += 0.15 * slack_gap * (0.5 + progress);

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // the current item is large and few bins are open, or late in the stream.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= 50 { 10.0 } else { 0.0 };
        let open_penalty = 3.0 * open_bins_count as f64;
        score += 45.0 + open_penalty - large_item_bonus - 20.0 * progress;
    }

    // Mild preference for bins whose residual is close to item size (exact-ish packing).
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * progress);

    // Quadratic coupling: waste grows super-linearly with post_residual, more so late in the stream.
    let x = pr / cap;
    score += 30.0 * x * x * (0.5 + progress);

    // Interaction of item size with residual: reward large items into large residual gaps.
    score -= 0.4 * it * x;

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.5 * gap;
        if pr >= nx {
            score -= 6.0 * (1.0 - gap / cap);
        }
    }

    // Last-chance bin: penalize slightly to avoid wasting a scarce fit unless it is tight.
    if fitting_bins_count == 1 {
        score += 4.0 * (1.0 - x);
    }

    // Smooth pressure from mean residual across open bins.
    score += 0.3 * (mean_residual - pr).abs();

    // Mild preference to fill existing bins as the stream progresses.
    score += 2.0 * progress * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Dead-space penalty grows super-linearly for tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic class reward: leftover in {0, 25, 33, 50} style classes pairs well with
    // common item sizes (integer division thresholds on post_residual).
    let class = post_residual / 10; // 0..10 classes
    let class_bonus: f64 = match class {
        0 => 20.0,
        2 => 6.0,           // ~20-29 leftover, fits a medium item
        3 => 10.0,          // ~30-39, common class
        5 => 12.0,          // ~50-59
        7 => 8.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            score -= 15.0 * (1.0 - (nxt / (pr + 1.0))); // tighter fit -> better
        } else {
            // next item cannot use leftover; penalize proportionally to wasted potential
            score += 5.0 + 0.3 * (next_item_size as f64 - pr);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; discount early in stream or when few bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * (0.85 - 0.25 * progress) + 3.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0; // next item won't fit anywhere typical anyway
        }
    }

    // Mild preference for bins below mean residual (keeps emptier bins for big items).
    score += 0.15 * (mean_residual - (bin_residual as f64)).max(0.0);

    // Modulo tiebreaker: prefer residuals in harmonious residue classes mod 10.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range,
    // but typical min ~10) are pure waste. Penalize hard when post_residual is
    // small but nonzero and unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range awkward gaps (10..25) are semi-dead space.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this placement is excellent.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: penalize creating new bins when many bins are already open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: accept it only if open-bin count is low or residual
        // landscape is fragmented (mean residual very low).
        score -= 15.0 * (1.0 - progress);
        score += (open_bins_count as f64) * 2.0;
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    } else {
        // Slight pressure to consolidate into fewer bins.
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins where the item exactly fills residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly (chain fit).
    if next_item_size > 0 && post_residual > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 0.5 {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how well it uses leftover
            score -= 0.5 * (nr / post_residual as f64);
        } else {
            // next item won't fit: penalize leaving dead space
            score += 0.3 * (nr - post_residual as f64);
        }
    }

    // Penalize large leftover relative to mean residual (dead space creation)
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or nothing fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 150.0;
        if fitting_bins_count == 0 {
            open_penalty = -50.0; // must open a bin
        }
        // later in the stream, prefer consolidating into open bins
        open_penalty += 100.0 * progress;
        score += open_penalty;
    }

    // Prefer tighter bins generally (best-fit flavor)
    score += 0.2 * (bin_capacity - bin_residual) as f64 * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: late in the stream, prefer tightening existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead reward: if the next item fits into the post-residual, this bin
    // chains nicely — reward it (subtract), scaled by how snugly it fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 6.0 + 0.25 * chain_waste * (1.0 - progress);
    } else if next_item_size > post_residual {
        // Next item won't chain here: mild penalty, stronger early when
        // there is still time to keep bins flexible.
        score += 3.0 + 4.0 * (1.0 - progress);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.5 * item_size as f64;
    }

    // Prefer bins whose residual is already below the mean (consolidate
    // half-empty bins rather than fragmenting full ones).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // Penalize creating tiny unusable slivers (dead space < 10 can never
    // hold any item in the classic regime; be lenient for small items).
    if post_residual < 10 {
        score -= 8.0; // near-perfect fill: excellent
    } else if post_residual < item_size.min(20) {
        score += 2.0; // awkward sliver
    }

    // New-bin candidate: residual == capacity. Only attractive when the item
    // is large (existing bins would be shredded) or very late in the stream
    // where fresh capacity pays off; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size >= 60 { 15.0 } else { 0.0 };
        score += 18.0 - large_item_bonus - 6.0 * progress
            - 0.05 * (open_bins_count as f64).min(10.0);
    }

    // Slight preference for fewer open bins overall (encourage consolidation).
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: quadratic penalty on wasted space, softened early in the stream
    let mut score = pr_norm * pr_norm * (0.5 + 1.5 * progress) * cap;

    // Smooth cubic coupling of waste with stream progress
    score += 10.0 * pr_norm.powi(3) * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 5.0 * (1.0 - pr_norm).powi(2) * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize bins far from mean residual (smooth dispersion term)
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).powi(2) * 10.0;

    // Lookahead: reward leaving space compatible with next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = (pr_norm - nxt).abs();
        score += 4.0 * gap * gap;      // post-residual close to next item size is good
        score -= 2.0 * (-gap * gap * 10.0).exp(); // smooth exact-match reward
    } else {
        // Last item: purely minimize waste
        score -= 6.0 * (1.0 - pr_norm);
    }

    // Mild penalty on many open bins to discourage fragmentation
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: neutral baseline with slight waste penalty
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * fit_ratio * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "reusable" is the leftover space?
    // Class 0: post_residual is a multiple of 25 (nice quarter-capacity slots)
    // Class 1: post_residual within 10 of a multiple of 25
    // Class 2: awkward leftover
    let harmonic_class = (post_residual % 25) as f64;
    let class_penalty = match post_residual % 25 {
        0 => -8.0,
        1..=10 => -3.0,
        _ => 0.0,
    };
    score += class_penalty;
    // Fine-grained non-linear penalty on awkward remainders (peaked away from 0/25)
    score += 0.15 * harmonic_class * (1.0 - harmonic_class / 25.0);

    // Integer-division threshold: post_residual >= 50 means the bin can still
    // hold a "half-capacity" item -> reward; below small thresholds it's dead space.
    if post_residual >= 50 {
        score -= 6.0;
    } else if post_residual < 10 {
        score += 12.0; // nearly-full bin is fine, but tiny slivers are useless
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let pair_res = post_residual - next_item_size;
            score -= 5.0;
            score += 0.1 * (pair_res % 25) as f64;
        } else {
            // next item cannot use this bin's leftover; mild penalty scaled by gap
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins mildly; penalty shrinks if mean residual is small
        score += 18.0 - 10.0 * (1.0 - mean_residual / bin_capacity as f64) - 5.0 * progress;
    }

    // Slight preference for tighter bins among equals (relative fill)
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64).recip().max(0.0);

    // Open-bin economy: discourage spreading across many bins
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to fit anything useful
    // (assume min item size ~10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    } else {
        // Mild quadratic penalty for larger leftovers
        score += 0.05 * (post_residual as f64).powi(2) / 100.0;
    }

    // Reward tight fits (perfect or near-perfect packing)
    if post_residual == 0 {
        score -= 40.0;
    }

    // If next item could use the leftover space, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.1 * post_residual as f64;
    }
    // If next item cannot fit the leftover, penalize slightly.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 4.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost + pressure from open bins count.
        score += 30.0 + 6.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper; late in stream, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If a new bin would waste less than existing mean residual, slightly cheaper.
        score -= 0.05 * mean_residual;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect-fit bonus: strongly favor bins whose residual exactly matches the item.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Partial lookahead reward, decaying with mismatch size.
            let gap = (post_residual - next_item_size) as f64;
            score -= 300.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use leftover space: penalize dead space creation.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    }

    // Relative-to-mean coupling: bins tighter than average get priority.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 400.0 + 200.0 * (1.0 - progress);
        score += new_bin_penalty;
        // If next item is huge and nothing else helps, opening a fresh bin is okay.
        if next_item_size > bin_capacity / 2 && post_residual == bin_capacity {
            score -= 100.0;
        }
    }

    // Slight preference for opening fewer bins early (consolidation).
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // Reward bins that can still absorb the lookahead item.
            score -= 2.5;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild crowding penalty so we don't dump into a scarce-fit bin needlessly.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // New-bin candidate handling: opening a bin wastes capacity early;
    // penalize it proportionally to stream progress and how well it fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // new bin useful for chaining large items
        }
    }

    // Prefer bins whose residual is below mean (consolidate waste in few bins).
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual {
        score += 0.15 * (resid_f - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - resid_f);
    }

    // Slight preference for bins that leave residuals matching common item sizes.
    let pr = post_residual;
    if pr >= 10 && pr <= 20 {
        score -= 3.0;
    } else if pr > 0 && pr < 10 {
        score += 4.0; // tiny unusable sliver
    }

    // Late-stream consolidation: fewer open bins preferred as stream ends.
    let remaining = total_items.saturating_sub(step_index) as f64;
    if remaining < 5.0 {
        score += 0.8 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; late, tighten strongly.
    let tight_weight = 0.5 + 2.0 * progress * progress;
    score -= tight_weight * (pr as f64).powi(2) / cap;

    // Reward filling bins nearly completely, smoothly via cubic term.
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that cannot fit a plausible next item (smooth coupling).
    let nxt = next_item_size as f64;
    let unusable = ((nxt - pr).max(0.0)) / cap;
    score += 20.0 * unusable * (0.5 + progress);

    // Last-chance bin bonus (smoothly weighted).
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - fit_ratio);
    }

    // Mild penalty for scattering across many open bins relative to mean residual.
    let dev = (mean_residual - pr) / cap;
    score += 5.0 * dev * dev * (1.0 + progress);

    // Slight preference for keeping some larger residual bins available mid-stream.
    score += 3.0 * progress * (1.0 - progress) * 4.0 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large powers
    // of small integers are more reusable by future items.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -50.0 // perfect fit, best possible outcome
    } else {
        let mut h = 0.0;
        let mut p = 2u32;
        while p * p <= pr {
            let mut q = p;
            while q <= pr && pr % q == 0 {
                h += 1.0;
                q *= p;
            }
            p += 1;
        }
        -2.5 * h
    };
    score += harmonic_bonus;

    // Integer-division thresholds on post_residual: dead space below the
    // smallest item size is unusable -> penalize.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    if pr >= 10 && pr < 20 {
        score += 5.0;
    }

    // Capacity fraction coupling: reward using a large fraction of the bin.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_frac * fill_frac;

    // Next-item lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            score -= 8.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 6.0; // next item won't fit here; keep larger residual bins free
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let base = 40.0 - 15.0 * (1.0 - progress) - 25.0 * scarcity;
        score += base.max(0.0) + 0.5 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tighter packing), penalize above-mean residuals mildly.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Modulo-10 class of residual: round residuals (multiples of 10) are
    // more likely to be exactly consumed by typical item sizes.
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever be useful
    // (below the minimum item size, or below the lookahead item) are toxic.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(next_item_size.min(post_residual)) {
        // unreachable guard, keep structure explicit
    }
    if post_residual > 0 && post_residual < 10 {
        // unusable micro-gap: heavy penalty scaled by gap smallness
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap cannot host the next item: dead weight unless it's a perfect-ish fit now
        let tightness = 1.0 - (post_residual as f64 / next_item_size as f64);
        score += 25.0 * tightness;
    }

    // Reward near-perfect fits (small but plausibly reusable residuals)
    if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Last-chance bin pressure: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits more aggressively
        score += (post_residual as f64) * (0.5 + 0.1 * fitting_bins_count as f64).min(2.0);
    }

    // Open-bin pressure: when many bins are open, discourage new bins / loose fits
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost, raised when open bins already exist,
        // lowered late in the stream when mean residual is high (bins are cluttered)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 2.0 * ob - 10.0 * progress;
        if next_item_size > 0 && next_item_size > bin_capacity {
            score += 100.0;
        }
        // opening a fresh bin is attractive if the item barely fits anywhere else
        if fitting_bins_count >= 1 && post_residual <= 5 {
            score -= 12.0;
        }
    } else {
        // existing bin: mild bonus for keeping bins consolidated
        score -= 1.5;
        // penalize using a bin whose residual is far above mean (fragmented state)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Lookahead synergy: if the next item exactly fills this bin's post-residual,
    // reward strongly (chained perfect packing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match: next item can fit into post_residual (chain placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize dead space proportionally.
        let dead = post_residual as f64;
        score += 0.5 * dead;
        if dead < 10.0 {
            score += 20.0; // tiny unusable sliver
        }
    }

    // Prefer bins tighter than the mean residual (good fills).
    let dev = mean_residual - post_residual as f64;
    score -= 2.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: keep it attractive only when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 5.0 * pressure + 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0; // fresh bin can chain the next item too
        }
    }

    // Mild preference for consolidating into fewer bins early on.
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: strongly penalize residuals too small for any item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: bonus if next item fits into post_residual.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Reward packing into tight (low-residual) bins relative to the mean.
    let tightness = mean_residual - bin_residual as f64;
    score += 0.4 * tightness;

    // New-bin candidate handling: penalize opening a new bin mildly,
    // more so late in the stream; but reward it when the current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) > 0.0 && (post_residual as f64) < 25.0;
        if bad_fit && next_item_size > 0 && (post_residual as u64) < next_item_size as u64 {
            score -= 50.0; // open fresh bin rather than wreck one
        } else {
            score += 30.0 + 40.0 * progress;
        }
    }

    // Mild dispersion penalty for hoarding many open bins.
    score += 0.5 * open_bins_count as f64 * (0.3 + progress);

    // Prefer placing larger items earlier (less fragmentation later).
    score -= 0.15 * item_size as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;
    let mean_res_n = mean_residual / cap;
    let next_n = next_item_size as f64 / cap;
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };

    // Base: prefer tight fits via non-linear post-residual penalty
    let mut score = norm_pr.powf(1.7) * cap;

    // Polynomial coupling of waste with stream progress: late stream punishes waste harder
    let progress_coupling = progress * (norm_pr * norm_pr - 0.5 * norm_pr + 0.25);
    score += progress_coupling * cap * 2.0;

    // Smooth interaction: exact fill (post_residual near 0) heavily rewarded
    score -= 12.0 * (1.0 - norm_pr).powf(6.0);

    // Reward bins whose residual matches the next item (lookahead smoothing)
    if next_item_size > 0 {
        let match_deg = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 6.0 * match_deg.max(0.0).powf(3.0);
    }

    // Last-chance bin: strong smooth reward scaled by fit quality
    score -= last_chance * (8.0 + 10.0 * (1.0 - norm_pr)) * (1.0 - norm_item * 0.5);

    // Penalize fragmenting large residuals when many bins are open
    let crowding = (open_bins_count as f64).ln1p();
    score += crowding * norm_pr.powf(2.5) * 3.0;

    // Mild pull toward bins with residuals above the mean (keeps variety)
    score += 1.5 * (norm_pr - mean_res_n).max(0.0);

    // New-bin candidate: neutral-ish score so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score = 10.0 + 6.0 * norm_item + 4.0 * progress;
        if last_chance == 1.0 {
            score += 8.0; // discourage opening new bin when a sole open bin fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_mod = post_residual % 10;
    let pr_div = post_residual / 10;

    // Reward residuals that form "harmonic" classes: multiples of 10 or
    // small residuals that are likely dead space anyway.
    if post_residual == 0 {
        score -= 200.0; // perfect fit
    } else if pr_mod == 0 {
        score -= 40.0; // residual aligns with decile classes -> future items likely fit
    } else if post_residual <= 5 {
        score += 30.0; // tiny dead space, useless
    }

    // Integer-division thresholds: residuals in [20, 40] are the most reusable
    // for unknown distributions (mid classes).
    if pr_div >= 2 && pr_div <= 4 {
        score -= 15.0;
    } else if pr_div > 6 {
        score += 10.0; // large residuals mean we under-filled this bin
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // exact chain
        } else if next_item_size <= post_residual {
            let fit_slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - fit_slack / cap).min(1.0);
            // harmonic class match between next item and residual
            if (post_residual % 10) == (next_item_size % 10) {
                score -= 10.0;
            }
        } else {
            // next item cannot use the leftover: penalize based on wasted class
            score += 0.3 * pr;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 * mean_residual < 0.5 * cap;
        score = 0.5 * cap + 60.0 * progress;
        if mean_residual < 15.0 && !crowded {
            score -= 70.0; // open bins nearly full -> open new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size && item_size >= 50 {
            score -= 40.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone_hi = 12.0f64.min(next_item_size.max(1.0) as f64 - 1.0);
    if post_residual > 0 && (post_residual as f64) < dead_zone_hi.max(1.0) {
        score += 40.0 + (12.0 - post_residual as f64) * 3.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if (post_residual as f64) >= dead_zone_hi.max(1.0) {
        // Usable leftover: mild reward scaled by tightness.
        score -= (post_residual as f64) * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score -= pressure * 3.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        }
        // If next item would NOT fit in post_residual, dead space is worse.
        if next_item_size > post_residual {
            score += 10.0;
        }
    }

    // New-bin candidate: keep it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: post_residual exactly matches next item => huge reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // post_residual can host next item: mild reward proportional to slack
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize dead space relative to next item
            score += 30.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare against mean residual: bins tighter than mean are good targets
    score -= 15.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0; // fresh bin can host a clean pair
        }
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
    }

    // Slight preference for filling fewer bins overall as stream progresses
    score += (open_bins_count as f64).ln() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary objective: minimize leftover space (best-fit core).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio; // reward tight fits super-linearly

    // Lookahead (k=2): penalize bins whose residual would become unusable
    // for the next item, reward bins that can host both.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // chain placement possible
            let combo_waste = post_residual - next_item_size;
            score -= 4.0 * (1.0 - combo_waste as f64 / bin_capacity as f64);
        } else if post_residual > 0 {
            // residual becomes dead space for the next item
            let dead = post_residual as f64;
            let next_fits_now = dead + item_size as f64 >= next_item_size as f64;
            score += 3.0 * dead / 10.0;
            if !next_fits_now { score += 5.0; }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual == 0 { score -= 10.0; } // perfect closure
    } else if fitting_bins_count > 2 {
        // many alternatives: mildly penalize so the tightest fit wins
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state coupling: when mean residual across open bins is high,
    // we have slack elsewhere -> be pickier (penalize mediocre fits).
    score += 0.08 * mean_residual * (1.0 - fit_ratio);

    // Time horizon: early in the stream, keep bins flexible (penalize tiny
    // residuals); late in the stream, aggressively close bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Bin count pressure: with many open bins, favor consolidation.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // NEW-BIN CANDIDATE handling: a fresh empty bin is only attractive when
    // no existing bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_exists = post_residual as f64 <= mean_residual + 0.5 * item_size as f64
            && fitting_bins_count > 0;
        if decent_exists {
            score += 25.0; // discourage opening a new bin
        } else {
            score -= 15.0; // escape hatch: poor fits everywhere -> open new bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste minimization with non-linear penalty on tiny residuals
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling: late in the stream, prefer tighter fits more aggressively
    let late = progress * progress;
    score -= late * (cap - pr) * 0.5;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Scarcity pressure: many open bins relative to progress -> discourage hoarding
    let scarcity = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += scarcity * norm_pr * 10.0 * (0.5 + progress);

    // Lookahead: reward if next item can use the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 8.0 * snug * (1.0 - progress);
    }

    // Mean-residual alignment: prefer bins near the average residual (smooth)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 15.0;

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress + 5.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: residuals that form useful
    // "denominators" of the capacity are more likely to be filled later.
    let post_u = post_residual;
    let mut harmonic_bonus = 0.0;
    for d in [2u32, 4, 5, 10, 20, 25, 50] {
        if cap as u32 % d == 0 {
            let class = cap as u32 / d;
            if post_u == class {
                harmonic_bonus += 6.0;
            }
            if post_u >= class && post_u < class + 5 {
                harmonic_bonus += 2.0;
            }
        }
    }
    // Small dead space (unusable for typical items) is bad.
    if post_u > 0 && post_u < 10 {
        score += 15.0;
    }
    // Perfect fit is excellent.
    if post_u == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_u {
            score -= 30.0;
        } else if next_item_size < post_u {
            let new_post = post_u - next_item_size;
            if new_post < 10 {
                score -= 8.0; // chain of near-perfect fits
            } else {
                score -= (new_post as f64).min(20.0) * 0.3;
            }
        } else {
            // next item cannot use this residual: residual becomes dead weight
            score += (post_u as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tightest (post already encodes that)
        score += (fitting_bins_count as f64) * 0.5;
    }

    // New-bin candidate: only attractive when item is large relative to
    // capacity or all open bins would leave big dead space.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score = 40.0 - 45.0 * fill;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room for a companion item in fresh bin
        }
        if fitting_bins_count == 1 {
            score += 25.0; // an open bin can take it; avoid waste
        }
    }

    // Progress-aware tightening: late in stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.4 * progress;

    // Slight preference to consolidate when many bins are open.
    score -= mean_residual * 0.05;

    score + harmonic_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward (dead space eliminated entirely)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Unusable small dead space: gaps that no item (min size 1..100) can later use well
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Moderate gap: only small items can use it
        score += 8.0;
    }

    // Penalize large leftover only mildly — it stays reusable
    if post_residual >= 50 {
        score -= 5.0;
    }

    // Next-item lookahead: reward gaps that can hold the lookahead item,
    // penalize gaps that just miss it by a small margin (worst case)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size - post_residual <= 10 {
            score += 12.0; // near-miss gap is likely dead space
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are crowded
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        // But if the item is huge and mean residual is small, new bin is fine
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 30.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins tighter than average (good fit relative to fleet)
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post residual), scaled
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 40.0;

    // Penalize small unusable leftovers (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else if next_item_size <= bin_residual {
            // next item would fit here anyway; mild penalty for wasting exact fit
            score += 5.0;
        }
        // if next item is huge, prefer keeping residuals flexible
        if next_item_size > 70 && post_residual < next_item_size {
            score += 6.0;
        }
    } else {
        // last item: any placement is fine, reward closing out bins
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many fitting bins: slight preference for tightest (already via fit_ratio),
    // but add small tie-break toward bins with less absolute residual
    if fitting_bins_count > 1 {
        score += bin_residual as f64 * 0.05;
    }

    // Global state: penalize opening new bins when many open bins exist
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 * 3.0;
        score += 20.0 + open_pressure + progress * 15.0;
        // Opening a new bin is acceptable if current item is large and mean residual is high
        if item_size > 60 && mean_residual < item_size as f64 {
            score -= 25.0;
        }
    } else {
        // Reward reusing bins relative to mean residual of the pool
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Time horizon: early in stream, be slightly conservative (keep space flexible);
    // late in stream, pack aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize large post-residual (wasted space), with non-linear growth
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate residuals; late, penalize them harder.
    let coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * coupling * pr_norm;

    // Interaction: small residual left is great; penalize "awkward" residuals
    // that are too large to be useful but too small for typical items.
    let awkward = (pr_norm * (1.0 - pr_norm)).max(0.0); // peaks mid-range
    score += 15.0 * awkward * (0.5 + coupling);

    // Reward tight fits
    score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - (pr / next_item_size.max(1) as f64).min(1.0));
    }

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly when many open bins exist with slack.
    if bin_residual == bin_capacity {
        let mean_res_norm = mean_residual / cap;
        score = cap - 30.0 * (1.0 - progress) - 20.0 * mean_res_norm;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which capacity-fraction band does post_residual fall in
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Penalize residuals that are dead space: too small for typical items (min size 10)
    if pr < 10.0 {
        score += 40.0 * (10.0 - pr) / 10.0;
    }

    // Reward tight fits (post_residual small but still useful)
    if pr > 0.0 && pr <= eighth {
        score -= 12.0;
    } else if pr <= quarter {
        score -= 6.0;
    }

    // Modulo-10 class coupling: residuals that are multiples of 10 are "harmonic"
    // with the integer item grid, more likely reusable.
    if post_residual % 10 == 0 {
        score -= 4.0;
    }

    // Lookahead: if the next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
            // exact harmonic match: next item exactly consumes residual
            if next_item_size == post_residual {
                score -= 20.0;
            }
            // bonus if next item lands in the same modulo-10 class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to the mismatch
            let gap = (next_item_size - post_residual) as f64;
            score += 3.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish score so we only open new bins
    // when existing bins have poor fits. Base new-bin score on mean residual pressure.
    if bin_residual == bin_capacity {
        // opening a bin is attractive when open bins are congested or few
        score = cap * 0.55 - (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // if mean residual is large, existing bins have room; discourage new bin
        score += mean_residual * 0.3;
    }

    // Mild penalty for leaving residuals in awkward mid-range band (3/8..5/8)
    if pr > cap * 0.375 && pr < cap * 0.625 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host
    // the smallest plausible future item (<=10) are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize large post-residuals less if they can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // keeps room for the next item: good
        } else {
            score += 15.0; // breaks the chain for the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // fresh bins; encourage filling existing ones.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable only when remaining open bins are
        // badly fragmented (high mean residual spread) or it's a poor fit.
        score += 30.0 + open_pressure;
        if mean_residual < 15.0 {
            score -= 20.0; // existing bins nearly full -> new bin is fine
        }
    } else {
        // Filling an existing bin reduces open-bin pressure slightly.
        score -= open_pressure * 0.1;
    }

    // Progress-based nudge: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.10;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed (dynamic time horizon).
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward filling the bin well (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item can fit into the post residual, this placement
    // keeps a useful gap; if next item would exactly fill it, huge bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Dead space the known next item cannot use: penalize, scaled by gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 12.0 * tightness;
    }

    // Last-chance bin: if this is the only open bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * tightness;
    }

    // New-bin candidate: penalize opening a new bin, more so early on and when
    // open bins have plenty of room on average.
    if bin_residual == bin_capacity {
        let early_penalty = 30.0 * (1.0 - t);
        score += 20.0 + early_penalty + 0.1 * mean_residual;
        // But if no existing bin fits at all, the new bin is the only option:
        // the fitting_bins_count==1 last-chance bonus above won't apply (residual==capacity),
        // so soften slightly.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate emptier space elsewhere).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    // Mild pressure to use existing bins as stream progresses.
    score -= 0.5 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual, with smooth polynomial shaping
    let mut score = norm_post + 0.35 * norm_post * norm_post + 0.15 * norm_post.powi(3);

    // Tight fit reward: quadratic coupling of post_residual with item size
    let item_frac = item_size as f64 / cap;
    score -= 0.25 * item_frac * (1.0 - norm_post) * (1.0 - norm_post);

    // Stream progress coupling: early on, keep bins flexible; later, pack tightly
    score += 0.30 * progress * norm_post;
    score -= 0.20 * progress * item_frac * norm_post;

    // Penalize bins far from the mean residual (smooth dispersion term)
    let disp = (bin_residual as f64 - mean_residual) / cap;
    score += 0.10 * disp * disp;

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 0.60 + 0.40 * (1.0 - norm_post);
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let next_frac = next_item_size as f64 / cap;
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 0.35 * fits_next * next_frac * (1.0 - norm_post);
        // Penalize leaving residual just below next item (dead space)
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap < 0.0 {
            score += 0.20 * (-gap / cap) * (1.0 - progress);
        }
    }

    // New-bin candidate: mildly penalize opening new bins when progress is low,
    // reward when bins are crowded
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        score += 0.55 - 0.45 * crowd * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    score -= 40.0 * (1.0 - post_residual as f64 / cap).powi(6);

    // Harmonic classes: dead space in small residual bands is unusable.
    // Penalize post_residuals in "dead zones" (1..10 and 11..19 bands get
    // graded penalties via integer division classes).
    let pr = post_residual;
    if pr > 0 {
        let class = pr / 10; // integer division: harmonic band 0..=10
        score += 8.0 * (class as f64).sqrt() * (1.0 - (pr % 10) as f64 / 10.0);
    } else {
        score -= 25.0; // perfect closure bonus
    }

    // Lookahead: penalize if the next item cannot use the leftover space.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size > post_residual {
            score += 12.0 * (next_item_size - post_residual) as f64 / cap;
        } else {
            // next item fits into the leftover: reward proportionally
            score -= 10.0 * (post_residual - next_item_size) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is poor or
    // open bins are heavily fragmented; otherwise discourage opening bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = 1.0 - (post_residual as f64 / cap); // = item/cap for new bin
        let fragmentation = (mean_residual / cap - 0.5).abs();
        let poor_fit = (post_residual as f64 / cap) > 0.45 && post_residual > 0;
        if poor_fit || open_bins_count == 0 {
            score -= 18.0 + 10.0 * (1.0 - progress);
        } else {
            score += 15.0 + 20.0 * fragmentation;
        }
        let _ = fit_quality;
    }

    // Mild preference to fill already-open bins when many are open.
    score += 0.6 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if it is too small to hold even a modest item.
    let dead_threshold = (cap * 0.10).max(1.0);
    if post > 0.0 && post < dead_threshold {
        // The smaller the gap relative to threshold, the worse (quadratic).
        let t = post / dead_threshold; // in (0,1)
        score += (1.0 - t) * (1.0 - t) * 150.0;
    }

    // Waste ratio penalty: fraction of bin turned into leftover.
    let fill = item_size as f64 / bin_residual as f64;
    score += (1.0 - fill) * 40.0;

    // Reward tight fits strongly (post_residual small relative to item).
    if item_size > 0 {
        score -= (item_size as f64) / (post + 1.0) * 5.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && (next_item_size as f64) == post {
        score -= 400.0;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 20.0;
    } else if next_item_size > 0 {
        // Next item cannot use this gap: the leftover is likely dead space.
        score += 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Open bins pressure: mild incentive to consolidate into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + progress) * 2.0;

    // Prefer bins with residual close to the mean (balance residuals).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: penalize opening a new bin unless the fit is poor
    // (i.e., using an open bin would leave a large dead gap).
    if bin_residual == bin_capacity {
        score += 120.0;
        // But allow new bin if it would create a near-perfect load.
        if fill > 0.85 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits (low dead space) nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else {
        // Penalize dead space quadratically relative to capacity.
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item exactly or nearly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next_item_size == post_residual {
            score -= 55.0;
        } else if post >= next {
            // Bonus proportional to tightness of the follow-up fit.
            let tight = 1.0 - ((post - next) / bin_capacity as f64);
            score -= 30.0 * tight;
        } else {
            // Next item cannot fit: penalize wasted potential.
            score += 12.0 * (1.0 - post / next);
        }
        // Coupling with mean residual: if this bin is far below mean residual,
        // it's the "emptiest" bin — prefer using it (keep tight bins for tight fits).
        if (post_residual as f64) > mean_residual {
            score += 0.35 * (post_residual as f64 - mean_residual);
        } else {
            score -= 0.15 * (mean_residual - post_residual as f64);
        }
    }

    // Last-chance bin: only open bin that fits — strong reward to avoid new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to prefer the best-fitting one naturally.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // New-bin candidate: only attractive early in the stream or when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scale = 0.4 + 0.6 * progress;
        score += 45.0 * scale;
        // If lookahead suggests the next item pairs with a fresh bin, soften penalty.
        if next_item_size > 0 && (next_item_size as f64 + item_size as f64) <= bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Mild preference for consolidating into fewer bins late in stream.
    score += 0.5 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio discount.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer bins with below-average residual (concentrate waste in few bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Time horizon: late in the stream, avoid opening new bins / spreading waste.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses unless current bin is hopeless.
        score += 6.0 + 20.0 * progress;
        // Opening a fresh bin is fine if item is huge and would strand an open bin.
        if item_size >= 70 && post_residual < 10 {
            score -= 18.0;
        }
    } else if progress > 0.7 {
        score -= 4.0 * progress; // favor packing into existing bins late
    }

    // Mild preference for fuller bins overall.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // Slight penalty when many bins are open (encourage consolidation).
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr
        + 12.0 * (pr / cap) * (pr / cap) * (0.5 + progress)
        - 8.0 * (pr / cap) * progress;

    // Reward near-perfect fills more strongly later in the stream
    let tightness = 1.0 - pr / cap;
    score -= 10.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (nxt - pr).max(0.0);
        score += 0.6 * waste * (1.0 + progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * open_bins_count as f64 * (pr / cap);

    // Deviation from mean residual: prefer bins close to mean (balance)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect closure, strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: residues that are "hard to fill"
    // (small but nonzero leftovers) create dead space. Penalize via
    // capacity-fraction classes: post_residual in (0..=9] is dead space.
    if post_residual > 0 && post_residual <= 9 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Integer-division thresholds on post_residual: quarter/half classes.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= quarter && post_residual < quarter + quarter / 2 {
        score -= 25.0; // sweet spot: leaves room for medium items
    }
    if post_residual > half {
        score -= 10.0; // roomy bin still flexible
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // this placement sets up a chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; leftover becomes dead space risk
            score += 15.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // multiple options: prefer the tightest naturally via post_residual,
        // but add mild penalty to discourage fragmenting many-bin pools
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin unless the item is large relative to capacity
    // or all open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let open_ratio = open_bins_count as f64;
        let mean_r = mean_residual;
        // If mean residual across open bins is large, better to use them.
        let fragmentation = if open_ratio > 0.0 { mean_r / open_ratio.max(1.0) } else { 0.0 };
        let _ = fragmentation;
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.7;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 120.0;
        if big_item { new_bin_penalty *= 0.5; }
        if fitting_bins_count == 0 { new_bin_penalty = -50.0; } // forced
        // late in stream, slightly prefer reusing
        new_bin_penalty += 30.0 * progress;
        score += new_bin_penalty;
    }

    // Modulo harmonic classes on post_residual: residues divisible by 10
    // pair well with typical item sizes (multiples of 5/10).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 7.0;
    }

    // Mild preference for bins with residual close to mean (balance pool).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Reward bins whose residual matches the item well (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= 3.0 / (1.0 + tightness);

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 18.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual cannot host next item: mild penalty unless tiny dead space already penalized.
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, discourage spreading; prefer filling.
    score += (open_bins_count as f64) * 0.35 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., item is large relative to typical residual or many bins already open).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        let item_heaviness = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items or when many bins are open and mean residual is small.
        let new_bin_bonus = 10.0 * item_heaviness + 3.0 * pressure + (mean_residual < item_size as f64) as i32 as f64 * 6.0;
        score -= new_bin_bonus;
        // But keep some inertia against spawning bins early in the stream.
        score += 4.0 * (1.0 - (step_index as f64 / (total_items.max(1) as f64)).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-chain: next item exactly fills the bin after this placement.
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 60.0 + 20.0 * progress; // reward grows as stream progresses
        }
        // Next item fits with a small remainder: strong reward.
        else if next_item_size <= post_residual {
            let leftover = post - nxt;
            let tightness = 1.0 - (leftover / 100.0);
            score -= 15.0 + 35.0 * tightness * tightness;
        }
        // Next item does NOT fit: penalize proportionally to wasted lookahead potential.
        else {
            let gap = nxt - post;
            score += 5.0 + 0.25 * gap;
        }
    } else {
        // Last item: strongly prefer minimal final residual.
        score -= 40.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Bins tighter than the mean are better candidates for large items.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res_f / mean_residual;
        score += 8.0 * (rel - 1.0); // penalize looser-than-average bins
    }

    // --- Tightness reward for the current fit ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // --- Last-chance bin: must use it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when few bins fit the item
        // and current bins are all loose (high mean residual).
        let open_f = open_bins_count as f64;
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        let bonus = if fitting_bins_count == 0 {
            100.0
        } else if fitting_bins_count == 1 {
            10.0
        } else {
            -15.0 - 3.0 * open_f
        };
        score += 20.0 - bonus - 10.0 * pressure;
        // Early in stream, fresh bins are cheap.
        score -= 10.0 * (1.0 - progress);
    }

    // --- Fragmentation penalty: leave residuals too small for typical items ---
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small post-residual is already low,
    // add extra bonus when the leftover would be too small for typical items).
    if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 6.0;
    } else if post_residual < 35 {
        score -= 2.0;
    }

    // Penalize bins whose residual is much larger than needed (waste of big space).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * waste_ratio * waste_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Slight preference when many bins compete: keep choice flexible,
        // mildly favor consolidation.
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead coupling: if the next item could use this bin's post-residual,
    // reward; if the next item would NOT fit here but fits elsewhere, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: extra reward for tight chain.
            let chain_left = post_residual - next_item_size;
            score -= 8.0 - (chain_left as f64) * 0.1;
        } else {
            // Next item breaks this bin's usability: penalize proportionally.
            score += 4.0;
        }
    }

    // Global state: if mean residual across open bins is high, we have slack
    // everywhere -> discourage filling a bin poorly, encourage new bin when fit is bad.
    if mean_residual > item_size as f64 * 1.5 {
        score += 3.0;
    } else {
        score -= 1.0;
    }

    // Time horizon: early in the stream, opening bins is cheap (long future to
    // fill them); late in the stream, avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it loses to decent fits.
        score += 20.0;
        // But allow new bin early or when current bin would leave huge dead space.
        score -= 30.0 * (1.0 - progress);
        if post_residual >= 0 && bin_residual < item_size + 5 {
            score -= 10.0; // never happens for empty bin, kept for symmetry
        }
        if mean_residual < 15.0 {
            score -= 8.0; // open bins nearly full -> new bin is fine
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 12.0; // next item is large; fresh bin is valuable
        }
    }

    // Mild penalty for proliferating bins.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let res = bin_residual as f64;
    let it = item_size as f64;

    // Base: tight fits favored, with a non-linear (quadratic) reward for small post-residual.
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Smooth coupling with stream progress: later in the stream, dead space matters more.
    score += 8.0 * progress * (pr / cap) * (pr / cap) * cap * 0.1;

    // Penalize using a nearly-full bin poorly; reward using bins whose residual is close to item size.
    let fit_quality = (res - it) / cap;
    score += 3.0 * fit_quality * fit_quality * cap * 0.1;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * (1.0 + progress);
        } else {
            score += 2.0 * (nxt - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins vs mean residual alignment.
    score += 0.05 * (open_bins_count as f64).ln() * (pr / cap);
    score += 0.5 * (mean_residual - pr) / cap;

    // New-bin candidate handling: empty bin gets a moderate score so it wins only when fits are bad.
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.25 * progress) - 3.0 * (1.0 - it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits get huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty grows quadratically for small residuals.
        score += (post_residual as f64).powi(2) / 200.0;
    }

    // Modulo classes: residuals divisible by common item sizes are reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 15.0; }
        else if pr % 5 == 0 { score -= 8.0; }
        else if pr % 3 == 0 { score -= 4.0; }
        else { score += 6.0; } // awkward class
    }

    // Lookahead: prefer bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 60.0 - 40.0 * frag;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 * 3 / 4 {
            score += 10.0; // big next item: fresh bin helps
        }
        if post_residual == 0 { score -= 500.0; }
    }

    // Progress coupling: early on, be pickier about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for unusable dead space: gaps too small for the smallest item (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }
    // Also penalize gaps that can't fit the lookahead item (wasted future capacity)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + 0.1 * next_item_size as f64;
    }
    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 25.0;
    }
    if item_size == bin_residual {
        score -= 15.0;
    }

    // Reward tight relative fit (small waste fraction)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins with residual below the mean (tighter bins)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // If lookahead fits well in a fresh bin, mildly favor opening
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host next_item_size
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact match for the next item is excellent
            if post_residual == next_item_size {
                score -= 500.0;
            } else {
                let slack = (post_residual - next_item_size) as f64;
                // prefer small leftover after hosting the next item
                score -= 200.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // next item cannot fit here: penalize dead space creation
            let gap = (next_item_size - post_residual) as f64;
            score += 50.0 * (gap / next_item_size as f64);
        }
    }

    // Relative to mean residual: bins with unusually large residual are good hosts
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Early in the stream, prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0);

    // New-bin candidate: penalize opening a new bin unless the item is huge
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 250.0 + 0.5 * waste;
        if item_size > bin_capacity * 3 / 4 {
            score -= 100.0; // huge items may justify a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base waste: penalize leftover space quadratically (dead space is the enemy)
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Reward tight fits: small post_residual gets a strong discount
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 25.0 - (post_residual as f64);
    }

    // Lookahead: if the next item fits into the post residual, this placement
    // chains nicely — reward it proportionally to how well it fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack_after_next / bin_capacity as f64);
    }
    // If next item almost fits (within a small gap), mildly penalize creating a trap
    if next_item_size > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate: it starts with post_residual == capacity (100), which
    // already scores high. Add a dynamic penalty that shrinks as the stream
    // progresses, so late in the stream consolidating into open bins is favored,
    // but early on opening bins is cheap.
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress);
        // If no open bin fits well (many bins but poor mean fit), opening is fine:
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Global pressure: if mean residual across open bins is large, we have lots
    // of slack available — penalize placements that leave large residuals further.
    if bin_residual < bin_capacity {
        let rel = pr / (mean_residual.max(1.0));
        score += 4.0 * (rel - 1.0).clamp(-1.0, 1.0);
    }

    // Mild preference for filling already-open bins as open bin count grows
    if bin_residual < bin_capacity {
        score -= 0.15 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: penalize residual, weighted non-linearly by stream progress
    let mut score = pr * (1.0 + progress * progress);

    // Smooth non-linear coupling: residual squared term scaled by progress
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) with a cubic discount
    score -= cap * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * 2.0;

    // Penalize dead space unusable by the next item (smooth interaction)
    let waste = (pr - norm_next * cap).max(0.0) / cap;
    score += waste * waste * cap * (1.5 + progress);

    // Last-chance bin bonus: subtract to favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= cap * (0.8 + 0.4 * progress);
    }

    // Penalize spreading across many open bins when mean residual is high
    score += (open_bins_count as f64).ln().max(0.0) * mean_residual * 0.05 * (1.0 - progress);

    // Mild reward for large item into this bin (fills space efficiently)
    score -= norm_item * norm_item * cap * 0.5;

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += cap * (0.6 + 0.6 * progress) - pr * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual (integer division thresholds)
    let class = post_residual / 10;
    score -= match class {
        0 => 25.0,               // near-perfect fit (0..=9 dead space)
        1 => 12.0,               // good fit (10..=19)
        2 => 5.0,                // acceptable (20..=29)
        3 => 1.0,
        _ => 0.0,
    };

    // Modulo-style refinement: multiples of 5 in dead space are more reusable
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: reward bins whose residual can host the next item (k=2 lookahead)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 4.0 * (1.0 - progress);
    }
    // Penalize if next item is close to fitting but just misses (wasted pairing)
    if next_item_size > 0 && next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 12.0; // default: prefer existing bins
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits anywhere -> open a new bin
        } else if post_residual as f64 > mean_residual + 20.0 {
            score += 5.0; // poor fit in existing bins would strand space
        }
    }

    // Relative dead-space coupling with mean residual
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Early stream: be slightly more conservative about tight residual bins
    score += 4.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the minimum
    // item size (1..100 interface => treat < item_size of smallest plausible
    // item) are wasted. Penalize tiny unusable gaps heavily.
    let dead_threshold: f64 = 10.0; // smallest historical item size
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 200.0 + (dead_threshold - post_residual as f64) * 20.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if (post_residual as f64) < 0.25 * bin_capacity as f64 {
        score -= 40.0 * (1.0 - post_residual as f64 / (0.25 * bin_capacity as f64));
    }

    // Penalize large leftover gaps that likely become dead space later.
    if post_residual > 60 {
        score += (post_residual - 60) as f64 * 1.5;
    }

    // Open-bin pressure: prefer consolidating into existing bins over
    // opening new ones as the number of open bins grows.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if next item fits snugly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap => gap likely dead.
        score += 25.0;
    }

    // Mean-residual coupling: bins far below mean residual are "loose";
    // prefer filling bins tighter than average.
    score += 0.5 * ((post_residual as f64) - mean_residual);

    // New-bin candidate: baseline score so it loses to good fits but wins
    // over terrible fits (large dead-space penalties above).
    if bin_residual == bin_capacity {
        score = 55.0 + open_bins_count as f64 * 1.5 - (post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // --- 2-step lookahead coupling: match post_residual against next_item_size ---
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual == next_item_size {
            // Perfect pairing: this bin's leftover exactly hosts the next item
            score -= 60.0;
        } else if gap <= 4 {
            score -= 25.0;
        } else if gap <= 10 {
            score -= 10.0;
        }
        if next_item_size > post_residual {
            // Leftover is dead space for the upcoming item
            score += 6.0 + 0.15 * next_item_size as f64 * (1.0 - progress);
        }
    } else {
        // Last item: minimize leftover directly (score already = post_residual)
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly favor it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // --- New empty bin candidate: penalize opening a new bin unless fits are poor ---
    if bin_residual == bin_capacity {
        let mut penalty = 35.0;
        if fitting_bins_count <= 1 {
            penalty -= 20.0; // few alternatives, opening is more acceptable
        }
        if next_item_size > 0 && next_item_size >= item_size {
            penalty -= 8.0; // large upcoming item benefits from a fresh bin
        }
        score += penalty;
    }

    // --- Relative-to-mean residual shaping ---
    if bin_residual < bin_capacity {
        let dev = post_residual as f64 - mean_residual;
        score += 0.08 * dev; // prefer bins tighter than the average residual
    }

    // --- Dead-space penalty for tiny unusable leftovers ---
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: bins whose residual is close to the item size.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: small post-residuals that no future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }
    // Reward residual that could fit the next item (lookahead synergy).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 8.0 * (1.0 - (nx / (post_residual as f64 + 1.0)));
        } else {
            score += 4.0 * (nx - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strong reward to use the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin fits well, or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (mean_residual / cap).min(1.0);
        // Prefer new bin when mean residual is low (bins nearly full)
        // or item is large relative to typical residual.
        score = cap * 0.6
            - 30.0 * (1.0 - crowded)
            + 15.0 * progress
            - (item_size as f64) * 0.3;
        if fitting_bins_count == 1 {
            // An open bin is the only option; discourage opening a new one.
            score += 40.0;
        }
    } else {
        // Mild penalty for using bins whose residual is much larger than item
        // (waste), scaled by how many other options exist.
        if bin_residual as f64 > (item_size as f64) * 2.0 {
            score += 3.0 * (fitting_bins_count as f64).min(3.0);
        }
    }

    // Global balance: when many bins are open with large mean residual,
    // slightly favor consolidating into bins below-average residual.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: strongly prefer small post_residual, with smooth quartic coupling to stream progress.
    // Later in the stream, tight packing matters more (fewer chances to recover wasted space).
    let mut score = 40.0 * pr * (1.0 + 0.8 * progress) + 60.0 * pr * pr * (1.0 + progress) + 30.0 * pr.powi(4);

    // Smooth penalty for leaving residual that neither fits the next item nor is "usable".
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Reward when post_residual is close to next item size (smooth bell via normalized gap)
            let gap = (post - nxt) / cap;
            score -= 25.0 * (-gap * gap * 40.0).exp();
        } else {
            // Dead space relative to lookahead: quadratic penalty
            let dead = (nxt - post) / cap;
            score += 20.0 * dead * dead * cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smoothly scaled by number of open bins).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 5.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // fits poorly everywhere else (large post_residual relative to mean residual),
    // or late in the stream when consolidation matters less. Smooth coupling.
    if bin_residual == bin_capacity {
        let mean_gap = (post - mean_residual).max(0.0);
        let openness = 1.0 / (1.0 + (-4.0 * (pr - 0.5)).exp()); // sigmoid: high when pr large
        score = 70.0 * openness + 0.15 * mean_gap + 10.0 * (1.0 - progress);
        // If a new bin leaves room for the next item, soften its score smoothly.
        if next_item_size > 0 && post >= next_item_size as f64 {
            score -= 15.0 * (post - next_item_size as f64) / cap;
        }
    }

    // Mild global regularization: prefer denser bins relative to fleet mean residual.
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "reusable" residue class are rewarded, dead-space classes penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Residue class modulo 10: residuals that are multiples of 10 pair well
    // with the common item-size granularities.
    let residue = post_residual % 10;
    let residue_bonus = match residue {
        0 => 6.0,
        1 | 9 => 1.0,
        2 | 8 => 0.5,
        _ => -1.5,
    };
    score -= residue_bonus;

    // Integer-division thresholds on post_residual: small leftovers are
    // nearly dead space; large leftovers keep the bin flexible.
    if post_residual < 10 {
        score += 8.0; // dead space penalty
    } else if post_residual <= 20 {
        score += 2.0;
    } else if post_residual >= 50 {
        score -= 3.0;
    }

    // Coupling with next item: reward exact fit of the lookahead into the
    // leftover (harmonic pairing), penalize near-misses.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / cap);
        } else {
            let over = (next_item_size - post_residual) as f64;
            score += 2.0 * (over / cap);
        }
    }

    // Fraction-of-capacity classes: prefer leaving residuals in the
    // [0.25C, 0.6C] band (most reusable for unknown distributions).
    let frac = pr / cap;
    if frac >= 0.25 && frac <= 0.6 {
        score -= 3.0 * (0.6 - (frac - 0.25).abs());
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64).sqrt() * 2.0;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / cap) * progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item size (1..100 interface => anything < 5 is near-waste) are heavily
    // penalized, scaled by how "stuck" the gap is.
    if post_residual < 5 {
        score += 60.0;
    } else if post_residual < 10 {
        score += 30.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // If the lookahead item exactly matches post_residual, strongly favor
    // this bin (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial lookahead fit: mild bonus proportional to fill.
        score -= 10.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Lookahead cannot use the gap: penalize leaving it.
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate: make empty bins attractive only when the current
    // stream is early or existing residuals are large (poor fits likely).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_pressure = (mean_residual - item_size as f64).max(0.0);
        score = 100.0 - 0.8 * poor_fit_pressure - 30.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 25.0; // discourage abandoning the sole fitting bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already in score.

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            // Perfect two-item packing: place here.
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // Next item could still fit here after this one.
            score -= 25.0 * (1.0 - gap as f64 / 50.0).max(0.0);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 0.5 * gap as f64;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are worth filling.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Prefer bins with larger residual overall (use near-full bins elsewhere).
    score += 0.1 * bin_residual as f64;

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        // Penalize opening a new bin, more so as stream progresses.
        let mut nb = 80.0 + 0.5 * open_pressure;
        // But if the item leaves huge dead space in every open bin, new bin wins.
        let wasteful = fitting_bins_count == 0 || post_residual as f64 > 0.6 * bin_capacity as f64;
        if wasteful {
            nb -= 100.0;
        }
        // If next item pairs well with this item in a fresh bin, encourage.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            nb -= 20.0;
        }
        score += nb;
    }

    // Small tie-breaker favoring earlier bins implicitly via residual decay.
    score += 0.001 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize leaving small unusable residuals (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.25 * next_item_size as f64;
        } else {
            score += 4.0;
        }
        // If next item exactly fills post residual, big bonus.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate handling: only attractive when few good options exist
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let desperation = (fitting_bins_count == 0) as i32 as f64
            + (item_size as f64 > mean_residual) as i32 as f64;
        score += 26.0; // base cost of opening a new bin
        score -= 20.0 * desperation;
        score -= 8.0 * (1.0 - progress); // slightly cheaper to open bins early
        // Prefer opening a new bin for very large items.
        score -= 0.15 * item_size as f64;
        // If many bins already fit the item, opening a new one is wasteful.
        score += 6.0 * (fitting_bins_count as f64).min(4.0);
    }

    // Mild preference for bins with smaller-than-average residual (consolidate waste).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight nudge toward bins that are already fairly full.
    score -= 0.08 * (bin_capacity - bin_residual) as f64;

    // Small time-dependent tie-breaker to diversify behavior across the stream.
    score -= 0.001 * (step_index as f64 % 7.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;

    // Penalize large dead space late in the stream (quartic smooth ramp)
    let late = progress * progress * progress;
    score += 60.0 * late * norm_pr * norm_pr;

    // Reward tight fits via smooth cubic of item fraction
    score -= 25.0 * norm_item * norm_item * (1.0 - norm_item);

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = (norm_pr - norm_next).max(0.0);
        score -= 15.0 * gap * (1.0 - progress);
        // Penalize if post_residual barely misses next item
        let miss = (norm_next - norm_pr).max(0.0);
        score += 20.0 * miss * miss;
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Penalize bins far below mean residual (fragmentation pressure), quadratic
    let dev = (mean_residual - pr) / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for opening a new bin when many bins already open
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        score -= 20.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes (10, 20, 25, 50) are more reusable; odd/prime-like gaps are dead space.
    let reusable = if post_residual == 0 {
        0.0
    } else if post_residual % 50 == 0 {
        12.0
    } else if post_residual % 25 == 0 {
        9.0
    } else if post_residual % 20 == 0 {
        8.0
    } else if post_residual % 10 == 0 {
        6.0
    } else if post_residual % 5 == 0 {
        3.0
    } else {
        0.0
    };
    score -= reusable;

    // Penalize tiny unusable gaps (< 10, the minimum item size) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // this placement is perfect (harmonic resonance).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if post_residual >= next_item_size && post_residual % next_item_size == 0 {
            score -= 10.0;
        } else if next_item_size > post_residual {
            // Next item won't fit here regardless; mildly neutralize gap penalty.
            score -= (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when few bins fit
    // the item or the stream is early; otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count as f64).recip();
        let new_bin_bonus = 15.0 * pressure + 10.0 * (1.0 - progress) - (open_bins_count as f64).min(10.0);
        score -= new_bin_bonus.max(-8.0);
    }

    // Tie-break toward bins tighter than the mean (best-fit flavor).
    score += ((post_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1..10) can use are toxic.
    if post_residual < 10 {
        score -= 25.0; // perfectly consumed or near-perfect fit is excellent
    } else if post_residual < 20 {
        score += 6.0; // small awkward gap
    } else if post_residual < 35 {
        score += 2.5;
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Penalize leaving a gap just below the next item's size (blocks the lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0 + (next_item_size - post_residual) as f64 * 0.15;
    }
    // Reward reserving space exactly for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.4;

    // Mean residual coupling: when open bins are already full-ish, prefer tighter fits.
    score += (mean_residual - post_residual as f64) * 0.1;

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            2.0
        } else {
            0.0
        };
        score = 55.0 + pressure - (fitting_bins_count as f64) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward near-exact 2-step lookahead match.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect match for the next item is heavily rewarded.
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        // Extra bonus if next item exactly exhausts the bin afterwards.
        if slack == 0.0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in the resulting residual: penalize proportionally
        // to how much dead space we create relative to the next item.
        let dead = next_item_size as f64 - post_residual as f64;
        score += 0.8 * dead;
    }

    // Coupling with mean residual: prefer bins whose post state stays near the mean
    // (balanced packing) when the stream is early/mid.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.25 * dev * (1.0 - progress);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when the fit is bad or
    // the item is large; otherwise opening bins is wasteful.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative, must open
        } else {
            score += 20.0 * (1.0 - fill_ratio);
            if next_item_size > 0 && next_item_size <= bin_residual - item_size {
                score -= 10.0; // new bin can also host the next item
            } else {
                score += 15.0;
            }
        }
    }

    // Mild preference for tighter fits overall (waste minimization).
    score += 0.1 * (post_residual as f64 % 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.5 * next_item_size as f64;
        // Extra reward if next item exactly fills the bin afterward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residuals that are just below the next item (dead space).
        let gap = next_item_size as f64 - post_residual as f64;
        if gap > 0.0 && gap <= 10.0 {
            score += 6.0 + gap;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin unless it is genuinely useful.
    if bin_residual == bin_capacity {
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        // New bin is attractive early or when open bins are mostly full/tight.
        let new_bin_bonus = 10.0 * (1.0 - pressure) * (1.0 - t) - 5.0 * pressure;
        score += 5.0 - new_bin_bonus;
        // If the item is large relative to typical residuals, opening fresh is fine.
        if item_size as f64 > mean_residual {
            score -= 6.0;
        }
    } else {
        // Slight preference for fuller bins (lower residual before placement).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Mild penalty for spreading across many open bins (encourage consolidation).
    if open_bins_count > 4 {
        score += 0.15 * (open_bins_count as f64 - 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, non-linearly
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, keep bins tight (tightness matters later); later, allow slack.
    let coupling = 30.0 * (1.0 - progress) * norm_pr * norm_pr
                 - 12.0 * progress * norm_pr * (1.0 - norm_pr);
    score += coupling;

    // Dead-space penalty: residuals too small to fit typical future items
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr as f64) / 10.0;
    }

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_margin = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - fit_margin / cap) * (0.5 + 0.5 * (1.0 - progress));
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 + progress);
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight_mean = (mean_residual / cap).max(0.0);
        score = cap as f64
            - 55.0 * scarcity * (1.0 + 0.5 * progress)
            + 20.0 * (1.0 - scarcity) * (1.0 + tight_mean)
            + 10.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mild penalty for many open bins early (encourage consolidation)
    score += 1.5 * open_bins_count as f64 * (1.0 - progress) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic-class decomposition of post_residual
    let cls = post_residual % 10;
    let quot = post_residual / 10;
    // Residuals in "nice" classes (0, 10, 20...) are reusable; odd/tiny remainders are dead space
    let dead_penalty = match cls {
        0 => -6.0,
        1 | 2 | 3 => 5.0 + (3 - quot.min(3)) as f64,
        4 | 5 | 6 => 1.5,
        7 | 8 | 9 => 3.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 40.0;
    }
    // Post residual large enough for typical next item class
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // lookahead fit: reward by how tightly it fits
            let tight = (post_residual - next_item_size) as f64;
            score -= 8.0 - (tight / 20.0).min(6.0);
            // exact modulo harmony: post_residual and next_item in same decade class
            if (post_residual % 10) == (next_item_size % 10) {
                score -= 3.0;
            }
        } else {
            // bin can't host next item: penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
        // next item is a "harmonic half" (multiple of 25/50): post residual of 50 or 25 is golden
        if next_item_size % 25 == 0 {
            if post_residual == next_item_size {
                score -= 12.0;
            }
        }
    } else {
        // last item: minimize leftover aggressively
        score -= 15.0;
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tightest fit implicitly; small bonus for scarcity
        score += (fitting_bins_count as f64 - 1.0) * 0.5;
    }

    // New-bin candidate: penalize opening unless current bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // open new bin when mean residual is small (bins mostly full)
        score += 25.0 - fragmentation * 40.0 + progress * 5.0;
        if post_residual == bin_capacity && next_item_size > 0 && next_item_size > mean_residual as u32 {
            score -= 10.0;
        }
    }

    // Integer-division threshold on post_residual: residuals < 10 are near-dead
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }
    // Decade-band coupling: bins whose residual is in the same decade as item size fit harmonically
    if (bin_residual / 10) == (item_size / 10) {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) are pure waste.
    // Penalize post_residual that falls below common item sizes (unusable slivers).
    let pr = post_residual as f64;
    if pr > 0.0 {
        // Small unusable gaps are heavily penalized (dead space).
        if pr < 10.0 {
            score += 60.0 * (10.0 - pr) / 10.0;
        } else if pr < 25.0 {
            // Moderately awkward gap: only fits very small items.
            score += 15.0 * (25.0 - pr) / 25.0;
        } else if pr < 50.0 {
            score += 4.0;
        } else {
            // Large residual is reusable; mild reward to prefer keeping big gaps.
            score -= 3.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 12.0 * (fill_ratio - 0.85) / 0.15;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if pr >= 0.0 && pr < 10.0 && fill_ratio > 0.5 {
            score -= 10.0; // even a dead-space fit beats a new bin here
        }
    }

    // New-bin candidate: penalize opening a new bin, scaled by open bin pressure
    // and how well existing bins could absorb the item.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 8.0;
        let mut new_bin_score = 45.0 + 10.0 * pressure;
        // If the next item could combine with this one in a fresh bin, mild discount.
        if next_item_size > 0 && (next_item_size as u32 + item_size) <= bin_capacity {
            new_bin_score -= 8.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score += 5.0 * progress;
        score = score.max(new_bin_score);
    }

    // Prefer bins below mean residual (balance load toward fuller bins).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 4.0 * (mean_residual - resid_f) / bin_capacity as f64;
    }

    // Lookahead: if the next item exactly fits the post residual, reward strongly.
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= 30.0;
    } else if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - (pr - next_item_size as f64) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (waste minimization).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 100.0 + (5 - post_residual) as f64 * 10.0;
    } else if post_residual <= 10 {
        score -= 30.0 + (10 - post_residual) as f64 * 3.0;
    }

    // 2-step lookahead: exact match of post_residual with next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 400.0; // perfect chain: next item fills this bin exactly
        } else if diff <= 10.0 {
            score -= 80.0 - diff * 4.0;
        } else {
            // penalize leaving residuals that nothing useful can use
            score += diff * 0.5;
        }
        // If next item cannot fit here, leaving a huge residual is worse
        // relative to the stream's typical residual scale (mean_residual).
        if post < nxt && post > 0.0 {
            score += 40.0 + (nxt - post) * 0.3;
        }
    } else {
        // Last item: strongly prefer closing bins out.
        score -= 200.0;
    }

    // Compare against mean residual: bins tighter than average are more valuable.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        if post_f < mean_residual {
            score -= (mean_residual - post_f) * 0.6;
        } else {
            score += (post_f - mean_residual) * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - progress * 40.0;
        if fitting_bins_count > 0 {
            score += 100.0; // some open bin fits; opening new is wasteful
        }
        if next_item_size > 0 && (bin_capacity as f64 - post_residual as f64).abs() < 1.0 {
            // still allow fresh bin for perfect future chains
            score -= 60.0;
        }
    }

    // Slight preference for fuller bins as stream progresses.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: penalize leaving residual the next item can't use,
    // but reward leaving residual exactly matching the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3; // leftover beyond what next item needs is dead space
            score -= 6.0; // bonus: next item can be chained into this bin
        } else {
            // post_residual too small for next item: dead space unless tiny
            let waste = post_residual as f64;
            score += waste * (0.5 + 0.5 * t);
        }
    }

    // Last-chance bonus: if this is the only open bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: opening a new bin costs ~half a bin on average.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if existing fits are very poor (huge post_residual among all fits),
        // this penalty is the baseline comparison anyway.
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        score -= 10.0 * (1.0 - t);
    }

    // Global state coupling: prefer bins with residual far below the mean
    // (concentrate fills, keep fresher bins available).
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.2;

    // Mild reward for very tight fits (best-fit core), scaled by fullness.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 5.0;

    // Penalize creating unusable slivers (< 10, minimum item size).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate slack; late, penalize it more aggressively
    let progress_weight = 0.6 + 1.4 * progress * progress;
    score += 30.0 * progress_weight * norm_pr * norm_pr;

    // Reward near-perfect fits more strongly as stream advances
    let fit_quality = 1.0 - norm_pr;
    score -= 12.0 * fit_quality * fit_quality * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth gate)
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0) / cap;
        score += 25.0 * waste * waste;
    } else {
        // last item: strongly prefer tightest fit
        score += 20.0 * norm_pr;
    }

    // Last-chance bin bonus (avoid opening new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * fit_quality;
    }

    // Mild penalty for spreading across many bins vs consolidation
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it available but not dominant unless current
    // bins are poor fits
    if bin_residual == bin_capacity {
        score = pr + 10.0 + 20.0 * (1.0 - fit_quality) - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead space penalty: small residuals (< 10) are unusable since items >= 1... but
    // tiny residuals relative to typical item sizes are wasted capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Penalize residuals that no item can usefully fill: residual < next_item_size
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0 * (1.0 - post_residual as f64 / cap);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item: chain-fit bonus.
        score -= 15.0;
        // Extra reward if post_residual - next_item_size is also small (tight chaining).
        let chain_left = post_residual - next_item_size;
        score -= (10.0 * (1.0 - chain_left as f64 / cap)).max(0.0);
    }

    // Harmonic classes: post_residual divisible by common item sizes (10, 20, 25, 50)
    // leaves reusable chunks.
    for m in [10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 4.0;
            break;
        }
    }

    // Integer-division threshold: penalize residuals in awkward bands.
    let band = post_residual / 10; // which decade band the residual lies in
    match band {
        0 => score += 20.0,             // 0..9: nearly dead space
        1 => score += 8.0,              // 10..19: awkward
        2 | 3 => score -= 2.0,          // 20..39: decent
        4 | 5 => score -= 5.0,          // 40..59: good
        _ => {}                          // large residual: neutral
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits (already via post_residual).
        score += 1.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: prefer opening a new bin only when open bins would leave
    // large dead space or late in the stream with many bins open.
    if bin_residual == bin_capacity {
        // Base score equals post_residual = capacity - item_size already.
        let early = progress < 0.2;
        if early {
            score += 5.0; // early stream: consolidate into open bins
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can chain the next item too
        }
    } else {
        // Prefer bins below mean residual (tighter than average).
        if pr < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0 * (pr - mean_residual) / cap;
        }
    }

    // Mild stream-progress modulation: later, be greedier about tight fits.
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits
    score -= (post_residual == 0) as i32 as f64 * 100.0;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure
        score += 20.0 + pressure * 5.0;
        // But if next item is large and no open bin could take both, new bin is fine
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 30.0;
        }
    } else {
        // Reward using existing bins more when many are open
        score -= pressure.min(10.0);
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize leaving a gap that exactly blocks the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Slight progression bias: later in stream, consolidate more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight convex penalty
    // so that leaving a large hole is disproportionately bad.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect follow-up: the next item exactly fills the remaining space.
        let match_gap = (post_residual as f64 - nxt).abs();
        // Reward proximity of post_residual to next_item_size.
        score -= 12.0 * (1.0 - match_gap / (bin_capacity as f64)).max(0.0);
        // Exact match gets an extra bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
        // If the next item cannot fit here but could fit a tighter residual,
        // penalize leaving residual that is "wasted" relative to the lookahead.
        if post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
        // If next item fits comfortably with room to spare after it too,
        // mildly reward (chain potential).
        if post_residual >= next_item_size {
            let chain_residual = post_residual as f64 - nxt;
            score -= 4.0 * (1.0 - chain_residual / (bin_capacity as f64)).max(0.0);
        }
    } else {
        // Last item: purely minimize post_residual.
        score -= 8.0;
    }

    // --- Mean residual coupling ---
    // Bins whose residual deviates strongly from the mean are less "flexible";
    // prefer bins with residual close to mean (keep the fleet balanced),
    // but only mildly, so tight fits still dominate.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 2.0 * dev / (bin_capacity as f64);

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless the fit is terrible). ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item fits poorly everywhere
        // (post_residual would be huge in any existing bin) or when open bins
        // are already quite full on average.
        let poor_fit_penalty = if post_residual > 40 { 0.0 } else { 18.0 + (40 - post_residual) as f64 };
        score += poor_fit_penalty;
        // Slight preference to consolidate when few bins are open.
        score -= 3.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, avoid opening new bins for small leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic penalty on wasted space.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac * bin_capacity as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current fit is terrible
    // and the next item could combine with the fresh residual.
    if bin_residual == bin_capacity {
        let base_penalty = 30.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        score += base_penalty;
        // If this item leaves a residual that exactly fits the lookahead item, favor new bin.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual as f64 <= mean_residual + 10.0 {
            score -= 35.0;
        }
        // If the item is huge relative to typical residuals, new bin is natural.
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: penalize placing here if the leftover cannot host the next item,
    // reward if it can (keeps bins chainable).
    if next_item_size > 0 && bin_residual != bin_capacity {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 5.0;
        }
    }

    // Dead-space penalty: residuals too small for the minimum item size are worthless.
    if post_residual > 0 && post_residual < 1 {
        score += 50.0;
    }

    // Time-horizon modulation: early in the stream, be conservative (keep bins flexible);
    // late in the stream, prioritize closing bins out tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - waste_frac);
    score += 8.0 * (1.0 - progress) * waste_frac;

    // Prefer bins whose residual is close to the mean (balanced state) mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with more room when many bins are open.
    score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear penalty on wasted space, quadratic in normalized residual
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr;

    // Tight fits rewarded strongly (smooth cubic falloff)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio * fit_ratio;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead coupling: reward leaving space the next item can use
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let slack = pr - ni;
        if slack >= 0.0 {
            score -= 3.0 * (1.0 - slack / cap);
        } else {
            score += 2.0 * (-slack / cap);
        }
    }

    // Stream-progress coupling: late in stream, prefer filling bins tighter
    score -= 5.0 * progress * (1.0 - norm_pr);

    // Penalize bins far below mean residual (fragmentation avoidance)
    score += 0.05 * (mean_residual - pr).abs();

    // Mild pressure against spreading across many bins when residual is large
    score += 0.02 * (open_bins_count as f64) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes capture "reusable" gaps
    let post = post_residual as i64;
    let class = post % 10;

    // Reward residuals in friendly classes (multiples of 5 or 10 are easier to fill)
    if class == 0 {
        score -= 12.0;
    } else if class == 5 {
        score -= 6.0;
    } else if class == 1 || class == 9 {
        score += 4.0; // awkward near-full gaps
    }

    // Integer-division thresholds: dead space that can't fit the smallest item (1..100 range, min ~1)
    if post_residual < 10 {
        score += 18.0; // unusable dead space
    } else if post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual as u32 {
            score -= 40.0;
        } else if next_item_size < post_residual as u32 {
            let gap = (post_residual - next_item_size) as i64;
            if gap % 10 == 0 {
                score -= 15.0;
            } else if gap < 10 {
                score += 8.0; // creates tiny dead space
            }
        } else {
            score += 10.0; // next item won't fit here
        }
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tight fits: relative fill ratio
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * 20.0;

    // New-bin candidate handling: keep it attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // open new bin if existing residuals are small/highly fragmented
        score = 30.0 + fragmentation * 60.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across many bins when residuals are healthy
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable
    // later (items are >= 10 typically), so penalize them heavily.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 11.0);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins early,
    // but allow new bins when the stream is young.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.5 * (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins below mean residual (denser bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when this bin would leave a tiny
    // dead gap and there are plenty of open bins already.
    if bin_residual == bin_capacity {
        let dead_gap_penalty = if post_residual <= 10 { 70.0 } else { 0.0 };
        score += 15.0 + dead_gap_penalty - 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; reward small post_residual non-linearly.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if the NEXT item exactly or nearly
    // fills the post residual (perfect chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            // Perfect match: next item exactly consumes leftover space.
            score -= 60.0;
        } else if nxt <= pr {
            // Next item fits inside this bin's leftover: partial reward,
            // scaled by how snugly it fits.
            let snug = 1.0 - diff / cap;
            score -= 25.0 * snug * snug;
        } else {
            // Next item cannot use the leftover; leftover likely dead space.
            // Penalize more if the gap to the next item is small (wasted potential).
            let gap = diff;
            score += 8.0 * (1.0 - (gap / cap).min(1.0));
        }
        // If post residual is smaller than next item but tiny, it's fine.
        if pr < nxt && pr <= 10.0 {
            score -= 10.0;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 15.0 * tightness;
    }

    // Compare against mean residual across open bins: placing into a bin with
    // residual well below mean concentrates packing (good), above mean spreads waste.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 6.0 * (mean_residual - res) / cap;
    } else {
        score += 4.0 * (res - mean_residual) / cap;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when nothing else fits well
    // or the stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 25.0; // there is a last-chance bin: prefer it
        } else {
            // Multiple options: new bin only mildly attractive early on.
            score += 10.0 + 20.0 * progress;
        }
        // Slight preference to open bins when very few are open (parallelism).
        if open_bins_count < 3 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Penalize dead space that cannot fit the typical next item
    if next_item_size > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        } else {
            score -= 2.0; // bin remains reusable for the lookahead item
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current bin fits are poor
    if bin_residual == bin_capacity {
        score += 20.0;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // fresh bin useful for large follow-up items
        }
    }

    // Time horizon: early on, prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Penalize spreading across many open bins when residuals are high
    let mean_res_norm = mean_residual / bin_capacity as f64;
    score += open_bins_count as f64 * 0.4 * mean_res_norm;

    // Prefer bins whose residual deviates favorably from mean (fill laggard bins)
    let dev = bin_residual as f64 - mean_residual;
    score -= dev * 0.05;

    // Small bonus for placing large items (hard to place later)
    score -= (item_size as f64 / 100.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr_norm = post / cap;

    // Base: prefer small post-residual (tight fit), smoothed non-linearly
    let mut score = post * (1.0 + 0.5 * pr_norm * pr_norm);

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate leftover space (keep bins flexible); late, demand tight fits.
    let coupling = pr_norm * (1.0 - pr_norm);
    score += 40.0 * coupling * (1.0 - progress) * (1.0 - progress);
    score -= 25.0 * coupling * progress * progress;

    // Penalize post-residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste = (next_item_size as f64 - post) / cap;
        score += 30.0 * waste * waste * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    }

    // Reward using the last fitting bin (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mild penalty for spreading across many open bins early in the stream
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Prefer bins whose residual is close to the mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * progress;

    // Slight bias toward larger items filling bins now
    score -= 0.05 * item_size as f64;

    // New-bin candidate: neutral baseline, only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 4.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item
    // granularities are more reusable, reward them.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 2.0; }
        if pr % 25 == 0 { score -= 2.0; }
    } else {
        // Perfect fit is ideal.
        score -= 40.0;
    }

    // Dead-space penalty: small, odd residuals are hard to fill.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 1.5;
        if pr % 2 == 1 { score += 2.0; }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && next_item_size == pr {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // Next item still fits: mild reward scaled by leftover after next.
        let pr2 = pr - next_item_size;
        score -= 4.0;
        if pr2 % 10 == 0 { score -= 3.0; }
    } else if next_item_size > pr {
        // This bin becomes dead after this placement; penalize by dead size.
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Last-chance bin: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and current residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let mut new_score = 8.0
            + fragmentation * 0.2
            + open_bins_count as f64 * 0.5;
        // Large items deserve fresh bins; small items should reuse space.
        if item_size >= 60 { new_score -= 10.0; }
        if item_size <= 30 { new_score += 6.0; }
        // Early in stream, be frugal; late, allow fresh bins.
        new_score -= progress * 4.0;
        score = new_score;
    }

    // Slight preference for bins with residuals near the item's harmonic
    // class (integer division threshold on residual / item size).
    if item_size > 0 {
        let ratio = bin_residual / item_size;
        if ratio == 1 { score -= 3.0; }
        else if ratio == 2 { score -= 1.5; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (size 1) are never fully wasted, but small gaps below the typical item
    // scale are hard to reuse — penalize them nonlinearly.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward tight fits: filling most of the bin is excellent.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward keeping
    // this bin alive; otherwise penalize leaving a gap that the next item
    // cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading out; opening new bins is penalized implicitly by
    // favoring bins with low residuals.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += (post_residual as f64) * pressure * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.2;
    }

    // Mean-residual coupling: if this bin's post residual deviates far below
    // the mean, it's a well-used bin; reward that.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.15;

    // Slight stream-progression tilt: late in the stream, consolidation
    // matters more (fewer wasted bins at the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64) * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual already favored).

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect chain: post_residual exactly equals next item -> near-zero waste over two steps.
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 30.0 + 0.5 * next_item_size as f64 - 0.3 * chain_waste;
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportional to how far off we are.
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.4 * gap;
    }

    // Relative-to-mean coupling: bins tighter than the mean are valuable, keep them packed.
    let rel = post_residual as f64 - mean_residual;
    score += 0.25 * rel;

    // Last-chance bin: if this is the ONLY bin that fits, avoid forcing a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is wasteful early/often; make it costly unless
    // the current item leaves a very clean residual for the future.
    if bin_residual == bin_capacity {
        let clean = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += 40.0 - 35.0 * clean + 0.1 * open_bins_count as f64;
    }

    // Penalize creating unusable dead space (residual too small for the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Mild stream-progression term: late in stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: relative fill of the bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 6.0 * t;
    }

    // Penalize bins that are much emptier than average (scatter waste),
    // unless it is the new-bin candidate itself.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += 0.05 * dev;
        } else {
            score -= 0.03 * (-dev);
        }
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement; if post-residual is too small for the next item,
    // penalize leaving awkward slivers.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_tight = (post_residual - next_item_size) as f64;
            score -= (10.0 * (1.0 - pair_tight / bin_capacity as f64)).max(0.0);
        } else if post_residual > 0 && post_residual < 10 {
            // unusable sliver for typical items
            score += 4.0;
        }
    }

    // New-bin candidate: prefer existing bins unless nothing fits well.
    // Penalize opening a new bin more when many bins are already open
    // and the stream is early (future items may fill existing bins).
    if is_new_bin {
        score += 14.0 + 0.8 * open_bins_count as f64 + 10.0 * (1.0 - t);
        // If the item fits almost perfectly in a fresh bin, soften the penalty
        let waste = (bin_capacity - item_size) as f64;
        score -= (waste / bin_capacity as f64) * 10.0;
    }

    // Slight bonus for filling bins completely over time (bin closing pressure)
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 5 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let res = bin_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;

    // Tight-fit reward: quadratic decay of post_residual, stronger as stream progresses.
    let tight = (post_residual as f64 / cap).powi(2);
    score -= 30.0 * (1.0 - tight) * (0.4 + 0.6 * progress);

    // Penalize small unusable post_residual that can't fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - (post_residual as f64) / (next_item_size as f64)) * (0.5 + 0.5 * progress);
    }

    // Reward if next item fits in the post-residual (chaining bonus).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = 1.0 - (post_residual - next_item_size as u32) as f64 / cap;
        score -= 10.0 * chain * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - tight);
    }

    // New-bin candidate: penalize mildly, more bins already open and early stream -> prefer filling.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.5 * open_bins_count as f64 * (1.0 - progress);
        // But allow new bin when item is huge and no open bin fits well.
        if item / cap > 0.6 && fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Smooth coupling with mean residual: prefer bins below mean residual (denser bins).
    score += 0.15 * (res - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual modulo capacity fractions.
    let pr = post_residual;
    let class_quarter = pr % (bin_capacity / 4);      // 0..24
    let class_fifth = pr % (bin_capacity / 5);       // 0..19
    let harmonic_bucket = pr / (bin_capacity / 10);  // integer division into 10-capacity buckets

    // Penalize leftovers that are "dead" (too small for typical items).
    if pr > 0 && pr < 10 {
        score += 60.0 - pr as f64 * 4.0;
    }

    // Reward leftovers in harmonic classes that pair well with common item sizes (mod arithmetic).
    let pairable = (pr % 10 == 0) as f64 * 18.0
        + (pr % 5 == 0) as f64 * 8.0
        + (pr % 25 == 0) as f64 * 12.0;
    score -= pairable;

    // Non-linear coupling: leftover class vs. lookahead item size.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead fits exactly in this bin's future residual -> strong reward.
            let exact = (next_item_size == pr) as f64 * 30.0;
            score -= 12.0 + exact;
            // Harmonic alignment: leftover and next item share a divisor class.
            if pr % gcd_like(next_item_size, bin_capacity) == 0 {
                score -= 6.0;
            }
        } else {
            // Lookahead cannot use this residual: penalize proportionally to wasted class.
            let waste = (next_item_size - pr).min(bin_capacity) as f64;
            score += waste * 0.35;
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 20.0 + 30.0 * fit_ratio;
        if fit_ratio > 0.7 {
            score -= 15.0;
        }
    }

    // Penalize spreading across many bins when residuals are large on average.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 30.0 && bin_residual as f64 > mean_residual {
        score += 8.0 * (1.0 - progress); // early stream: discourage hoarding large residuals
    }

    // Harmonic bucket shaping: mid-range buckets (usable leftovers) get mild reward.
    let bucket_f = harmonic_bucket as f64;
    score -= (bucket_f * (10.0 - bucket_f)).max(0.0) * 0.15;

    // Quarter/fifth class interplay: leftovers near class boundaries are awkward.
    if class_quarter <= 2 && pr >= bin_capacity / 4 {
        score += 5.0;
    }
    if class_fifth == 0 && pr > 0 {
        score -= 4.0;
    }

    // Slight preference to fill nearly-full bins (small residual) regardless.
    score -= (bin_residual as f64).ln().max(0.0) * 2.0;

    score
}

// Small helper-style inline gcd via subtraction on u32 (no imports).
fn gcd_like(a: u32, b: u32) -> u32 {
    let mut x = a;
    let mut y = b;
    while y != 0 {
        let t = y;
        y = x % y;
        x = t;
    }
    if x == 0 { 1 } else { x }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful are heavily penalized (they become unusable gaps).
    // Define a "dead zone" threshold relative to capacity.
    let dead_zone = cap * 0.10; // residuals <= 10 are nearly worthless
    if post_residual > 0 && (post_residual as f64) <= dead_zone {
        score += (dead_zone - post) * 6.0; // steep penalty inside the dead zone
    }

    // Perfect fit reward: subtract aggressively for near-zero post residual.
    if post_residual == 0 {
        score -= cap * 2.0;
    } else {
        // Smooth tight-fit reward proportional to how small the gap is.
        score -= (cap - post) / cap * 5.0;
    }

    // Reward bins that can also accommodate the lookahead item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= cap * 1.5; // lookahead perfect fit: excellent chaining
        } else {
            score -= (slack as f64) / cap * 2.0;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot fit in the leftover: this gap risks becoming dead space.
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.25;
    }

    // Last-chance bin pressure: if this is the only bin that fits, prefer it
    // strongly over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 1.2;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate (residual == capacity) gets penalized via count.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin plus pressure.
        score += cap * 1.1 + pressure * 2.0;
        // But if the item is huge relative to mean residual space, opening
        // a fresh bin may be wiser: soften the penalty.
        if (item_size as f64) > mean_residual {
            score -= (item_size as f64 - mean_residual) * 0.8;
        }
    } else {
        // Fitting into an existing bin slightly rewarded under pressure.
        score -= pressure * 0.3;
        // Penalize bins far from mean residual (outliers waste capacity).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match for next item is excellent
        if post_residual == next_item_size {
            score -= 400.0;
        } else {
            // penalize proportional to mismatch, scaled by next item magnitude
            score += gap * 0.6 * (1.0 + next_item_size as f64 / 100.0);
        }
        // If next item can't fit anywhere else after this placement, mild penalty
        if post_residual < next_item_size && post_residual > 0 {
            score += 30.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize bins far below mean residual (wasteful large-bin usage for small items)
    let mean_r = mean_residual;
    if mean_r > 0.0 {
        let rel = (post_residual as f64 - mean_r) / mean_r;
        score += rel * 15.0;
    }

    // Penalize creating large dead space that nothing typical can use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    }

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 120.0;
        // cheaper to open new bin late in stream? no — early bins amortize more items
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 80.0 * progress;
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 60.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Penalize wasting a nearly-full bin on a small item.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 4.0 * (1.0 - fill) * (1.0 - fill);

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; leaving a large dead gap is worse.
            score += 0.05 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with below-average residual (keep big holes for big future items).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff;

    // Mild pressure against opening new bins mid-stream; more bins => prefer reusing.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 3.0 + 10.0 * progress + 0.15 * open_bins_count as f64;
        // But if nothing fits well anywhere, opening a fresh bin is fine (post_residual==0 already low).
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight reward for leaving residual that is "hard to use" (small odd gaps are dead anyway).
    if post_residual > 0 && post_residual < 10 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: squared residual (quadratic dead-space penalty)
    let mut score = norm_pr * norm_pr * cap;

    // Cubic coupling with stream progress: early on, tolerate slack; late, punish it harder
    let progress_coupling = norm_pr.powi(3) * (1.0 + 3.0 * progress);
    score += progress_coupling * cap;

    // Reward tight fits: subtract when post_residual is small relative to capacity
    let tightness = (1.0 - norm_pr).powi(4);
    score -= tightness * cap * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 2.0;
    } else if fitting_bins_count > 1 {
        // mild competition term: prefer bins where alternatives exist but fit is good
        score += tightness * cap * 0.1 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // Lookahead synergy: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            let gap_norm = gap / cap;
            score -= (1.0 - gap_norm).powi(3) * cap * 1.5;
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            let over = (nxt - pr) / cap;
            score += over * cap * 0.3;
        }
    }

    // Mean residual interaction: if this bin's residual deviates favorably from mean, adjust
    let mean_dev = (pr - mean_residual) / cap;
    score += mean_dev * cap * (0.2 + 0.5 * progress);

    // Crowding: many open bins -> prefer filling existing ones over opening new
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless residual landscape is bad
        let crowding = open_bins_count as f64;
        score += cap * (1.5 + 0.05 * crowding) - tightness * cap * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill and "nice" residuals get bonuses.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, always take
    } else {
        // Modulo classes: residuals divisible by common small sizes stay usable.
        let usable_mod = (pr % 10 == 0) as f64 * 30.0
            + (pr % 5 == 0) as f64 * 12.0
            + (pr % 2 == 0) as f64 * 5.0;
        score -= usable_mod;

        // Dead-space penalty for tiny unusable residuals.
        if pr < 10 {
            score += 60.0;
        } else if pr < 20 {
            score += 25.0;
        }

        // Lookahead coupling: does next item fit into post_residual?
        if next_item_size > 0 {
            if next_item_size <= pr {
                score -= 80.0; // chain two items: excellent
                // integer-division threshold: leftover after chaining
                let chained_left = pr - next_item_size;
                if chained_left == 0 {
                    score -= 150.0;
                } else if chained_left < 10 {
                    score += 20.0; // chain leaves dead space
                }
            } else {
                score += 15.0; // next item won't fit here anyway
            }
        } else {
            // last item: minimize waste aggressively
            score -= 40.0;
        }
    }

    // Fractional fill level of this bin.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill * 50.0; // prefer fuller bins

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // residuals are all poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when justified.
        score += 90.0;
        // If many bins fit the item, opening new is wasteful.
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 25.0;
        }
        // Early in stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
        // If mean residual is large, existing bins have room: penalize new bin.
        score += mean_residual * 0.5;
        // But if next item is huge and nothing fits, a fresh bin is fine.
        if next_item_size > 50 && fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mild preference to spread load when many bins are open and residuals tight.
    if open_bins_count > 3 && mean_residual < 15.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals too small for the smallest item (1..10) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Tight fit reward: residual barely above the item.
    let tightness = (bin_residual - item_size) as f64;
    if tightness == 0.0 {
        score -= 50.0;
    } else if tightness <= 10.0 {
        score -= 20.0;
    }

    // If next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // If next item fits but would leave dead space, mild penalty.
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size < 10 {
        score += 15.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 + progress) * 0.5;

    // New-bin candidate: only attractive when item leaves a big usable residual
    // and open bins are scarce.
    if bin_residual == bin_capacity {
        score -= 30.0 - open_bins_count as f64 * 2.0;
        if post_residual < 10 {
            score += 80.0;
        }
    }

    // Prefer bins with below-mean residual (closable bins) to consolidate.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item still fits tightly after placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize leaving post_residual too small for anything useful (dead space),
    // especially when it cannot fit the lookahead item.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        if post_residual < 10 {
            score += 25.0; // tiny unusable sliver
        } else {
            score += 8.0 * (1.0 - post_residual as f64 / 100.0);
        }
    }

    // Exact-fill bonus: bin becomes perfectly closed.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Tightness reward: placing item into a snug residual relative to mean.
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Prefer filling bins whose residual is below mean (compact bins first),
    // keeping large-residual bins flexible for bigger future items.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate penalty: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host current + lookahead pair
        }
    }

    // Late-stream urgency: close bins out as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio within the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Core waste penalty: squared residual discourages leaving large unusable gaps ----
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // ---- Lookahead coupling: penalize bins whose post-residual cannot host the next item ----
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space relative to the upcoming item.
            let gap = (next_item_size - post_residual) as f64;
            score += 1.5 * gap;
            // Extra penalty if the gap is small-but-unusable (worst kind of fragmentation).
            if gap < 10.0 {
                score += 6.0 * (10.0 - gap);
            }
        } else {
            // Reward a perfect chain fit: this bin can absorb the next item too.
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else {
        // Last item in the stream: strongly prefer tightest fit (minimize final residual).
        score += 3.0 * post_residual as f64;
    }

    // ---- Last-chance bonus: if this is the ONLY bin that fits, strongly favor using it ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * post_residual as f64;
    }

    // ---- Scarcity pressure: many open bins with low mean residual -> prefer filling existing bins ----
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        // Low mean residual (bins nearly full) => opening new bins is attractive; penalize this bin less.
        score -= (1.0 - pressure) * 4.0;
    }

    // ---- Time-horizon modulation: early in the stream, be picky about tight fits; ----
    // ---- late in the stream, prioritize consolidation into open bins.            ----
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= progress * 8.0 * tightness;
    score += (1.0 - progress) * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // ---- New-bin candidate handling: brand-new empty bin gets a calibrated default ----
    if bin_residual == bin_capacity {
        // Attractive early (plenty of stream left) or when no bin fits well;
        // unattractive when existing bins are nearly full and can absorb the item.
        let mut new_bin_score = 55.0;
        new_bin_score += progress * 20.0; // later => less willing to open new bins
        if open_bins_count == 0 {
            new_bin_score -= 60.0; // must open the first bin
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 40.0; // nothing else fits
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Room for the next item in a fresh bin: mild bonus.
            new_bin_score -= 5.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 8.0 * norm_pr * norm_pr * (0.5 + p2) * cap;
    score -= 14.0 * fit_norm * (1.0 - p3) * cap;

    // Dead-space penalty: small residuals are wasteful late in the stream
    let tiny = (norm_pr * 10.0).min(1.0);
    score += 20.0 * tiny * tiny * (0.3 + 0.7 * p2);

    // Reward tight fits
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item can use the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Slight penalty when many bins are open (encourage consolidation)
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Mean residual alignment: prefer bins near the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless item is large
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * fit_norm + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer division thresholds on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Tightness reward: fractional fill of the bin by this item.
    let fill = item / cap;
    score -= 22.0 * fill;

    // Dead-space penalty: post_residual in the "useless" harmonic class
    // (small but not tiny leftovers, e.g. 1..=9) are hard to reuse.
    if post_residual >= 1 && post_residual <= 9 {
        score += 18.0;
    }
    // Class 10..=19: moderately reusable, mild penalty scaled by scarcity
    // of alternative bins.
    if post_residual >= 10 && post_residual <= 19 {
        score += 4.0 * (1.0 - (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0)));
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual, this placement is excellent.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let leftover2 = post_residual - next_item_size;
            // Reward proportional to how compact the two-item packing is.
            score -= 12.0 * (1.0 - leftover2 as f64 / cap);
            if leftover2 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item cannot use this residual; penalize large leftovers
            // in bins that won't be revisited usefully.
            let waste = post_residual as f64;
            score += 0.05 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual
    // of all open bins; make the empty-bin candidate less attractive unless
    // open bins are nearly full (small mean residual) or item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 0.9 * cap
            + mean_residual * 0.6
            + (open_bins_count as f64) * 0.8
            - 15.0 * fill
            - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0; // next item would need a new bin anyway
        }
        if item_size >= 80 {
            score -= 25.0; // big items pair poorly with existing residuals
        }
    }

    // Mean-residual coupling: when open bins are collectively empty-ish,
    // discourage spreading items across many bins (prefer filling one).
    if bin_residual != bin_capacity {
        score += 0.15 * (mean_residual - post).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    // Penalize post_residuals that are too small to be useful for any future item
    // (assume minimum useful item size ~10), but reward moderately large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space: unusable gap
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0; // marginal gap: only fits very small items
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else {
        // larger residuals are valuable; slight reward scaled by size
        score -= (post_residual as f64 - 20.0) * 0.3;
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Open bins pressure: discourage spreading across many bins,
    // but soften near the end of the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 - 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; prefer placing into below-mean-residual bins.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - res) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin is a safe fallback; make it
    // moderately attractive so we avoid stuffing items into bad gaps, but
    // not so attractive that we always open new bins.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progression through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward exact/near match between post_residual and next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff < 0.5 {
            // Perfect chain: post_residual exactly fits the next item
            score -= 60.0;
        } else if pr >= nxt && pr - nxt <= 10.0 {
            // Near-perfect chain
            score -= 40.0 * (1.0 - (pr - nxt) / 10.0);
        } else if pr < nxt {
            // Next item won't fit here anyway; penalize proportionally to wasted space
            score += 0.5 * (nxt - pr).min(80.0);
        } else {
            // Next item fits but leaves slack; mild penalty on the gap
            score += 0.3 * (pr - nxt - 10.0).max(0.0);
        }
        // Extra bonus if the chain leaves a residual matching typical small items
        if pr >= nxt && (pr - nxt) <= 20.0 {
            score -= 10.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 20.0;
    }

    // --- Relative-to-mean-residual coupling ---
    // Bins with residual well below mean are "tight" — favor filling them further.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res_f - mean_residual;
        score += 0.4 * rel; // penalize bins looser than average
        if rel < -5.0 {
            score -= 8.0; // reward tighter-than-average bins
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, emphasize tightness more
        score += 0.2 * post_residual as f64;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost, offset slightly early in the stream
        score = bin_capacity as f64 - 15.0 * (1.0 - progress);
        // Never open a new bin if it's the only fitting option is irrelevant here;
        // but if many bins fit and this item is small, opening new is wasteful
        if fitting_bins_count > 0 && item_size <= 30 {
            score += 30.0;
        }
        // If next item is large and current item is large, new bin may be reasonable
        if next_item_size >= 60 && item_size >= 60 {
            score -= 10.0;
        }
    }

    // --- Waste penalty: dead space that nothing (min size 1..) can use ---
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // nearly-full bin is excellent
    }

    // Slight preference for high fill ratio
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post residual.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * (1.0 - tightness * tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead coupling: reward residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual useful for lookahead
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).min(30.0) / 30.0;
        } else {
            // residual too small for next item: penalize dead space
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize fragmenting a large residual when many bins are open.
    let frag = (post_residual as f64) / (bin_residual as f64);
    if bin_residual > 0 && bin_residual != bin_capacity {
        score += 5.0 * frag * (open_bins_count as f64).ln().max(1.0);
    }

    // Global pressure: if mean residual is low, conserve residual space.
    score += 3.0 * (mean_residual / bin_capacity as f64 - tightness);

    // Time horizon: early in stream, prefer opening fresh bins for poor fits;
    // late in stream, prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: attractive early, penalized late
        score -= 15.0 * (1.0 - progress);
        score += 20.0 * progress;
        // prefer new bin if this would be a very loose fit elsewhere
        if (post_residual as f64) > 0.5 * (item_size as f64) {
            score -= 10.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress:
    // early on, small residuals are fine (keep bins tight); later, penalize them more
    let progress_coupling = norm_pr * norm_pr * (0.5 + 2.0 * progress) + norm_pr * progress * progress;
    score += 60.0 * progress_coupling;

    // Reward near-perfect fits smoothly (bell-shaped around zero residual)
    let fit_quality = (-norm_pr * 8.0).exp();
    score -= 25.0 * fit_quality * (1.0 - progress * 0.5);

    // Lookahead: if next item fits the post-residual, strongly reward this bin
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 18.0 * (1.0 - slack) * (1.0 + 0.5 * progress);
    } else if next_item_size > 0 {
        // next item won't fit here; mildly penalize leaving residual that's unlikely used
        score += 6.0 * norm_pr * (1.0 - progress);
    }

    // Last-chance bin: penalize heavily if we would strand the only fitting bin
    if fitting_bins_count == 1 {
        score += 12.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (tighter bins) with smooth interaction
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: smooth sigmoid gate on residual == capacity
    let is_new = ((bin_residual as f64 - cap).abs() < 0.5) as f64;
    let open_pressure = 1.0 / (1.0 + (open_bins_count as f64 - 3.0).exp());
    score += is_new * (30.0 + 40.0 * open_pressure + 20.0 * progress);

    // Mildly discourage spreading across many bins early
    score += 0.5 * open_bins_count as f64 * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: residuals divisible by common item granularities
    // are more reusable, so reward them (subtract).
    for m in [10u32, 20, 25, 50].iter() {
        if post_residual % m == 0 && post_residual > 0 {
            score -= 4.0 + (m as f64) * 0.2;
        }
    }

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tiny dead space is bad: penalize residuals in (0, 10) — unusable for min item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 500.0;
        } else {
            score -= 0.5 * (next_item_size as f64);
        }
    }
    // If next item cannot fit in post_residual but could fit elsewhere, mild penalty
    // for leaving a bin that strands the lookahead.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits this item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Fraction-of-capacity harmonic thresholds on post_residual:
    // residuals near quarter/half capacity are "healthy" bins.
    let frac = post_residual as f64 / cap;
    if (frac - 0.25).abs() < 0.05 || (frac - 0.5).abs() < 0.05 {
        score -= 6.0;
    }

    // Prefer tighter bins generally: deviation from mean residual.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when nothing fits well
    // (large item relative to mean residual, or few fitting bins).
    if bin_residual == bin_capacity {
        let tight = mean_residual < item_size as f64 * 0.5;
        let crowded = fitting_bins_count == 0 || (fitting_bins_count == 1 && item_size > 50);
        if tight || crowded {
            score -= 150.0;
        } else {
            score += 50.0; // keep using open bins when they're roomy
        }
    }

    // Late in the stream: consolidate harder, penalize opening slack.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let gap = post_residual;
    if gap > 0 && gap < 10 {
        // Gap too small for any item (min size 1..100 unknown, but tiny gaps waste space)
        score += (10.0 - gap as f64) * 8.0;
    } else if gap >= 10 && gap < 25 {
        // Moderately small gap: mild penalty scaled by gap smallness
        score += (25.0 - gap as f64) * 1.5;
    } else if gap == 0 {
        // Perfect fit: strong reward
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == gap {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= gap && gap - next_item_size < 10 {
        // next item would leave a dead gap here: penalize
        score += (10.0 - (gap - next_item_size) as f64) * 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: many open bins -> favor filling existing ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin; prefer filling it
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.5;
    } else {
        score += (-dev) * 0.1;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many bins already open and item is large
        let mut new_bin_cost = 25.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0; // no alternative
        } else if fitting_bins_count == 1 {
            new_bin_cost += 30.0; // an open bin is a last chance; prefer it
        }
        if next_item_size > 0 && next_item_size <= item_size {
            new_bin_cost -= 10.0; // large item may pair with next item
        }
        score = new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 20.0 * tightness * tightness;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves more waste: mild penalty proportional to slack
            let slack = (post_residual - next_item_size) as f64;
            score += 0.5 * slack;
        } else {
            // next item cannot fit this residual: penalize leftover dead space
            score += 0.3 * (post_residual as f64);
            // extra penalty if next item is large and residual is a small unusable gap
            if next_item_size >= 40 && post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Compare against mean residual: penalize bins far below mean residual usage
    // (bins with residual much larger than mean are "underused" -> good targets)
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res_f - mean_residual) / mean_residual;
        score -= 5.0 * dev;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well
    if bin_residual == bin_capacity {
        // neutral base for new bin; discourage unless existing fits are bad
        score += 50.0 + (post_residual as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * (1.0 - progress);
    }

    // Slight preference for many open bins fitting item (less risk)
    if fitting_bins_count > 1 {
        score -= 2.0 * (fitting_bins_count as f64).ln();
    }

    // Small noise-free tiebreaker by residual
    score += 0.01 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual relative to item size)
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 2.5 * tightness * (item_size as f64);

    // Penalize leaving dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small residual is fine, item almost fills bin
    } else if post_residual >= 10 && post_residual < 40 {
        // mid-range residual is usable by future items; mild penalty scaled by mean residual gap
        score += 0.15 * (post_residual as f64 - mean_residual).abs();
    } else if post_residual >= 40 {
        // large leftover: wasteful unless bin was huge
        score += 0.05 * (post_residual as f64 - 40.0);
    }

    // Lookahead: reward if the next item fits exactly into the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 0.03 * ((next_item_size - post_residual) as f64);
        }
    } else {
        // last item: strongly prefer filling an existing bin
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Time horizon: early in stream, be conservative about fragmenting bins;
    // late in stream, prefer closing bins out (fill tightly).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    // Many open bins: encourage consolidation into existing bins
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, reduced when stream is early or
        // existing bins are crowded / item is large with poor fits elsewhere
        let mut open_cost = 18.0;
        open_cost -= 8.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            open_cost -= 25.0; // no alternative
        }
        if item_size > 60 {
            open_cost -= 5.0; // big items deserve fresh space
        }
        // if mean residual across open bins is large, reusing is easy: penalize new bin
        open_cost += 0.08 * mean_residual;
        score += open_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 30.0 * progress);

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 15.0 * progress * (nxt - pr) / cap;
        } else {
            score -= 10.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many bins
    score += (open_bins_count as f64).ln() * 2.0;

    // New-bin candidate: prefer it early, discourage late
    if bin_residual == bin_capacity {
        score += 5.0 * progress - 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by integer division.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let harmonic_class = (post_residual / (bin_capacity / 8).max(1)) as f64; // 0..8 buckets

    // Reward tight fits: post_residual in low harmonic classes is good.
    score -= (8.0 - harmonic_class) * 3.0;

    // Penalize "dead space" residuals that are too small to ever be useful.
    // Residuals in (0, 10] are nearly dead; add a strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo-arithmetic coupling: residuals divisible by common item sizes (10, 20, 25, 50)
    // are reusable; reward them.
    for &m in &[10u32, 20, 25, 50] {
        if post_residual % m == 0 {
            score -= 6.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves a remainder; penalize by the leftover it creates.
            let next_left = post_residual - next_item_size;
            if next_left < 10 {
                score += 8.0; // creates dead space
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; mild penalty if this bin becomes stranded.
            if post_residual < 20 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: an empty bin should only win when it offers better long-run utility.
    if bin_residual == bin_capacity {
        // Base reluctance: keep item in an existing bin unless existing fits are bad.
        score += 12.0;
        // But if open bins have large fragmented mean residual (poor packing), a fresh
        // bin with clean harmonic structure is attractive.
        if mean_residual > cap * 0.5 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        // Large items deserve fresh bins to avoid fragmentation.
        if item_size >= bin_capacity / 2 {
            score -= 14.0;
        }
    }

    // Fraction-of-capacity coupling: prefer bins whose fill fraction is already high.
    let fill_frac = 1.0 - (bin_residual as f64) / cap;
    score -= fill_frac * 10.0;

    // Slight pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // Small item into a big residual wastes the bin; penalize by waste ratio.
    if post_residual > item_size as f64 * 2.0 {
        score += (post_residual - item_size as f64 * 2.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use
    // (post_residual in 1..10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward using bins that are already quite full (small bin_residual).
    let fullness = bin_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fullness) * 15.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item would fit exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize leaving a gap the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when existing bins are poor fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            // Make new bin slightly worse than a decent existing fit,
            // but better than bins with big dead-space risk.
            score += 12.0 + mean_residual * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this placement creates a perfect chain — strongly favor it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it nests.
            let nest = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - nest / (bin_capacity as f64));
        } else {
            // Next item cannot fit here: penalize leaving a gap just under
            // next_item_size (unusable dead space for the lookahead item).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 120.0 - 8.0 * gap;
            }
        }
    } else {
        // Last item: only the exact fill matters.
        if post_residual == 0 {
            score -= 500.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Compare against mean residual: placing into a bin with residual above
    // the mean keeps tighter bins available for future small items.
    if bin_residual as f64 > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.5;
    } else {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Penalize fragmenting many open bins when the item is large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if item_size >= 50 && open_bins_count > 3 {
        score += 20.0 * (open_bins_count as f64).ln() * (1.0 - progress);
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else if post_residual > 40 {
            score -= 50.0;
        } else {
            score += 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize residuals that become "dead space" (too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening bins is more acceptable early; late stream favors consolidation.
        let openness = 40.0 * (1.0 - progress);
        score += 15.0 + openness + 2.0 * open_bins_count as f64;
        // If item is large relative to mean residual, opening a fresh bin is more sensible.
        if (item_size as f64) > mean_residual {
            score -= 12.0;
        }
    }

    // Mild global pressure: many open bins -> prefer filling existing ones.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for bins below mean residual (balance utilization).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = post;

    // Smooth non-linear coupling of post_residual with stream progress:
    // later in the stream, tight packing (small post_residual) matters more.
    let progress_coupling = post * (1.0 + 1.5 * progress * progress);
    score += 0.35 * progress_coupling;

    // Quadratic penalty on wasted space relative to capacity, amplified by progress.
    let waste_frac = (post / cap).powi(2);
    score += 12.0 * waste_frac * (0.5 + progress);

    // Reward bins whose residual is nearly consumed (smooth exponential term).
    score -= 6.0 * (-(post / cap * 4.0)).exp();

    // Penalize the brand-new empty bin candidate smoothly, less so late in the stream.
    if bin_residual == bin_capacity {
        let open_scale = (open_bins_count as f64).ln().max(1.0);
        score += 8.0 * open_scale * (1.0 - 0.5 * progress);
    } else {
        // Last-chance bonus: if this is the only fitting bin, strongly favor it.
        if fitting_bins_count == 1 {
            score -= 10.0 * (1.0 + progress);
        }
        // Lookahead: reward leaving a gap that the next item can still use.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 2.5 * (1.0 - post / cap);
        }
        // Slight preference for bins tighter than the mean residual (smooth sigmoid).
        let diff = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * (diff / (1.0 + (diff * diff).sqrt()));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residuals near multiples of
    // common item sizes are more reusable. Penalize residuals in "dead" classes.
    let dead = |r: u32| -> f64 {
        // residuals 1..=9 are hard to fill (min item size 1, but small waste)
        // treat very small residuals as near-dead
        if r == 0 { 0.0 } else if r < 5 { 30.0 } else if r < 10 { 12.0 } else { 0.0 }
    };
    score += dead(post_residual);

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the next item fit the post-residual exactly?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 45.0; // chain of perfect fits
            } else {
                score -= 10.0;
                score += dead(slack);
            }
        } else {
            // next item won't fit here; mildly penalize wasting this bin's tail
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // placement in existing bins is poor. Give empty-bin candidate a baseline
    // score near its residual (capacity), with a mild penalty so existing
    // reasonable fits beat it.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 15.0 + dead(0.0);
        if next_item_size > 0 {
            // new bin leaves residual item_size; check lookahead chain
            if item_size >= next_item_size {
                score += 8.0;
            }
        }
        // late in the stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins whose residual deviates most from the mean
    // (reduce variance / consolidate slack)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.15 * dev;

    // Modulo-class bonus: residual congruent to 0 mod 10 is highly reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Many open bins: encourage tightening to limit bin count
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are dead space.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score -= 40.0 * (dead_threshold - post_residual as f64);
    }

    // Penalize small-but-not-dead gaps less harshly, but still avoid fragmenting.
    if post_residual > 0 && post_residual < item_size {
        score += 5.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward keeping this bin viable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        score += 4.0;
    }

    // Mild preference for bins tighter than the mean residual (compact packing).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight late-stream tightening: avoid leaving many half-empty bins at the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    // New-bin candidate: make it moderately expensive so it's chosen only when
    // open bins would create bad dead space.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively than linear.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tight * tight;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-fit bonus scaled by how snugly the next item would fit.
            let chain_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 18.0 + 12.0 * chain_tight;
        } else {
            // Penalize leaving a residual too small for the next item (dead space risk),
            // unless this bin is nearly full anyway.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Penalize opening a new bin when existing bins fit well, especially late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 + 60.0 * progress + 4.0 * open_bins_count as f64;
        // But if mean residual across open bins is tiny, a new bin is fine.
        score -= 30.0 * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    }

    // Mild penalty for placing into a bin whose residual is far above the item
    // (encourage using bins closest in size first, classic best-fit flavor).
    let slack = (bin_residual - item_size) as f64;
    score += 0.10 * slack;

    // Slight preference for consolidating when many bins are open.
    if bin_residual != bin_capacity {
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 + t * t) * (pr / cap) * (pr / cap) * cap * 0.5;
    score += poly;

    // Reward near-perfect fills smoothly
    score -= (1.0 - pr / cap).powi(6) * 12.0;

    // Penalize dead space relative to mean residual, weighted by progress
    score += (pr - mean_residual).abs() * (0.5 + t) * 0.3;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - t);
    }

    // Lookahead: favor bins whose post_residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * t;
    }

    // Slight penalty for spreading across many bins early
    score += (open_bins_count as f64).ln() * (1.0 - t) * 0.5;

    // Discourage opening new bins unless current fit is poor
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * (1.0 - pr / cap) * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo 10 classes
    let class = post_residual % 10;
    // Penalize residuals in "dead" classes (small primes-like leftovers)
    let dead_penalty = match class {
        0 => -6.0,   // perfect fill
        5 => -3.0,   // half-decade, still reusable by medium items
        1 | 2 | 3 => 4.0, // tiny unusable slivers
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division threshold: how many "typical" items (size ~ next_item_size) still fit
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            score -= 5.0; // reward leaving room for lookahead item
            let k = post_residual / next_item_size.max(1);
            score -= (k.min(4) as f64) * 1.5;
        } else {
            score += 3.0; // lookahead won't fit here
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Tight fit reward: fraction of capacity consumed
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill_frac * fill_frac;

    // New empty bin candidate: penalize unless open bins are crowded or fit is hopeless
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count == 0 { 0.0 }
            else { (mean_residual / bin_capacity as f64).max(0.0) };
        // open new bin when existing residuals are large (poor fits) or few fitting bins
        score += 12.0 - 10.0 * pressure;
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            score -= 6.0; // existing bins barely fit; new bin attractive
        }
    } else {
        // mild preference to keep bin count low
        score += (open_bins_count as f64).min(10.0) * 0.15;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Progress-scaled urgency: later in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small to fit even the smallest plausible item.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual as f64 >= dead_threshold {
        // Usable leftover: mildly reward proportional to how much fits later.
        score -= (post_residual as f64) * 0.15;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 8.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // discourage wasting a nearly-full bin's identity on a bad fit.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual != bin_capacity {
        score += pressure * 0.8;
    } else {
        // New-bin candidate: penalize opening a bin unless current fits are poor.
        score += 18.0 + pressure * 0.3;
        // If the next item is large and this bin would be opened fresh, slight relief.
        if next_item_size > 60 {
            score -= 5.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual is below average
    // (concentrate filling), i.e., penalize bins with excess residual.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.12;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap < dead_threshold {
            score -= 20.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Leftover unusable for the known next item: mild penalty.
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits too: mild reward proportional to how well it fits after.
            let rem2 = post_residual - next_item_size;
            score -= 50.0 * (1.0 - rem2 as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize leftover space.
            score += 0.5 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening new bins when decent fits exist.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.4 * (open_bins_count as f64);
    }

    // Late-stream consolidation: tighter packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit reward: strongly prefer placements that leave little waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically (unusable residuals are costly).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 4.0 * dead * dead * (bin_capacity as f64);
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
            // Extra reward if next item then fills the bin completely.
            if post_residual == next_item_size {
                score -= 6.0;
            }
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 2.5 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Many fitting bins: mild preference for the fullest bin (best-fit style),
    // approximated by low residual.
    if fitting_bins_count > 1 {
        score += 0.5 * (bin_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // current item is large or global residuals are already fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 8.0;
        // More attractive when existing bins have scattered small residuals.
        let frag = mean_residual / bin_capacity as f64;
        if frag < 0.25 {
            score -= 6.0 * (0.25 - frag);
        }
        // Attractive late in stream if item is big (would leave big dead space elsewhere).
        if item_size > 60 && post_residual < 40 {
            score -= 4.0;
        }
        // Early stream: prefer consolidating into few bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 * (1.0 - t);
        // Many open bins: discourage opening yet another unless item is huge.
        score += 0.3 * open_bins_count as f64;
        if item_size >= 80 {
            score -= 6.0;
        }
    }

    // Global fragmentation pressure: if mean residual is high, tighten selection.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Time horizon: as the stream progresses, waste matters more (fewer chances to recover).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty on using nearly-full bins for tiny items (save them for bigger items).
    if item_size <= 20 && bin_residual >= 60 && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: quadratic penalty on post_residual (waste grows superlinearly)
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling: waste penalty modulated by stream progress
    // (early on, tolerate spread; later, be ruthless about waste)
    score += pr * (0.5 + 1.5 * progress * progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - pr / (bin_residual.max(1) as f64);
    score -= tightness * tightness * item_size as f64 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / cap);
        } else {
            score += 4.0 * (pr / cap);
        }
    }

    // Align with global mean residual: prefer bins near the mean (keeps bin profile uniform)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: opening a bin should be discouraged unless this item
    // is large and would leave bad fits in existing bins.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Large items pair well with future items in a fresh bin; small items should reuse
        score = 10.0 + 40.0 * (1.0 - frac) * (1.0 - frac) - 15.0 * frac * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes (mod capacity fractions)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals in "unusable" classes: too small for typical items (1..100)
    // Residual < 10 is dead space; residual in (0, min_item) wastes capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward exact fills (perfect packing)
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class via integer division: which capacity fraction band does post_residual fall in?
    // Bands: [0,25), [25,50), [50,75), [75,100]
    let band = post_residual / 25;
    match band {
        0 => score += 10.0,      // tiny residual: poor future usability
        1 => score += 3.0,       // quarter band
        2 => score += 0.0,       // half band: versatile
        _ => score -= 5.0,       // mostly empty: good
    }

    // Modulo coupling: does post_residual + next_item_size land near a capacity boundary?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Next item fits here: strong reward for keeping that option
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit: penalize proportionally to how much we waste
            score += 0.5 * nxt;
        }
        // Modulo harmonic: residual divisible by next item size is harmonious
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if all open bins are tight (low mean residual), a fresh bin is fine
        score -= 20.0 * (1.0 - mean_residual / cap).max(0.0);
    }

    // Tightness reward: the fuller the bin relative to capacity, the better
    score -= (1.0 - pr / cap) * 10.0;

    // Late-stream consolidation: prefer filling existing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / cap);

    // Many open bins: encourage closing them out by filling small residuals
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Dead-space penalty: residuals that are too small to fit any
    // future item are the worst outcome. Assume minimum item size ~1,
    // but treat gaps below a "useful threshold" as increasingly wasted.
    let dead_threshold = 12.0_f64;
    if (post_residual as f64) < dead_threshold {
        // Heavily penalize unusable slivers: the tighter (smaller) the gap,
        // the more dead space it represents.
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // --- Reward near-perfect fits (small but nonzero waste is fine,
    // zero waste is best).
    if post_residual == 0 {
        score -= 40.0; // perfect fill: bin closed, ideal
    } else if post_residual <= 5 {
        score -= 15.0; // excellent fit
    }

    // --- Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: strong bonus,
            // scaled by how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + 4.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 && (post_residual as f64) < next_item_size as f64 {
            // Gap exists but next item won't fit in it: mild penalty
            // proportional to the unusable fraction.
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // --- Open-bins pressure: when many bins are open, discourage
    // spreading; prefer filling existing bins (favor low residual bins
    // implicitly via post_residual, add explicit pressure against
    // opening new bins when open_bins_count is high).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.35 * (0.5 + progress);

    // --- New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Opening a new bin is only attractive when:
    //  * this bin is the last fitting bin (fitting_bins_count == 1) and the
    //    fit is terrible, or
    //  * the item would leave a large awkward gap relative to mean residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of consuming a fresh bin.
        score += 25.0 + open_bins_count as f64 * 1.5;
        // But if this item is a poor fit everywhere (last chance bin with
        // big post residual), opening fresh is better than wasting space.
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        let last_chance = fitting_bins_count == 1 && !is_new_bin;
        if poor_fit && (last_chance || open_bins_count == 0) {
            score -= 35.0;
        }
        // Early in the stream, slightly prefer consolidating into few bins.
        if progress < 0.2 {
            score += 10.0 * (0.2 - progress);
        }
    } else if fitting_bins_count == 1 {
        // This open bin is the ONLY bin that can take the item: strong
        // preference to use it rather than open a new bin.
        score -= 12.0;
    }

    // --- Mean-residual coupling: if this bin's post placement residual is
    // far below the current mean residual, it is consolidating space well.
    let residual_gap = mean_residual - post_residual as f64;
    if residual_gap > 0.0 {
        score -= 0.15 * residual_gap;
    } else {
        score += 0.10 * (-residual_gap);
    }

    // --- Prefer filling bins with lower pre-existing residual (tighter bins first),
    // classic best-fit flavor, mild weight.
    score += 0.05 * (bin_capacity as f64 - bin_residual as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when next item exactly fills the post-residual (2-step lookahead match).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-item pairing
        } else if next_item_size <= post_residual {
            score -= 8.0; // next item still fits after this placement
        } else {
            score += 12.0; // next item won't fit here; keep larger residual bins free
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor),
    // penalize leaving this bin far above the mean.
    let resid_f = post_residual as f64;
    score += (resid_f - mean_residual).max(0.0) * 0.5;
    score -= (mean_residual - resid_f).max(0.0) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Baseline penalty: opening a new bin wastes the residual left behind elsewhere.
        score += 30.0;
        // But if this item leaves a huge residual in any existing bin (poor fit),
        // a fresh bin becomes attractive.
        if post_residual > bin_capacity / 2 {
            score -= 35.0;
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
        // If many bins already fit the item, no need for a new one.
        score += fitting_bins_count as f64 * 6.0;
    }

    // Mild penalty for creating tiny unusable slivers.
    if resid_f > 0.0 && resid_f < 10.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (waste term superlinear).
    let frac_used = item_size as f64 / bin_residual as f64;
    score -= 12.0 * frac_used * frac_used;

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Mild bonus if post-residual remains usable for the next item.
            let next_fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * next_fit_ratio;
        } else {
            // Penalize leaving residuals that the next item cannot use at all.
            score += 6.0;
        }
    }

    // Penalize creating tiny unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin when good alternatives exist,
    // but allow it when existing bins would be badly fragmented.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        // Opening new bins is costlier early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - 0.5 * progress);
        // If mean residual across open bins is large, we should use them instead.
        if mean_residual > item_size as f64 {
            score += 0.3 * mean_residual;
        }
        // Many open bins with slack: discourage yet another bin.
        score += 2.0 * open_f.sqrt();
    } else {
        // Reward filling existing bins, more so when the bin is already well-used.
        let used = (bin_capacity - bin_residual) as f64;
        score -= 0.05 * used;
    }

    // Slight preference for bins whose residual is close to the item (tightness).
    score -= 8.0 * (1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with progress
    let t = pr / cap;
    let g = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    let coupling = t * t * (1.0 - t) * (1.0 + g);

    // Reward tight fits (small post_residual) more strongly as stream advances
    let mut score = base - 6.0 * coupling * cap - progress * (cap - pr) * 0.15;

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.5 + progress);
        } else {
            // smooth reward when lookahead also fits
            score -= (pr - nx).min(cap * 0.5) * 0.1 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // Favor bins tighter than average residual
    score += (mean_residual - bin_residual as f64) * 0.1;

    // Slight bias against opening a new bin
    if bin_residual == bin_capacity {
        score += 4.0 + progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: strong best-fit preference with quadratic penalty on waste.
    score += (post_residual as f64) * (post_residual as f64) / (4.0 * cap);

    // Harmonic class of the residual after placement: residuals divisible
    // into common small item sizes (mod classes) are more reusable.
    let pr = post_residual;
    let mut reusability = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { reusability += 6.0; }
        else if pr % 5 == 0 { reusability += 3.0; }
        else if pr % 20 == 0 { reusability += 8.0; }
        if pr % 25 == 0 { reusability += 4.0; }
        if pr % 50 == 0 { reusability += 5.0; }
    }
    score -= reusability;

    // Perfect fit: huge reward.
    if pr == 0 { score -= 1000.0; }

    // Dead-space thresholds: residuals too small for the minimum item (1..100
    // interface, but typical small items) get penalized via integer division.
    let dead_zone = pr / 30; // 0..3 integer division threshold
    score += dead_zone as f64 * 4.0;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            score -= 15.0 + (pr - next_item_size) as f64 * 0.1;
        } else {
            // next item cannot use this residual: mild penalty proportional
            // to how much leftover is stranded.
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a dynamic barrier so we only
    // open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let barrier = 60.0 + 40.0 * (1.0 - progress) + (open_bins_count as f64) * 2.0;
        score += barrier;
        // Very large items (near full capacity) justify a fresh bin.
        if item_size * 10 >= (bin_capacity as u32) * 9 {
            score -= 55.0;
        }
    }

    // Slight preference to fill bins whose residual is below the mean
    // (concentrate waste in few bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small gap: only valuable if the lookahead item can use it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 25.0;
        }
    } else if post_residual == 0 {
        // Perfect fill is ideal.
        score -= 50.0;
    } else {
        // Usable gap: reward proportional closeness of lookahead fit.
        if next_item_size > 0 && next_item_size <= post_residual {
            let fit_quality = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 20.0 * fit_quality;
        }
    }

    // Penalize leaving a gap that is just above the item size band edges
    // (awkward residuals in (60, 70) etc. are less reusable).
    if post_residual > 60 && post_residual < 70 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones
    // and avoid opening new bins unless the fit is excellent.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no existing bin fits well.
    if bin_residual == bin_capacity {
        if post_residual >= 50 {
            score += 20.0 + pressure * 0.5;
        } else {
            score += 5.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can serve the large lookahead too
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Mean-residual coupling: if this bin is far below the mean residual it
    // is already "cramped"; filling it further is good.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit
    let fit_gap = (post_residual as f64) / bin_capacity as f64;
    score -= (1.0 - fit_gap) * 30.0;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin fully consumed over two steps
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leaving a large unusable gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: heavily favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless it enables a perfect
    // two-item chain (item + next) or existing fits are terrible
    if bin_residual == bin_capacity {
        let base = 45.0 + (open_bins_count as f64).sqrt() * 5.0;
        let chain_bonus = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            (bin_capacity - item_size - next_item_size) as f64
        } else {
            0.0
        };
        score = base + chain_bonus * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 3.0 * fit_ratio * fit_ratio * (bin_residual as f64);

    // Penalize large dead space quadratically
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.5) * 0.05;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for wasting residual
        score += (post_residual as f64) * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer opening a new bin only if existing fits are loose
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin; make it attractive only when mean residual is fragmented
        score = (bin_capacity as f64) * 0.6;
        if mean_residual > 30.0 && fitting_bins_count > 0 {
            score += 20.0; // existing bins have room; don't open new
        }
        if mean_residual < 12.0 {
            score -= 10.0; // open bins nearly full; new bin good
        }
        // early in stream, allow more bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Penalize spreading across many open bins when residuals are small
    let open_f = open_bins_count as f64;
    score += (open_f / (open_f + 10.0)) * (mean_residual - post_residual as f64).abs() * 0.1;

    // Mild time-varying conservatism: late in stream, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Reward tight fits: quadratic bonus as post_residual approaches zero.
    let tightness = 1.0 - (post / cap);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that grows with stream progress (late waste is costlier).
    let waste_frac = post / cap;
    score += 25.0 * waste_frac * waste_frac * (0.5 + progress);

    // Perfect-fit style reward when item nearly fills the bin.
    let fill = item_size as f64 / bin_residual as f64;
    if bin_residual > 0 {
        score -= 30.0 * fill * fill;
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Post-residual too small for next item: penalize proportionally.
            score += 10.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0 * (0.5 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        // Slight penalty spread when many bins compete: prefer best-fit resolution.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: it should only win when open bins are very full / poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, eased early in the stream.
        score = cap * (0.9 - 0.25 * progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        if mean_residual > 0.0 && post_residual as f64 <= mean_residual {
            score += 8.0; // existing bins already have comparable residuals
        }
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter).
    score += 0.15 * (post - mean_residual);

    // Small penalty for proliferating open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "band" of leftover space we create.
    // Classes (mod 10 style granularity scaled to capacity 100):
    // class 0: post_residual == 0 (perfect fit) -> strong reward
    // class 1: post_residual <= 10 (nearly full) -> reward
    // class 2: post_residual in (10, 25] -> mild penalty (awkward dead zone)
    // class 3: post_residual in (25, 50] -> larger penalty
    // class 4: post_residual > 50 -> keep flexible, moderate score
    let pr = post_residual;
    let cap = bin_capacity as f64;

    if pr == 0 {
        score -= 60.0; // perfect fit: always take it
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 25 {
        score += 8.0;
    } else if pr <= 50 {
        score += 18.0;
    } else {
        // large leftover: value depends on whether future items can use it
        score += 5.0;
    }

    // Integer-division threshold: post_residual bucket by /10 (harmonic decile).
    let decile = pr / 10;
    match decile {
        0 => score -= 10.0,
        1 => score -= 5.0,
        2 | 3 => score += 6.0,
        4 => score += 10.0,
        _ => {}
    }

    // Lookahead coupling: if the next item exactly fills the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 6.0; // next item still fits: keeps bin chain alive
        } else {
            // next item cannot use this residual: penalize wasted capacity
            let waste = (next_item_size - pr) as f64;
            score += (waste * 0.3).min(15.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // tie-break among multiple fitting bins: prefer tightest fit,
        // which post_residual already encodes; small bonus for competition
        score += 2.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    // (mean residual low relative to item size) or late in the stream
    // where consolidation has less value.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if crowded {
            score -= 5.0;
        } else {
            score += 30.0; // discourage opening new bins when existing ones fit well
        }
        if progress > 0.8 {
            score += 10.0; // late stream: avoid proliferating bins
        }
        // a fresh bin always has residual = capacity; neutralize the base
        // post_residual term so it doesn't dominate
        score -= (cap - cap) ; // no-op placeholder, base term already = cap
        score = score - cap + 40.0; // recalibrate baseline for empty bin
    }

    // Mean residual context: if this bin is much tighter than average,
    // filling it is efficient.
    let tightness = (mean_residual - bin_residual as f64).max(0.0);
    score -= (tightness * 0.2).min(10.0);

    // Penalize very large open-bin fleets slightly to encourage consolidation.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the smallest
    // item (1..10) are pure waste; penalize them quadratically.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        let gap = (dead_threshold - post_residual) as f64;
        score += 40.0 + gap * gap * 2.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Favor bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < dead_threshold {
            score -= 25.0; // chains into a near-perfect follow-up
        } else {
            score -= 8.0;
        }
    }
    // Penalize leaving a gap that the known next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; a new-bin call gets penalized proportionally.
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: baseline so it only wins when
        // existing fits are truly bad.
        score = (bin_capacity - item_size) as f64 * 0.5
            + open_bins_count as f64 * 6.0
            + 15.0;
        // Late in the stream, opening new bins is cheaper than hoarding
        // dead space in nearly-full bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        // Slight pressure to fill existing bins when many are open.
        score += open_bins_count as f64 * 0.5;
        // Prefer bins below mean residual (they need filling more).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // 2-step lookahead: strongly reward exact or near-exact match for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post - nxt;
        score -= 30.0 * (1.0 - slack / cap);
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step pairing
        }
    } else if next_item_size > 0 {
        // next item won't fit here: penalize proportionally to the dead space created
        score += 0.3 * post;
    }

    // Reward tight fits relative to mean residual across open bins.
    if post < mean_residual {
        score -= (mean_residual - post).min(25.0);
    } else {
        score += 0.2 * (post - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * (1.0 - post / cap);
    }

    // New-bin candidate: only attractive early in the stream or when few bins are open,
    // and when the current fit is loose.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        let fit_quality = 1.0 - (item_size as f64 / cap);
        score -= 5.0 + 20.0 * fit_quality / openness + 10.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate into fewer bins.
    score += 0.5 * open_bins_count as f64 * (post / cap);

    score
}
